#[test]
fn dynamic_history_offset_negative_is_na() {
    // A negative offset refers to a bar that does not exist, so the read is na
    // (assumed, consistent with the out-of-range rule). `n = 0 - 1` = -1.
    let program = compile("indicator(\"D\")\nn = 0 - 1\ny = close[n]\nplot(y)\n");
    let outcome = run(
        &program,
        &data_from_close(&[10.0, 20.0, 30.0]),
        &RunOptions::default(),
    );
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    assert_eq!(floats(&outcome.plots[0].values), vec![None, None, None]);
}

#[test]
fn dynamic_history_offset_na_offset_is_na() {
    // An `na` int offset reads `na`. `close[1]` is na on bar 0, so
    // `int(close[1] - close)` — no: keep it simple with an int series that is
    // na on bar 0. `bar_index - bar_index[1]` is na on bar 0 (na prior) and 1
    // thereafter; on bar 0 the offset is na → na; from bar 1 the offset is 1.
    let program =
        compile("indicator(\"D\")\nn = bar_index - bar_index[1]\ny = close[n]\nplot(y)\n");
    let outcome = run(
        &program,
        &data_from_close(&[10.0, 20.0, 30.0]),
        &RunOptions::default(),
    );
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    // Bar 0: offset na → na. Bar 1: offset 1 → close[1] = 10. Bar 2: offset 1
    // → close[1] = 20.
    assert_eq!(
        floats(&outcome.plots[0].values),
        vec![None, Some(10.0), Some(20.0)]
    );
}

