#[test]
fn ta_sma_preserves_order_and_missing_values_across_ring_wraps() {
    // Cancellation makes reassociation observable. Lengths on both sides of
    // ring-size boundaries exercise windows occupying one and two slices.
    let mut close: Vec<f64> = (0..1300)
        .map(|bar| [1e16, 1.0, -1e16, 3.0, -0.0, 2.0, -2.0][bar % 7])
        .collect();
    close[511] = f64::NAN;
    close[1024] = f64::NAN;
    for length in [1, 2, 3, 7, 16, 31, 300] {
        let program = compile(&format!(
            "indicator(\"Ordered SMA\")\nplot(ta.sma(close, {length}))\n"
        ));
        let outcome = run(&program, &data_from_close(&close), &RunOptions::default());
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        for (bar, actual) in outcome.plots[0].values.iter().enumerate() {
            let observations = close[..=bar]
                .iter()
                .copied()
                .filter(|value| !value.is_nan())
                .collect::<Vec<_>>();
            if observations.len() < length {
                assert_eq!(actual, &Value::Na);
                continue;
            }
            let window = &observations[observations.len() - length..];
            let expected = window.iter().fold(0.0, |sum, value| sum + value) / length as f64;
            let Value::Float(actual) = actual else {
                panic!("missing SMA at length {length}, bar {bar}");
            };
            assert_eq!(
                actual.to_bits(),
                expected.to_bits(),
                "length {length}, bar {bar}"
            );
        }
    }
}

#[test]
