#[test]
fn int_literals_above_2_pow_53_are_exact() {
    // 2^53 + 1 is odd; before the AST carried exact i64 literals it rounded
    // through f64 to 2^53 and came out even.
    let program = compile("indicator(\"Big\")\nplot(9007199254740993 % 2)\n");
    let outcome = run(&program, &data_from_close(&[1.0]), &RunOptions::default());
    assert!(outcome.errors.is_empty());
    assert_eq!(floats(&outcome.plots[0].values), vec![Some(1.0)]);

    let program = compile("indicator(\"Big\")\nplot(9007199254740993 - 9007199254740992)\n");
    let outcome = run(&program, &data_from_close(&[1.0]), &RunOptions::default());
    assert_eq!(floats(&outcome.plots[0].values), vec![Some(1.0)]);
}

#[test]
fn run_rejects_empty_functions_program_without_panicking() {
    let mut program = compile("indicator(\"E\")\nplot(close)\n");
    program.functions.clear();
    let outcome = run(&program, &data_from_close(&[1.0]), &RunOptions::default());
    assert_eq!(outcome.errors.len(), 1);
    assert_eq!(outcome.errors[0].kind, RuntimeErrorKind::InvalidProgram);
    assert_eq!(outcome.bars_executed, 0);
}

#[test]
fn cumulative_instruction_budget_is_exact_across_bars() {
    let program = compile("indicator(\"B\")\nplot(close)\n");
    let data = data_from_close(&[1.0, 2.0]);
    let total = program.main().code.len() as u64 * data.bars() as u64;
    let exact = RunOptions {
        max_instructions_per_run: total,
        ..RunOptions::default()
    };
    let outcome = run(&program, &data, &exact);
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    assert_eq!(outcome.bars_executed, 2);

    let over = RunOptions {
        max_instructions_per_run: total - 1,
        ..RunOptions::default()
    };
    let outcome = run(&program, &data, &over);
    assert_eq!(outcome.bars_executed, 1);
    assert_eq!(outcome.errors.len(), 1);
    assert_eq!(
        outcome.errors[0].kind,
        RuntimeErrorKind::RunInstructionLimitExceeded
    );
    assert_eq!(
        outcome.errors[0].instruction_offset,
        Some(program.main().code.len() as u32 - 1)
    );
}

#[test]
fn vm_preallocation_budget_accepts_exact_limit_and_rejects_one_byte_over() {
    let program = compile("indicator(\"M\")\nx = close\nplot(x)\n");
    let data = data_from_close(&[1.0, 2.0, 3.0]);
    let defaults = RunOptions::default();
    let ring = program.history_ring() as usize;
    let exact = crate::vm_preallocation_bytes(&program, &data, &defaults, data.bars(), ring)
        .expect("bounded state arithmetic");

    let allowed = RunOptions {
        max_vm_bytes_per_run: exact,
        ..defaults.clone()
    };
    assert!(run(&program, &data, &allowed).errors.is_empty());

    let refused = RunOptions {
        max_vm_bytes_per_run: exact - 1,
        ..defaults
    };
    let outcome = run(&program, &data, &refused);
    assert_eq!(outcome.bars_executed, 0);
    assert_eq!(
        outcome.errors[0].kind,
        RuntimeErrorKind::VmMemoryLimitExceeded
    );
    assert_eq!(outcome.errors[0].bar_index, None);
}

