#[test]
fn crossover_crossunder_cross_truth_table_including_na_edges() {
    // close crosses a flat open at 2. The na bar (bar 3) breaks the chain:
    // a cross immediately after it is NOT reported (the previous value is
    // unknown; assumed rule — plain false, never na).
    let program = compile(
        "indicator(\"X\")\nplot(ta.crossover(close, open) ? 1 : 0)\nplot(ta.crossunder(close, open) ? 1 : 0)\nplot(ta.cross(close, open) ? 1 : 0)\n",
    );
    let close = vec![1.0, 3.0, 3.0, f64::NAN, 5.0, 1.0];
    let data = MarketData {
        open: vec![2.0; 6],
        high: close.clone(),
        low: close.clone(),
        close,
        volume: vec![1.0; 6],
        ..MarketData::default()
    };
    let outcome = run(&program, &data, &RunOptions::default());
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    let ints = |i: usize| floats(&outcome.plots[i].values);
    // bar1: 1→3 over 2 → crossover. bar2: stays above → nothing.
    // bar3: na → nothing. bar4: above, but the previous value was na →
    // nothing. bar5: 5→1 under 2 → crossunder.
    let f = Some(0.0);
    let t = Some(1.0);
    assert_eq!(ints(0), vec![f, t, f, f, f, f]);
    assert_eq!(ints(1), vec![f, f, f, f, f, t]);
    assert_eq!(ints(2), vec![f, t, f, f, f, t]);
}

