#[test]
fn calendar_series_match_hand_computed_utc_date() {
    // 2021-03-15T14:30:45Z. epoch ms worked out from the calendar date.
    let program = compile(
        "indicator(\"C\")\nplot(year)\nplot(month)\nplot(dayofmonth)\nplot(hour)\nplot(minute)\nplot(second)\nplot(dayofweek)\n",
    );
    let mut data = data_from_close(&[1.0]);
    data.time = vec![1_615_818_645_000];
    // Default syminfo timezone is UTC.
    let outcome = run(&program, &data, &RunOptions::default());
    assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
    assert_eq!(floats(&outcome.plots[0].values), vec![Some(2021.0)]); // year
    assert_eq!(floats(&outcome.plots[1].values), vec![Some(3.0)]); // month
    assert_eq!(floats(&outcome.plots[2].values), vec![Some(15.0)]); // dayofmonth
    assert_eq!(floats(&outcome.plots[3].values), vec![Some(14.0)]); // hour
    assert_eq!(floats(&outcome.plots[4].values), vec![Some(30.0)]); // minute
    assert_eq!(floats(&outcome.plots[5].values), vec![Some(45.0)]); // second
                                                                    // 2021-03-15 is a Monday; Pine numbers Sunday = 1, so Monday = 2.
    assert_eq!(floats(&outcome.plots[6].values), vec![Some(2.0)]); // dayofweek
}

#[test]
fn time_tradingday_fallback_encodes_exchange_calendar_date_at_utc_midnight() {
    // Without a host tradingDay lane, the deterministic boundary is the bar's
    // exchange-local calendar date encoded at 00:00 UTC. Exact overnight
    // session identity requires the host-supplied lane.
    let program = compile("indicator(\"T\")\nplot(time_tradingday)\n");
    // 2021-03-15T14:30:45Z. UTC midnight of that day is 2021-03-15T00:00:00Z.
    let mut data = data_from_close(&[1.0]);
    data.time = vec![1_615_818_645_000];
    let utc = run(&program, &data, &RunOptions::default());
    assert!(utc.errors.is_empty(), "{:?}", utc.errors);
    assert_eq!(
        floats(&utc.plots[0].values),
        vec![Some(1_615_766_400_000.0)]
    );
    // Under UTC-5 this instant still belongs to the local 2021-03-15 calendar
    // date, which Pine represents as 2021-03-15T00:00:00Z rather than the UTC
    // instant when local midnight occurred.
    let mut data5 = data_from_close(&[1.0]);
    data5.time = vec![1_615_818_645_000];
    data5.syminfo.timezone = "UTC-5".to_string();
    let off = run(&program, &data5, &RunOptions::default());
    assert!(off.errors.is_empty(), "{:?}", off.errors);
    assert_eq!(
        floats(&off.plots[0].values),
        vec![Some(1_615_766_400_000.0)]
    );
    assert_eq!(1_615_766_400_000_i64 % crate::MS_PER_DAY, 0);
}

#[test]
fn host_trading_day_lane_is_authoritative_across_an_overnight_session() {
    let program = compile("indicator(\"T\")\nplot(time_tradingday)\n");
    let mut data = data_from_close(&[1.0, 2.0, 3.0]);
    data.timeframe = "60".to_string();
    data.syminfo.kind = "forex".to_string();
    data.syminfo.session = "1700-1700".to_string();
    // Bar 1 crosses UTC midnight, but both bars belong to the host's same
    // symbol trading day. Bar 2 begins the next host-supplied trading day.
    data.time = vec![1_700_604_000_000, 1_700_607_600_000, 1_700_694_000_000];
    data.trading_day = vec![1_700_539_200_000, 1_700_539_200_000, 1_700_625_600_000];
    let outcome = run(&program, &data, &RunOptions::default());
    assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
    assert_eq!(
        floats(&outcome.plots[0].values),
        vec![
            Some(1_700_539_200_000.0),
            Some(1_700_539_200_000.0),
            Some(1_700_625_600_000.0)
        ]
    );

    let wire = serde_json::to_value(&data).expect("serialize MarketData");
    assert_eq!(
        wire["tradingDay"],
        serde_json::json!([
            1_700_539_200_000_i64,
            1_700_539_200_000_i64,
            1_700_625_600_000_i64
        ])
    );
}

