#[test]
fn timezone_offset_parsing_matrix() {
    use crate::timezone_offset_seconds;
    assert_eq!(timezone_offset_seconds("UTC"), 0);
    assert_eq!(timezone_offset_seconds("GMT"), 0);
    assert_eq!(timezone_offset_seconds("UTC-5"), -5 * 3600);
    assert_eq!(timezone_offset_seconds("UTC+05:30"), 5 * 3600 + 30 * 60);
    assert_eq!(timezone_offset_seconds("GMT+0530"), 5 * 3600 + 30 * 60);
    assert_eq!(timezone_offset_seconds("UTC+00"), 0);
    // Full IANA names are unsupported: fall back to UTC.
    assert_eq!(timezone_offset_seconds("America/New_York"), 0);
    assert_eq!(timezone_offset_seconds(""), 0);
    // Multi-byte garbage after the sign must fall back to UTC, not panic:
    // the "HHMM" split used to byte-slice at 2, which traps on a script
    // like `timestamp("GMT+€€€€", ...)` (4 chars, 12 bytes; and "1€" makes
    // byte 2 a non-boundary). A panic here poisons the wasm instance.
    assert_eq!(timezone_offset_seconds("GMT+€€€€"), 0);
    assert_eq!(timezone_offset_seconds("UTC-€€€€"), 0);
    assert_eq!(timezone_offset_seconds("GMT+1€"), 0);
    assert_eq!(timezone_offset_seconds("GMT+05:€"), 0);
}

