#[test]
fn strategy_with_realtime_ticks_executes_against_the_appended_feed() {
    // Strategies share the realtime rollback model with indicators while the
    // broker book persists across ticks.  The final close must be read from the
    // VM-owned feed because this tick appends bar 2 beyond the caller's two-bar
    // historical input.
    let program = compile(
        "//@version=6\nstrategy(\"S\")\nstrategy.entry(\"L\", strategy.long)\nplot(close)\n",
    );
    let data = data_from_close(&[10.0, 11.0]);
    let options = RunOptions {
        realtime: Some(RealtimeSim {
            ticks: vec![tick(2, 12.0, true)],
        }),
        ..RunOptions::default()
    };
    let outcome = run(&program, &data, &options);
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    assert_eq!(outcome.bars_executed, 3);
    assert_eq!(
        floats(&outcome.plots[0].values),
        vec![Some(10.0), Some(11.0), Some(12.0)]
    );
    let strategy = outcome.strategy.expect("strategy outcome");
    assert_eq!(strategy.position.size, 1.0);
    assert_eq!(strategy.open_profit, 1.0);
}

#[test]
fn request_security_memo_is_invalidated_on_a_realtime_appended_bar() {
    // Regression: request.security memoizes the back-mapped
    // HTF series over the historical feed length. A realtime tick that APPENDS a
    // bar pushes self.bar past that frozen length, so without invalidation the
    // appended bar reads `na`. Clearing the memo when the feed changes lets it
    // recompute over the current data, so the appended bar repeats the last
    // completed weekly close (gaps_off) just like the prior historical bar.
    let program = compile(
        "//@version=6\nindicator(\"S\")\nplot(request.security(syminfo.tickerid, \"1W\", close))\n",
    );
    // 7 daily bars (closes 100..106): the first weekly bucket closes at bar 6.
    let data = monday_daily_closes(&[100.0, 101.0, 102.0, 103.0, 104.0, 105.0, 106.0]);
    let mut appended = tick(7, 200.0, true);
    appended.time = data.time_at(6) + crate::MS_PER_DAY;
    let options = RunOptions {
        realtime: Some(RealtimeSim {
            ticks: vec![appended],
        }),
        ..RunOptions::default()
    };
    let outcome = run(&program, &data, &options);
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    let vals = floats(&outcome.plots[0].values);
    // The last historical bar (6) closes the first weekly bucket (value 106).
    assert_eq!(vals[6], Some(106.0), "historical weekly bucket close");
    // The appended bar (7) starts a new weekly bucket whose close is the tick's
    // 200; the memo must recompute over the extended feed to surface it. Without
    // invalidation, self.bar (7) exceeds the frozen memo length and reads `na`.
    assert_eq!(
        vals[7],
        Some(200.0),
        "appended bar's weekly value, not na (memo must be invalidated)"
    );
}

