/// Determinism: the same tick script run twice produces identical outputs.
#[test]
fn realtime_is_deterministic() {
    let program = compile(
        "indicator(\"D\")\n\
         varip int vp = 0\n\
         vp := vp + 1\n\
         plot(ta.sma(close, 3))\n\
         plot(vp)\n",
    );
    let data = data_from_close(&[10.0, 20.0, 30.0]);
    let mk_options = || RunOptions {
        realtime: Some(RealtimeSim {
            ticks: vec![
                tick(3, 40.0, false),
                tick(3, 44.0, false),
                tick(3, 42.0, true),
            ],
        }),
        ..RunOptions::default()
    };
    let a = run(&program, &data, &mk_options());
    let b = run(&program, &data, &mk_options());
    assert_eq!(a, b);
    assert!(a.errors.is_empty(), "errors: {:?}", a.errors);
}

/// Plots commit only bar-close values: a re-run realtime bar's committed plot
/// is the value from its closing tick, not an intermediate tick.
#[test]
fn plots_commit_only_bar_close_values() {
    let program = compile("indicator(\"P\")\nplot(close)\n");
    let data = data_from_close(&[10.0]);
    let options = RunOptions {
        realtime_trace: true,
        realtime: Some(RealtimeSim {
            ticks: vec![
                tick(1, 20.0, false),
                tick(1, 99.0, false),
                tick(1, 30.0, true), // closing value wins
            ],
        }),
        ..RunOptions::default()
    };
    let outcome = run(&program, &data, &options);
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    assert_eq!(outcome.bars_executed, 2);
    // Committed: historical bar 0 = 10, realtime bar 1 = 30 (the close tick).
    assert_eq!(
        floats(&outcome.plots[0].values),
        vec![Some(10.0), Some(30.0)]
    );
    // Trace shows the intrabar wiggle 20 -> 99 -> 30.
    let trace = outcome.realtime_trace.expect("trace");
    assert_eq!(
        trace.iter().map(|t| floats(&t.values)).collect::<Vec<_>>(),
        vec![vec![Some(20.0)], vec![Some(99.0)], vec![Some(30.0)]]
    );
}

/// A tick targeting an invalid bar index is a structured error, not a panic.
#[test]
fn realtime_tick_bad_index_is_structured_error() {
    let program = compile("indicator(\"E\")\nplot(close)\n");
    let data = data_from_close(&[10.0, 11.0]);
    let options = RunOptions {
        // bar 5 is neither the last committed bar (1) nor the append index (2).
        realtime: Some(RealtimeSim {
            ticks: vec![tick(5, 12.0, true)],
        }),
        ..RunOptions::default()
    };
    let outcome = run(&program, &data, &options);
    assert_eq!(outcome.errors.len(), 1);
    assert_eq!(outcome.errors[0].kind, RuntimeErrorKind::InvalidProgram);
    // Historical bars still executed and committed before the bad tick.
    assert_eq!(outcome.bars_executed, 2);
}

/// A realtime bar stays open until its `is_bar_close` tick commits it. A first
/// tick on another bar while one is open would abandon the open bar without
/// committing it: the one-shot result then truncated to `bars_executed` and
/// dropped the *later* bar's committed close instead. It is refused instead.
#[test]
fn realtime_tick_cannot_open_another_bar_while_one_is_open() {
    let program = compile("indicator(\"E\")\nplot(close)\n");
    let data = data_from_close(&[10.0, 11.0]);
    let options = RunOptions {
        // Bar 2 is appended and left open; bar 3 must not append over it.
        realtime: Some(RealtimeSim {
            ticks: vec![tick(2, 12.0, false), tick(3, 13.0, true)],
        }),
        ..RunOptions::default()
    };
    let outcome = run(&program, &data, &options);
    assert_eq!(outcome.errors.len(), 1, "{:?}", outcome.errors);
    assert_eq!(outcome.errors[0].kind, RuntimeErrorKind::InvalidProgram);
    assert_eq!(outcome.errors[0].bar_index, Some(3));
    assert!(
        outcome.errors[0].message.contains("bar 2 is still open"),
        "{}",
        outcome.errors[0].message
    );
    // Only the two historical bars were ever committed.
    assert_eq!(outcome.bars_executed, 2);
    assert_eq!(
        floats(&outcome.plots[0].values),
        vec![Some(10.0), Some(11.0)]
    );

    // A re-run of the last committed bar is open in the same way.
    let rerun = run(
        &program,
        &data,
        &RunOptions {
            realtime: Some(RealtimeSim {
                ticks: vec![tick(1, 12.0, false), tick(2, 13.0, true)],
            }),
            ..RunOptions::default()
        },
    );
    assert_eq!(rerun.errors.len(), 1, "{:?}", rerun.errors);
    assert_eq!(rerun.errors[0].kind, RuntimeErrorKind::InvalidProgram);
    assert_eq!(rerun.bars_executed, 2);

    // The persistent session refuses the same sequence across two advances,
    // leaving the open bar's tick as the last accepted state.
    let mut session =
        IncrementalSession::new(&program, &data, &RunOptions::default()).expect("session");
    let opened = session.advance(&[tick(2, 12.0, false)]);
    assert!(opened.errors.is_empty(), "{:?}", opened.errors);
    let refused = session.advance(&[tick(3, 13.0, true)]);
    assert_eq!(refused.errors.len(), 1, "{:?}", refused.errors);
    assert_eq!(refused.errors[0].kind, RuntimeErrorKind::InvalidProgram);
    assert_eq!(refused.bars_executed, 2);

    // Closing the open bar first and then appending stays legal.
    let legal = run(
        &program,
        &data,
        &RunOptions {
            realtime: Some(RealtimeSim {
                ticks: vec![
                    tick(2, 12.0, false),
                    tick(2, 12.5, true),
                    tick(3, 13.0, true),
                ],
            }),
            ..RunOptions::default()
        },
    );
    assert!(legal.errors.is_empty(), "{:?}", legal.errors);
    assert_eq!(legal.bars_executed, 4);
    assert_eq!(
        floats(&legal.plots[0].values),
        vec![Some(10.0), Some(11.0), Some(12.5), Some(13.0)]
    );
}

/// varip persists across ticks but a plain var rolls back — verified via the
/// per-tick trace on a re-run (non-appended) realtime bar.
#[test]
fn varip_persists_var_rolls_back_on_rerun_bar() {
    let program = compile(
        "indicator(\"R\")\n\
         var int vc = 0\n\
         varip int vp = 0\n\
         vc := vc + 1\n\
         vp := vp + 1\n\
         plot(vc)\n\
         plot(vp)\n",
    );
    // One historical bar (vc=1, vp=1), then re-run bar 0 three times.
    let data = data_from_close(&[10.0]);
    let options = RunOptions {
        realtime_trace: true,
        realtime: Some(RealtimeSim {
            ticks: vec![
                tick(0, 11.0, false),
                tick(0, 12.0, false),
                tick(0, 13.0, true),
            ],
        }),
        ..RunOptions::default()
    };
    let outcome = run(&program, &data, &options);
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    let trace = outcome.realtime_trace.expect("trace");
    // var counter (plot 0): rolls back to bar-start each tick, so it is 2 on
    // every tick (bar-start snapshot had vc=1, +1 each execution).
    let vc: Vec<_> = trace.iter().map(|t| floats(&t.values)[0]).collect();
    assert_eq!(vc, vec![Some(2.0), Some(2.0), Some(2.0)]);
    // varip counter (plot 1): persists, so 2, 3, 4 across the three ticks.
    let vp: Vec<_> = trace.iter().map(|t| floats(&t.values)[1]).collect();
    assert_eq!(vp, vec![Some(2.0), Some(3.0), Some(4.0)]);
}

/// varip must keep its session value when the *last committed bar* (bar > 0)
/// is re-run: the tick-open carry-forward must not re-carry a varip slot from
/// the previous bar and clobber it. (Regression: the
/// test above only re-ran bar 0, where carry-forward is skipped entirely.)
#[test]
fn varip_survives_a_rerun_of_the_last_committed_bar() {
    let program = compile(
        "indicator(\"R\")\n\
         varip int vp = 0\n\
         vp := vp + 1\n\
         plot(vp)\n",
    );
    // Two historical bars commit vp = 1 (bar 0) then 2 (bar 1). Re-run bar 1
    // with two ticks: varip continues from the committed 2 → 3, 4 (it must
    // NOT reset to the bar-0 value of 1 via carry-forward).
    let data = data_from_close(&[10.0, 11.0]);
    let options = RunOptions {
        realtime_trace: true,
        realtime: Some(RealtimeSim {
            ticks: vec![tick(1, 20.0, false), tick(1, 21.0, true)],
        }),
        ..RunOptions::default()
    };
    let outcome = run(&program, &data, &options);
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    let trace = outcome.realtime_trace.expect("trace");
    let vp: Vec<_> = trace.iter().map(|t| floats(&t.values)[0]).collect();
    assert_eq!(
        vp,
        vec![Some(3.0), Some(4.0)],
        "varip must continue from the committed 2"
    );
    // The committed history is the final (bar-close) value: 4.
    assert_eq!(floats(&outcome.plots[0].values), vec![Some(1.0), Some(4.0)]);
}

/// With no history reads the ring is at its floor of two cells. Re-running
/// the last committed bar must still carry `var` forward from the previous
/// bar's cell, not from the cell the committed run left behind; a one-cell
/// ring would alias the two and count the committed bar twice.
#[test]
fn var_rerun_of_last_committed_bar_on_the_two_cell_floor() {
    let program = compile(
        "indicator(\"R\")\n\
         var int vc = 0\n\
         vc := vc + 1\n\
         plot(vc)\n",
    );
    assert_eq!(program.history_ring(), 2);
    let data = data_from_close(&[10.0, 11.0]);
    let options = RunOptions {
        realtime_trace: true,
        realtime: Some(RealtimeSim {
            ticks: vec![tick(1, 20.0, false), tick(1, 21.0, true)],
        }),
        ..RunOptions::default()
    };
    let outcome = run(&program, &data, &options);
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    let trace = outcome.realtime_trace.expect("trace");
    let vc: Vec<_> = trace.iter().map(|t| floats(&t.values)[0]).collect();
    assert_eq!(vc, vec![Some(2.0), Some(2.0)]);
    assert_eq!(floats(&outcome.plots[0].values), vec![Some(1.0), Some(2.0)]);
}

/// A collection first assigned to a `varip` slot after the bar snapshot must
/// stay live across rollback. Per-tick temporary arrays follow its allocation
/// point so stale handles would alias the first temporary on the next tick.
#[test]
fn varip_collection_survives_frontier_rollback_without_retaining_temporaries() {
    let program = compile(
        r#"indicator("R")
var array<int> padding = array.new_int(1, 55)
varip array<int> held = na
if barstate.isrealtime and barstate.isnew
    held := array.new_int(1, 111)
temporary_alias = array.new_int(1, 777)
later_temporary = array.new_int(1, 888)
float observed = 0.0
if barstate.isrealtime
    observed := array.get(held, 0)
plot(observed)
"#,
    );
    let data = data_from_close(&[10.0]);
    let options = RunOptions {
        realtime_trace: true,
        realtime: Some(RealtimeSim {
            ticks: vec![tick(1, 11.0, false), tick(1, 12.0, true)],
        }),
        ..RunOptions::default()
    };

    let outcome = run(&program, &data, &options);
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    let trace = outcome.realtime_trace.expect("trace");
    assert_eq!(
        trace
            .iter()
            .map(|sample| floats(&sample.values))
            .collect::<Vec<_>>(),
        vec![vec![Some(111.0)], vec![Some(111.0)]],
        "the held handle must survive and must not alias the next tick's temporary"
    );
    assert_eq!(
        floats(&outcome.plots[0].values),
        vec![Some(0.0), Some(111.0)]
    );

    // Inspect the real VM snapshot as well: history has a nonzero arena
    // frontier, and the first realtime `varip` allocation must receive the
    // exact next handle. A second tick must retain that handle's object.
    let mut vm = crate::Vm::new(&program, &data, &RunOptions::default()).expect("VM");
    let (mut bars_executed, history_errors) = vm.run_history();
    assert!(
        history_errors.is_empty(),
        "history errors: {history_errors:?}"
    );
    let frontier = vm.heap.arena_len();
    assert!(frontier > 0);
    let held_slot = vm
        .program
        .series_slots
        .iter()
        .position(|slot| slot.name == "held")
        .expect("held slot");
    let first_tick = vm
        .run_realtime(
            &RealtimeSim {
                ticks: vec![tick(1, 11.0, false)],
            },
            true,
            &mut bars_executed,
        )
        .expect("first realtime tick")
        .expect("trace enabled");
    assert_eq!(floats(&first_tick[0].values), vec![Some(111.0)]);
    let snapshot = vm
        .realtime_driver
        .bar_snapshot
        .as_ref()
        .expect("open-bar snapshot");
    assert_eq!(snapshot.base.heap.arena_len(), frontier);
    assert_eq!(
        vm.user_slots[held_slot][1 & vm.slot_mask],
        Value::Ref(HandleId(frontier as u32))
    );

    let second_tick = vm
        .run_realtime(
            &RealtimeSim {
                ticks: vec![tick(1, 12.0, false)],
            },
            true,
            &mut bars_executed,
        )
        .expect("second realtime tick")
        .expect("trace enabled");
    assert_eq!(floats(&second_tick[0].values), vec![Some(111.0)]);
    assert_eq!(
        vm.user_slots[held_slot][1 & vm.slot_mask],
        Value::Ref(HandleId(frontier as u32))
    );
    let Some(HeapObj::Array { items, .. }) = vm.heap.get(HandleId(frontier as u32)) else {
        panic!("varip handle must continue to name a live array")
    };
    assert_eq!(items, &[Value::Int(111)]);
}

/// Existing `var` collections roll back their object contents while the same
/// mutations through a `varip` collection persist across realtime executions.
#[test]
fn var_collection_mutation_rolls_back_while_varip_collection_mutation_persists() {
    let program = compile(
        r#"indicator("R")
var array<int> ordinary = array.new_int(1, 10)
varip array<int> intrabar = array.new_int(1, 10)
array.set(ordinary, 0, array.get(ordinary, 0) + 1)
array.set(intrabar, 0, array.get(intrabar, 0) + 1)
plot(array.get(ordinary, 0))
plot(array.get(intrabar, 0))
"#,
    );
    let data = data_from_close(&[10.0]);
    let options = RunOptions {
        realtime_trace: true,
        realtime: Some(RealtimeSim {
            ticks: vec![tick(1, 11.0, false), tick(1, 12.0, true)],
        }),
        ..RunOptions::default()
    };

    let outcome = run(&program, &data, &options);
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    let trace = outcome.realtime_trace.expect("trace");
    let ordinary: Vec<_> = trace
        .iter()
        .map(|sample| floats(&sample.values)[0])
        .collect();
    let intrabar: Vec<_> = trace
        .iter()
        .map(|sample| floats(&sample.values)[1])
        .collect();
    assert_eq!(ordinary, vec![Some(12.0), Some(12.0)]);
    assert_eq!(intrabar, vec![Some(12.0), Some(13.0)]);
}

/// Rolling back a shrunken ordinary array while preserving a newly allocated
/// varip array can make the merged live set exceed the configured cap. The VM
/// must stop with a structured limit error rather than admit an over-budget
/// heap or let a handle alias another object.
#[test]
fn varip_heap_overlay_over_budget_is_a_structured_runtime_error() {
    let program = compile(
        r#"indicator("R")
var array<int> ordinary = array.new_int(2, 1)
varip array<int> intrabar = na
if barstate.isrealtime and barstate.isnew
    array.pop(ordinary)
    intrabar := array.new_int(1, 9)
float observed = 0.0
if barstate.isrealtime
    observed := array.get(intrabar, 0)
plot(observed)
"#,
    );
    let data = data_from_close(&[10.0]);
    let options = RunOptions {
        max_collection_elements: 2,
        realtime_trace: true,
        realtime: Some(RealtimeSim {
            ticks: vec![tick(1, 11.0, false), tick(1, 12.0, true)],
        }),
        ..RunOptions::default()
    };

    let outcome = run(&program, &data, &options);
    assert_eq!(outcome.errors.len(), 1, "errors: {:?}", outcome.errors);
    assert_eq!(
        outcome.errors[0].kind,
        RuntimeErrorKind::CollectionLimitExceeded
    );
    assert!(outcome.errors[0]
        .message
        .contains("collection element limit exceeded"));
}

// ===========================================================================
// Collections (array core). Value-asserted end-to-end tests.
// ===========================================================================

/// Compile + run a program over `close` data, asserting no runtime errors, and
/// return the first plot's values as `Option<f64>`.
fn run_plot(source: &str, close: &[f64]) -> Vec<Option<f64>> {
    let program = compile(source);
    let outcome = run(&program, &data_from_close(close), &RunOptions::default());
    assert!(
        outcome.errors.is_empty(),
        "runtime errors: {:?}",
        outcome.errors
    );
    floats(&outcome.plots[0].values)
}

/// Compile + run, returning the whole outcome so the test can inspect errors
/// and `bars_executed`.
fn run_outcome(source: &str, close: &[f64], opts: &RunOptions) -> crate::RunOutcome {
    let program = compile(source);
    run(&program, &data_from_close(close), opts)
}

#[test]
fn array_push_get_size_value_asserted() {
    let src = "indicator(\"C\")\n\
               a = array.new_float(0)\n\
               array.push(a, 10.0)\n\
               array.push(a, 20.0)\n\
               plot(array.get(a, 1))\n";
    assert_eq!(run_plot(src, &[1.0]), vec![Some(20.0)]);
}

#[test]
fn array_new_float_with_size_and_initial() {
    // array.new_float(3, 7.0) -> [7,7,7]; get(2) is 7, size is 3.
    let src = "indicator(\"C\")\na = array.new_float(3, 7.0)\nplot(array.get(a, 2))\n";
    assert_eq!(run_plot(src, &[1.0]), vec![Some(7.0)]);
    let src2 = "indicator(\"C\")\na = array.new_float(3, 7.0)\nplot(array.size(a))\n";
    assert_eq!(run_plot(src2, &[1.0]), vec![Some(3.0)]);
}

#[test]
fn array_set_overwrites_element() {
    let src = "indicator(\"C\")\n\
               a = array.new_float(2, 0.0)\n\
               array.set(a, 1, 99.0)\n\
               plot(array.get(a, 1))\n";
    assert_eq!(run_plot(src, &[1.0]), vec![Some(99.0)]);
}

#[test]
fn array_pop_shift_unshift() {
    // a = [1,2,3]; unshift 0 -> [0,1,2,3]; pop -> 3, shift -> 0; plot get(0)=1.
    let src = "indicator(\"C\")\n\
               a = array.from(1.0, 2.0, 3.0)\n\
               array.unshift(a, 0.0)\n\
               x = array.pop(a)\n\
               y = array.shift(a)\n\
               plot(x + y + array.get(a, 0))\n";
    // x=3, y=0, get(0)=1 -> 4.
    assert_eq!(run_plot(src, &[1.0]), vec![Some(4.0)]);
}

#[test]
fn array_insert_remove() {
    // a=[1,3]; insert 2 at index 1 -> [1,2,3]; remove index 0 -> returns 1, a=[2,3].
    let src = "indicator(\"C\")\n\
               a = array.from(1.0, 3.0)\n\
               array.insert(a, 1, 2.0)\n\
               r = array.remove(a, 0)\n\
               plot(r + array.get(a, 0) + array.size(a))\n";
    // r=1, get(0)=2, size=2 -> 5.
    assert_eq!(run_plot(src, &[1.0]), vec![Some(5.0)]);
}

#[test]
fn array_first_last_reverse() {
    let src = "indicator(\"C\")\n\
               a = array.from(1.0, 2.0, 3.0)\n\
               array.reverse(a)\n\
               plot(array.first(a) - array.last(a))\n";
    // reversed [3,2,1]; first=3, last=1 -> 2.
    assert_eq!(run_plot(src, &[1.0]), vec![Some(2.0)]);
}

#[test]
fn array_clear_resets_size() {
    let src = "indicator(\"C\")\na = array.from(1.0, 2.0)\narray.clear(a)\nplot(array.size(a))\n";
    assert_eq!(run_plot(src, &[1.0]), vec![Some(0.0)]);
}

#[test]
fn array_includes_indexof_lastindexof() {
    // a=[5,7,5]; includes 7 -> true (plot 1), indexof 5 -> 0, lastindexof 5 -> 2.
    let inc = "indicator(\"C\")\na = array.from(5.0, 7.0, 5.0)\nplot(array.includes(a, 7.0) ? 1.0 : 0.0)\n";
    assert_eq!(run_plot(inc, &[1.0]), vec![Some(1.0)]);
    let idx = "indicator(\"C\")\na = array.from(5.0, 7.0, 5.0)\nplot(array.indexof(a, 5.0))\n";
    assert_eq!(run_plot(idx, &[1.0]), vec![Some(0.0)]);
    let last = "indicator(\"C\")\na = array.from(5.0, 7.0, 5.0)\nplot(array.lastindexof(a, 5.0))\n";
    assert_eq!(run_plot(last, &[1.0]), vec![Some(2.0)]);
    let miss = "indicator(\"C\")\na = array.from(5.0, 7.0)\nplot(array.indexof(a, 9.0))\n";
    assert_eq!(run_plot(miss, &[1.0]), vec![Some(-1.0)]);
}

#[test]
fn array_concat_appends_and_aliases_receiver() {
    // concat mutates the receiver and returns it; size grows to 4.
    let src = "indicator(\"C\")\n\
               a = array.from(1.0, 2.0)\n\
               b = array.from(3.0, 4.0)\n\
               c = array.concat(a, b)\n\
               plot(array.size(a) + array.get(c, 3))\n";
    // a mutated to size 4; c is a (alias) so get(3)=4 -> 4+4=8.
    assert_eq!(run_plot(src, &[1.0]), vec![Some(8.0)]);
}

#[test]
fn array_slice_is_shallow_copy_of_range() {
    // a=[1,2,3,4]; slice(1,3) -> [2,3]; mutating the slice does not touch a.
    let src = "indicator(\"C\")\n\
               a = array.from(1.0, 2.0, 3.0, 4.0)\n\
               s = array.slice(a, 1, 3)\n\
               array.set(s, 0, 99.0)\n\
               plot(array.get(s, 0) + array.get(a, 1) + array.size(s))\n";
    // s=[99,3], a[1] still 2, size(s)=2 -> 99+2+2=103.
    assert_eq!(run_plot(src, &[1.0]), vec![Some(103.0)]);
}

#[test]
fn array_copy_is_independent() {
    let src = "indicator(\"C\")\n\
               a = array.from(1.0, 2.0)\n\
               b = array.copy(a)\n\
               array.set(b, 0, 50.0)\n\
               plot(array.get(a, 0) + array.get(b, 0))\n";
    // a[0] still 1, b[0]=50 -> 51.
    assert_eq!(run_plot(src, &[1.0]), vec![Some(51.0)]);
}

#[test]
fn str_split_produces_string_array() {
    // str.split("a,b,c", ",") -> ["a","b","c"]: size 3, each element asserted.
    let size = "indicator(\"C\")\np = str.split(\"a,b,c\", \",\")\nplot(array.size(p))\n";
    assert_eq!(run_plot(size, &[1.0]), vec![Some(3.0)]);
    let e0 = "indicator(\"C\")\np = str.split(\"a,b,c\", \",\")\nplot(array.get(p, 0) == \"a\" ? 1.0 : 0.0)\n";
    assert_eq!(run_plot(e0, &[1.0]), vec![Some(1.0)]);
    let e1 = "indicator(\"C\")\np = str.split(\"a,b,c\", \",\")\nplot(array.get(p, 1) == \"b\" ? 1.0 : 0.0)\n";
    assert_eq!(run_plot(e1, &[1.0]), vec![Some(1.0)]);
    let e2 = "indicator(\"C\")\np = str.split(\"a,b,c\", \",\")\nplot(array.get(p, 2) == \"c\" ? 1.0 : 0.0)\n";
    assert_eq!(run_plot(e2, &[1.0]), vec![Some(1.0)]);
}

#[test]
fn str_split_trailing_separator_yields_empty_element() {
    // A trailing separator produces a trailing empty-string element: "a,b," -> ["a","b",""] (size 3).
    let size = "indicator(\"C\")\np = str.split(\"a,b,\", \",\")\nplot(array.size(p))\n";
    assert_eq!(run_plot(size, &[1.0]), vec![Some(3.0)]);
    let last = "indicator(\"C\")\np = str.split(\"a,b,\", \",\")\nplot(array.get(p, 2) == \"\" ? 1.0 : 0.0)\n";
    assert_eq!(run_plot(last, &[1.0]), vec![Some(1.0)]);
    // Consecutive separators yield an interior empty element: "a,,b" size 3.
    let mid = "indicator(\"C\")\np = str.split(\"a,,b\", \",\")\nplot(array.size(p))\n";
    assert_eq!(run_plot(mid, &[1.0]), vec![Some(3.0)]);
}

#[test]
fn str_split_empty_separator_splits_into_characters() {
    // Empty separator splits the string into individual characters.
    let size = "indicator(\"C\")\np = str.split(\"abc\", \"\")\nplot(array.size(p))\n";
    assert_eq!(run_plot(size, &[1.0]), vec![Some(3.0)]);
    let e1 = "indicator(\"C\")\np = str.split(\"abc\", \"\")\nplot(array.get(p, 1) == \"b\" ? 1.0 : 0.0)\n";
    assert_eq!(run_plot(e1, &[1.0]), vec![Some(1.0)]);
}

#[test]
fn array_fill_whole_and_range() {
    let whole = "indicator(\"C\")\na = array.new_float(3, 0.0)\narray.fill(a, 5.0)\nplot(array.get(a, 2))\n";
    assert_eq!(run_plot(whole, &[1.0]), vec![Some(5.0)]);
    // fill range [1,3): a=[0,0,0,0] -> [0,9,9,0]; get(0)=0, get(1)=9, get(3)=0.
    let range = "indicator(\"C\")\na = array.new_float(4, 0.0)\narray.fill(a, 9.0, 1, 3)\nplot(array.get(a, 1) - array.get(a, 3))\n";
    assert_eq!(run_plot(range, &[1.0]), vec![Some(9.0)]);
}

#[test]
fn array_fill_optional_bounds_use_the_evaluated_receiver_length() {
    for (call, expected) in [
        ("array.fill(a, 9.0, 1)", 27.0),
        ("array.fill(id=a, value=9.0, index_from=2)", 18.0),
        ("array.fill(index_to=2, value=9.0, id=a)", 18.0),
    ] {
        let source =
            format!("indicator(\"C\")\na = array.new_float(4, 0.0)\n{call}\nplot(array.sum(a))\n");
        assert_eq!(run_plot(&source, &[1.0]), vec![Some(expected)]);
    }
}

#[test]
fn array_fill_does_not_evaluate_its_receiver_twice_for_defaults() {
    let source = "indicator(\"C\")\na = array.new_float(4, 0.0)\ncalls = array.new_int()\nreceiver() =>\n    array.push(calls, 1)\n    a\narray.fill(id=receiver(), value=9.0, index_from=1)\nplot(array.sum(a) + array.size(calls))\n";
    assert_eq!(run_plot(source, &[1.0]), vec![Some(28.0)]);
}

#[test]
fn aliasing_two_handles_share_mutations() {
    // b = a; push through b; size(a) sees it (handle aliasing).
    let src = "indicator(\"C\")\n\
               a = array.new_float(0)\n\
               b = a\n\
               array.push(b, 1.0)\n\
               plot(array.size(a))\n";
    assert_eq!(run_plot(src, &[1.0]), vec![Some(1.0)]);
}

#[test]
fn var_array_persists_and_grows_across_bars() {
    // A var array persists; pushing once per bar grows it. size = bar count.
    let src = "indicator(\"C\")\n\
               var a = array.new_float(0)\n\
               array.push(a, close)\n\
               plot(array.size(a))\n";
    assert_eq!(
        run_plot(src, &[1.0, 2.0, 3.0]),
        vec![Some(1.0), Some(2.0), Some(3.0)]
    );
}

#[test]
fn oob_get_is_structured_error_and_aborts() {
    let src = "indicator(\"C\")\na = array.from(1.0, 2.0)\nplot(array.get(a, 5))\n";
    let outcome = run_outcome(src, &[1.0, 2.0, 3.0], &RunOptions::default());
    assert_eq!(outcome.errors.len(), 1);
    assert_eq!(
        outcome.errors[0].kind,
        RuntimeErrorKind::CollectionIndexOutOfBounds
    );
    // Aborts on the first bar; bars_executed reflects the abort.
    assert_eq!(outcome.bars_executed, 0);
}

#[test]
fn missing_array_index_returns_na_and_makes_set_inert() {
    // array.get(a, na) returns na and
    // array.set(a, na, value) leaves every existing cell unchanged.
    let plots = run_close(
        "//@version=6\nindicator(\"Missing array index\")\na = array.new_float(2, 7.0)\nint index = na\nv = array.get(a, index)\narray.set(a, index, 9.0)\nplot(na(v) ? 1 : 0)\nplot(array.get(a, 0))\n",
        &[1.0, 2.0],
    );
    assert_eq!(plots[0], vec![Some(1.0), Some(1.0)]);
    assert_eq!(plots[1], vec![Some(7.0), Some(7.0)]);
}

#[test]
fn oob_set_insert_remove_are_structured_errors() {
    for (name, src) in [
        (
            "set",
            "indicator(\"C\")\na = array.from(1.0)\narray.set(a, 3, 0.0)\nplot(close)\n",
        ),
        (
            "insert",
            "indicator(\"C\")\na = array.from(1.0)\narray.insert(a, 9, 0.0)\nplot(close)\n",
        ),
        (
            "remove",
            "indicator(\"C\")\na = array.from(1.0)\nr = array.remove(a, 9)\nplot(close)\n",
        ),
    ] {
        let outcome = run_outcome(src, &[1.0], &RunOptions::default());
        assert_eq!(outcome.errors.len(), 1, "{name}: {:?}", outcome.errors);
        assert_eq!(
            outcome.errors[0].kind,
            RuntimeErrorKind::CollectionIndexOutOfBounds,
            "{name}"
        );
    }
}

#[test]
fn pop_on_empty_is_structured_error() {
    let src = "indicator(\"C\")\na = array.new_float(0)\nx = array.pop(a)\nplot(close)\n";
    let outcome = run_outcome(src, &[1.0], &RunOptions::default());
    assert_eq!(outcome.errors.len(), 1);
    assert_eq!(
        outcome.errors[0].kind,
        RuntimeErrorKind::CollectionIndexOutOfBounds
    );
}

#[test]
fn na_method_receiver_is_structured_error() {
    // An unassigned (na) collection: calling a method on it is a runtime error.
    // A ternary that never picks the array leaves `a` na on the false branch.
    let src = "indicator(\"C\")\n\
               a = false ? array.new_float(0) : na\n\
               plot(array.size(a))\n";
    let outcome = run_outcome(src, &[1.0], &RunOptions::default());
    assert_eq!(outcome.errors.len(), 1, "{:?}", outcome.errors);
    assert_eq!(outcome.errors[0].kind, RuntimeErrorKind::NaMethodReceiver);
}

#[test]
fn na_of_array_works() {
    // na(arr) is false for a real array (1.0), true for an na one (plot via ?:).
    let src = "indicator(\"C\")\na = array.new_float(0)\nplot(na(a) ? 1.0 : 0.0)\n";
    assert_eq!(run_plot(src, &[1.0]), vec![Some(0.0)]);
}

#[test]
fn heap_limit_bomb_is_structured_error_no_hang() {
    // A loop pushing past the element cap aborts with CollectionLimitExceeded.
    let src = concat!(
        "indicator(\"C\")\n",
        "a = array.new_float(0)\n",
        "for i = 0 to 1000\n",
        "    array.push(a, 1.0)\n",
        "plot(array.size(a))\n"
    );
    let opts = RunOptions {
        max_collection_elements: 10,
        ..RunOptions::default()
    };
    let outcome = run_outcome(src, &[1.0], &opts);
    assert_eq!(outcome.errors.len(), 1, "{:?}", outcome.errors);
    assert_eq!(
        outcome.errors[0].kind,
        RuntimeErrorKind::CollectionLimitExceeded
    );
}

#[test]
fn bar_local_collections_do_not_leak_across_bars() {
    // A fresh (non-`var`) array every bar has no historical reader, so only
    // the current cell needs to remain rooted. Even a large shared history
    // ring must not turn 2,000 short-lived arrays into live collections.
    let src = concat!(
        "indicator(\"C\")\n",
        "a = array.new_float(1, 1.0)\n",
        "plot(array.size(a))\n"
    );
    let opts = RunOptions {
        max_collection_elements: 1_000,
        ..RunOptions::default()
    };
    let closes = vec![1.0; 2_000];
    let outcome = run_outcome(src, &closes, &opts);
    assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
    // Still computing the real answer, not silently dropping the array.
    assert_eq!(outcome.plots[0].values.last(), Some(&Value::Float(1.0)));
}

#[test]
fn unrelated_dynamic_window_does_not_pin_bar_local_arrays() {
    let src = concat!(
        "//@version=6\nindicator(\"GC with dynamic window\")\n",
        "n = close > 0 ? 513 : 2\n",
        "unused = ta.vwma(close, n)\n",
        "a = array.new_float(10, close)\n",
        "plot(array.get(a, 0))\n"
    );
    let opts = RunOptions {
        max_collection_elements: 100,
        ..RunOptions::default()
    };
    let closes = vec![2.0; 600];
    let outcome = run_outcome(src, &closes, &opts);
    assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
    assert_eq!(outcome.plots[0].values.len(), closes.len());
    assert_eq!(outcome.plots[0].values.last(), Some(&Value::Float(2.0)));
}

#[test]
fn collection_history_reader_survives_unrelated_dynamic_window_gc() {
    let src = concat!(
        "//@version=6\nindicator(\"Historical array GC\")\n",
        "n = close > 0 ? 513 : 2\n",
        "unused = ta.vwma(close, n)\n",
        "a = array.new_float(1, close)\n",
        "float older = na\n",
        "if bar_index >= 2\n",
        "    older := array.get(a[2], 0)\n",
        "plot(older)\n"
    );
    let opts = RunOptions {
        max_collection_elements: 100,
        ..RunOptions::default()
    };
    let closes: Vec<f64> = (1..=600).map(f64::from).collect();
    let outcome = run_outcome(src, &closes, &opts);
    assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
    assert_eq!(outcome.plots[0].values[0], Value::Na);
    assert_eq!(outcome.plots[0].values[1], Value::Na);
    assert_eq!(outcome.plots[0].values[2], Value::Float(1.0));
    assert_eq!(outcome.plots[0].values.last(), Some(&Value::Float(598.0)));
}

#[test]
fn persistent_collections_survive_collection() {
    // The mirror of the test above: a `var` array is reachable from its slot on
    // every bar, so collection must never reclaim it. Growing it one element
    // per bar also proves the element budget is not double-credited.
    let src = concat!(
        "indicator(\"C\")\n",
        "var a = array.new_float(0)\n",
        "array.push(a, close)\n",
        "plot(array.size(a))\n"
    );
    let opts = RunOptions {
        max_collection_elements: 1_000,
        ..RunOptions::default()
    };
    let closes = vec![1.0; 200];
    let outcome = run_outcome(src, &closes, &opts);
    assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
    assert_eq!(outcome.plots[0].values.last(), Some(&Value::Float(200.0)));
}

#[test]
fn loop_tailed_void_function_runs_all_side_effects() {
    let src = "indicator(\"C\")\nvar a = array.new_int()\nappend() =>\n    for i = 0 to 2\n        array.push(a, i)\nappend()\nplot(array.size(a))\n";
    assert_eq!(
        run_plot(src, &[1.0, 2.0, 3.0]),
        vec![Some(3.0), Some(6.0), Some(9.0)]
    );
}

#[test]
fn collection_on_metering_charges_element_count() {
    // array.new_float(size, initial) is O(n): it charges `size` budget units.
    // With a tiny budget the constructor's element cost exhausts it.
    let src = "indicator(\"C\")\na = array.new_float(50, 0.0)\nplot(array.size(a))\n";
    // Ample budget: succeeds.
    let ok = run_outcome(
        src,
        &[1.0],
        &RunOptions {
            max_instructions_per_bar: 1000,
            ..RunOptions::default()
        },
    );
    assert!(ok.errors.is_empty(), "{:?}", ok.errors);
    // A budget below the element count aborts with InstructionLimitExceeded.
    let starved = run_outcome(
        src,
        &[1.0],
        &RunOptions {
            max_instructions_per_bar: 5,
            ..RunOptions::default()
        },
    );
    assert_eq!(starved.errors.len(), 1);
    assert_eq!(
        starved.errors[0].kind,
        RuntimeErrorKind::InstructionLimitExceeded
    );
}

