    let src = "indicator(\"C\")\n\
               a = array.from(-3.0, 4.0, -5.0)\n\
               b = array.abs(a)\n\
               plot(array.sum(b) + array.get(a, 0))\n";
    // sum(b)=12, get(a,0)=-3 -> 9.
