#[test]
fn array_binary_search_hits_and_misses() {
    // Sorted [1,3,5,7,9]. Present values return their index; absent -> -1.
    let hit = "indicator(\"C\")\n\
               a = array.from(1.0, 3.0, 5.0, 7.0, 9.0)\n\
               plot(array.binary_search(a, 7.0))\n";
    assert_eq!(run_plot(hit, &[1.0]), vec![Some(3.0)]);
    let first = "indicator(\"C\")\n\
                 a = array.from(1.0, 3.0, 5.0, 7.0, 9.0)\n\
                 plot(array.binary_search(a, 1.0))\n";
    assert_eq!(run_plot(first, &[1.0]), vec![Some(0.0)]);
    // Absent value -> -1 (the not-found result).
    let miss = "indicator(\"C\")\n\
                a = array.from(1.0, 3.0, 5.0, 7.0, 9.0)\n\
                plot(array.binary_search(a, 4.0))\n";
    assert_eq!(run_plot(miss, &[1.0]), vec![Some(-1.0)]);
    // Below-range and above-range values -> -1.
    let below = "indicator(\"C\")\n\
                 a = array.from(1.0, 3.0, 5.0)\n\
                 plot(array.binary_search(a, -10.0))\n";
    assert_eq!(run_plot(below, &[1.0]), vec![Some(-1.0)]);
    let above = "indicator(\"C\")\n\
                 a = array.from(1.0, 3.0, 5.0)\n\
                 plot(array.binary_search(a, 100.0))\n";
    assert_eq!(run_plot(above, &[1.0]), vec![Some(-1.0)]);
}

#[test]
fn array_binary_search_leftmost_rightmost_on_duplicates() {
    // Sorted with duplicates: [1,2,2,2,5].
    // leftmost(2) = 1 (first matching index); rightmost(2) = 3 (last matching).
    let left = "indicator(\"C\")\n\
                a = array.from(1.0, 2.0, 2.0, 2.0, 5.0)\n\
                plot(array.binary_search_leftmost(a, 2.0))\n";
    assert_eq!(run_plot(left, &[1.0]), vec![Some(1.0)]);
    let right = "indicator(\"C\")\n\
                 a = array.from(1.0, 2.0, 2.0, 2.0, 5.0)\n\
                 plot(array.binary_search_rightmost(a, 2.0))\n";
    assert_eq!(run_plot(right, &[1.0]), vec![Some(3.0)]);
    // Absent value between elements: leftmost points to the element just left
    // of the insertion point, rightmost to the one just right.
    // [1,3,5], search 4: insertion point index 2 (before 5).
    // leftmost -> 1 (the 3); rightmost -> 2 (the 5).
    let mleft = "indicator(\"C\")\n\
                 a = array.from(1.0, 3.0, 5.0)\n\
                 plot(array.binary_search_leftmost(a, 4.0))\n";
    assert_eq!(run_plot(mleft, &[1.0]), vec![Some(1.0)]);
    let mright = "indicator(\"C\")\n\
                  a = array.from(1.0, 3.0, 5.0)\n\
                  plot(array.binary_search_rightmost(a, 4.0))\n";
    assert_eq!(run_plot(mright, &[1.0]), vec![Some(2.0)]);
    // Below the whole range: leftmost clamps to 0, rightmost points at index 0.
    let bl = "indicator(\"C\")\n\
              a = array.from(2.0, 4.0, 6.0)\n\
              plot(array.binary_search_leftmost(a, 0.0))\n";
    assert_eq!(run_plot(bl, &[1.0]), vec![Some(0.0)]);
    // Above the whole range: rightmost clamps to len-1.
    let ar = "indicator(\"C\")\n\
              a = array.from(2.0, 4.0, 6.0)\n\
              plot(array.binary_search_rightmost(a, 99.0))\n";
    assert_eq!(run_plot(ar, &[1.0]), vec![Some(2.0)]);
}

#[test]
fn array_covariance_of_a_series_with_itself_is_its_variance() {
    // cov(x, x) with the biased (population) estimator equals var(x).
    // [2,4,6]: population variance = 8/3.
    let src = "indicator(\"C\")\n\
               a = array.from(2.0, 4.0, 6.0)\n\
               b = array.from(2.0, 4.0, 6.0)\n\
               plot(array.covariance(a, b))\n";
    let got = run_plot(src, &[1.0])[0].unwrap();
    assert!((got - 8.0 / 3.0).abs() < 1e-12, "cov(x,x) {got}");
    // The unbiased (sample) estimator divides by n-1: 8/2 = 4.
    let unb = "indicator(\"C\")\n\
               a = array.from(2.0, 4.0, 6.0)\n\
               b = array.from(2.0, 4.0, 6.0)\n\
               plot(array.covariance(a, b, false))\n";
    let got = run_plot(unb, &[1.0])[0].unwrap();
    assert!((got - 4.0).abs() < 1e-12, "sample cov {got}");
}

#[test]
fn array_covariance_of_anti_correlated_series_is_negative() {
    // x = [1,2,3], y = [6,4,2]: perfectly anti-correlated.
    // mx=2, my=4; sum (x-mx)(y-my) = (-1)(2)+(0)(0)+(1)(-2) = -4; /3 = -4/3.
    let src = "indicator(\"C\")\n\
               a = array.from(1.0, 2.0, 3.0)\n\
               b = array.from(6.0, 4.0, 2.0)\n\
               plot(array.covariance(a, b))\n";
    let got = run_plot(src, &[1.0])[0].unwrap();
    assert!((got - (-4.0 / 3.0)).abs() < 1e-12, "cov {got}");
}

#[test]
fn array_percentrank_hand_computed() {
    // [10,20,30,40,50]. percentrank at index 2 (value 30): of the other four
    // elements, two (10, 20) are <= 30 -> 2/4 * 100 = 50.
    let src = "indicator(\"C\")\n\
               a = array.from(10.0, 20.0, 30.0, 40.0, 50.0)\n\
               plot(array.percentrank(a, 2))\n";
    assert_eq!(run_plot(src, &[1.0]), vec![Some(50.0)]);
    // At index 0 (the smallest): zero others are <= it -> 0.
    let low = "indicator(\"C\")\n\
               a = array.from(10.0, 20.0, 30.0, 40.0, 50.0)\n\
               plot(array.percentrank(a, 0))\n";
    assert_eq!(run_plot(low, &[1.0]), vec![Some(0.0)]);
    // At the largest: all four others are <= it -> 100.
    let high = "indicator(\"C\")\n\
                a = array.from(10.0, 20.0, 30.0, 40.0, 50.0)\n\
                plot(array.percentrank(a, 4))\n";
    assert_eq!(run_plot(high, &[1.0]), vec![Some(100.0)]);
}

#[test]
fn array_percentile_nearest_rank_hand_computed() {
    // Sorted [15,20,35,40,50]. nearest-rank at 40%: ceil(0.40*5)=ceil(2)=2 ->
    // the 2nd value (1-based) = 20.
    let src = "indicator(\"C\")\n\
               a = array.from(15.0, 20.0, 35.0, 40.0, 50.0)\n\
               plot(array.percentile_nearest_rank(a, 40.0))\n";
    assert_eq!(run_plot(src, &[1.0]), vec![Some(20.0)]);
    // 0% -> the minimum; 100% -> the maximum.
    let lo = "indicator(\"C\")\n\
              a = array.from(15.0, 20.0, 35.0, 40.0, 50.0)\n\
              plot(array.percentile_nearest_rank(a, 0.0))\n";
    assert_eq!(run_plot(lo, &[1.0]), vec![Some(15.0)]);
    let hi = "indicator(\"C\")\n\
              a = array.from(15.0, 20.0, 35.0, 40.0, 50.0)\n\
              plot(array.percentile_nearest_rank(a, 100.0))\n";
    assert_eq!(run_plot(hi, &[1.0]), vec![Some(50.0)]);
    // Operates on unsorted input by sorting internally (nearest-rank sorts).
    let uns = "indicator(\"C\")\n\
               a = array.from(50.0, 15.0, 40.0, 20.0, 35.0)\n\
               plot(array.percentile_nearest_rank(a, 40.0))\n";
    assert_eq!(run_plot(uns, &[1.0]), vec![Some(20.0)]);
}

#[test]
fn array_percentile_linear_interpolation_hand_computed() {
    // Sorted [10,20,30,40]. Position h = p/100*(n-1) = p/100*3.
    // At 50%: h = 1.5 -> between xs[1]=20 and xs[2]=30, frac 0.5 -> 25.
    let src = "indicator(\"C\")\n\
               a = array.from(10.0, 20.0, 30.0, 40.0)\n\
               plot(array.percentile_linear_interpolation(a, 50.0))\n";
    assert_eq!(run_plot(src, &[1.0]), vec![Some(25.0)]);
    // At 0% -> min (10); at 100% -> max (40).
    let lo = "indicator(\"C\")\n\
              a = array.from(10.0, 20.0, 30.0, 40.0)\n\
              plot(array.percentile_linear_interpolation(a, 0.0))\n";
    assert_eq!(run_plot(lo, &[1.0]), vec![Some(10.0)]);
    let hi = "indicator(\"C\")\n\
              a = array.from(10.0, 20.0, 30.0, 40.0)\n\
              plot(array.percentile_linear_interpolation(a, 100.0))\n";
    assert_eq!(run_plot(hi, &[1.0]), vec![Some(40.0)]);
    // A third of the way: 33.333...% -> h = 1.0 exactly -> xs[1] = 20.
    let third = "indicator(\"C\")\n\
                 a = array.from(10.0, 20.0, 30.0, 40.0)\n\
                 pct = 100.0 / 3.0\n\
                 plot(array.percentile_linear_interpolation(a, pct))\n";
    let got = run_plot(third, &[1.0])[0].unwrap();
    assert!((got - 20.0).abs() < 1e-9, "linear interp {got}");
}

#[test]
fn array_cf3_edge_cases_empty_single_all_na() {
    // Empty numeric array: percentile family -> na; covariance -> na;
    // binary_search -> -1.
    let empty_pct = "indicator(\"C\")\n\
                     a = array.new_float(0)\n\
                     plot(array.percentile_nearest_rank(a, 50.0))\n";
    assert_eq!(run_plot(empty_pct, &[1.0]), vec![None]);
    let empty_search = "indicator(\"C\")\n\
                        a = array.new_float(0)\n\
                        plot(array.binary_search(a, 1.0))\n";
    assert_eq!(run_plot(empty_search, &[1.0]), vec![Some(-1.0)]);
    // Single element: linear interpolation returns that element at any pct;
    // percentrank has no "others" -> na.
    let single = "indicator(\"C\")\n\
                  a = array.from(42.0)\n\
                  plot(array.percentile_linear_interpolation(a, 73.0))\n";
    assert_eq!(run_plot(single, &[1.0]), vec![Some(42.0)]);
    let single_rank = "indicator(\"C\")\n\
                       a = array.from(42.0)\n\
                       plot(array.percentrank(a, 0))\n";
    assert_eq!(run_plot(single_rank, &[1.0]), vec![None]);
    // All-na array: aggregates skip na, so the percentile family sees an empty
    // numeric set -> na.
    let all_na = "indicator(\"C\")\n\
                  a = array.new_float(3)\n\
                  plot(array.percentile_nearest_rank(a, 50.0))\n";
    assert_eq!(run_plot(all_na, &[1.0]), vec![None]);
}

#[test]
fn array_covariance_skips_na_pairs() {
    // a = [10, na, 30], b = [1, 2, 3]. Only indices 0 and 2 are paired.
    // Paired x=[10,30] mean 20; y=[1,3] mean 2. sum (x-mx)(y-my) =
    // (-10)(-1)+(10)(1)=20; biased /2 = 10.
    let src = "indicator(\"C\")\n\
               a = array.new_float(3)\n\
               array.set(a, 0, 10.0)\n\
               array.set(a, 2, 30.0)\n\
               b = array.from(1.0, 2.0, 3.0)\n\
               plot(array.covariance(a, b))\n";
    let got = run_plot(src, &[1.0])[0].unwrap();
    assert!((got - 10.0).abs() < 1e-12, "cov skipping na {got}");
}

