#[test]
fn map_na_key_is_a_structured_error() {
    // An na key would create an unreachable entry (na != na); reject it.
    // `na` in the key argument adopts the string key type, so this compiles;
    // the na-key rejection is a runtime error.
    let src = "indicator(\"C\")\n\
               m = map.new_string_float()\n\
               map.put(m, na, 10.0)\n\
               plot(map.size(m))\n";
    let program = compile(src);
    let outcome = run(&program, &data_from_close(&[1.0]), &RunOptions::default());
    assert_eq!(outcome.errors.len(), 1, "errors: {:?}", outcome.errors);
    assert_eq!(outcome.errors[0].kind, RuntimeErrorKind::TypeMismatch);
    assert!(outcome.errors[0]
        .message
        .contains("map key must not be `na`"));
}

