#[test]
fn matrix_new_binds_named_arguments_by_parameter_name() {
    // Named arguments bind by parameter name, not by position: each
    // program plots rows, columns, and the last cell of a 2x3 matrix.
    let float_src = "indicator(\"M\")\n\
                     m = matrix.new<float>(columns = 3, rows = 2, initial_value = 1.5)\n\
                     plot(matrix.rows(m))\n\
                     plot(matrix.columns(m))\n\
                     plot(matrix.get(m, 1, 2))\n";
    assert_eq!(
        run_close(float_src, &[1.0]),
        vec![vec![Some(2.0)], vec![Some(3.0)], vec![Some(1.5)]]
    );
    let int_src = "indicator(\"M\")\n\
                   m = matrix.new<int>(initial_value = 7, rows = 2, columns = 3)\n\
                   plot(matrix.rows(m))\n\
                   plot(matrix.columns(m))\n\
                   plot(matrix.get(m, 1, 2))\n";
    assert_eq!(
        run_close(int_src, &[1.0]),
        vec![vec![Some(2.0)], vec![Some(3.0)], vec![Some(7.0)]]
    );
    // bool and color cells take distinct analyzer and VM paths; a named
    // `initial_value` must still fill every cell of the named shape.
    let bool_src = "indicator(\"M\")\n\
                    m = matrix.new<bool>(initial_value = true, columns = 1, rows = 2)\n\
                    ok = matrix.rows(m) == 2 and matrix.columns(m) == 1 and matrix.get(m, 1, 0)\n\
                    plot(ok ? 1.0 : 0.0)\n";
    assert_eq!(run_plot(bool_src, &[1.0]), vec![Some(1.0)]);
    let color_src = "indicator(\"M\")\n\
                     expected = color.new(color.red, 25)\n\
                     m = matrix.new<color>(columns = 2, initial_value = expected, rows = 1)\n\
                     ok = matrix.rows(m) == 1 and matrix.columns(m) == 2 and matrix.get(m, 0, 1) == expected\n\
                     plot(ok ? 1.0 : 0.0)\n";
    assert_eq!(run_plot(color_src, &[1.0]), vec![Some(1.0)]);
}

