#[test]
fn matrix_transpose_preserves_extreme_empty_shapes() {
    let program = compile("indicator(\"Empty transpose\")\nplot(close)\n");
    let data = data_from_close(&[1.0]);
    let options = RunOptions::default();
    let maximum = usize::try_from(i64::MAX).unwrap_or(usize::MAX);
    for (rows, cols) in [(0, 0), (0, 3), (3, 0), (0, maximum), (maximum, 0)] {
        let mut vm = crate::Vm::new(&program, &data, &options).unwrap();
        let receiver = vm
            .call_collection(
                CollectionFunc::MatrixNew,
                &[
                    Value::Int(i64::try_from(rows).unwrap()),
                    Value::Int(i64::try_from(cols).unwrap()),
                    Value::Int(7),
                    Value::Int(ElemType::Int.to_tag()),
                ],
                0,
            )
            .unwrap();
        let Value::Ref(source_handle) = receiver else {
            unreachable!("matrix handle")
        };
        let original = vm.heap.get(source_handle).cloned();
        let transposed = vm
            .call_collection(
                CollectionFunc::MatrixTranspose,
                std::slice::from_ref(&receiver),
                0,
            )
            .unwrap();
        assert_ne!(transposed, receiver);
        assert_eq!(
            vm.call_collection(
                CollectionFunc::MatrixRows,
                std::slice::from_ref(&transposed),
                0,
            )
            .unwrap(),
            Value::Int(i64::try_from(cols).unwrap())
        );
        assert_eq!(
            vm.call_collection(
                CollectionFunc::MatrixColumns,
                std::slice::from_ref(&transposed),
                0,
            )
            .unwrap(),
            Value::Int(i64::try_from(rows).unwrap())
        );
        let Value::Ref(result_handle) = transposed else {
            unreachable!("matrix handle")
        };
        assert!(matches!(
            vm.heap.get(result_handle),
            Some(HeapObj::Matrix { elem_ty: ElemType::Int, items, .. }) if items.is_empty()
        ));
        assert_eq!(vm.heap.get(source_handle), original.as_ref());
    }
}

