#[test]
fn matrix_reinsertion_rejects_changed_nonzero_axis_without_mutating_or_charging() {
    let program = compile("indicator(\"M\")\nplot(close)\n");
    let data = data_from_close(&[1.0]);
    let options = RunOptions::default();
    for (remove, add, rows, cols) in [
        (
            CollectionFunc::MatrixRemoveRow,
            CollectionFunc::MatrixAddRow,
            1,
            2,
        ),
        (
            CollectionFunc::MatrixRemoveCol,
            CollectionFunc::MatrixAddCol,
            2,
            1,
        ),
    ] {
        for line_len in [0, 1, 3] {
            let mut vm = crate::Vm::new(&program, &data, &options).expect("small VM state");
            let matrix = vm
                .call_collection(
                    CollectionFunc::MatrixNew,
                    &[
                        Value::Int(rows),
                        Value::Int(cols),
                        Value::String("kept".into()),
                        Value::Int(ElemType::String.to_tag()),
                    ],
                    0,
                )
                .expect("matrix fixture");
            vm.call_collection(remove, &[matrix.clone(), Value::Int(0)], 0)
                .expect("remove last row or column");
            let line = vm
                .heap
                .alloc(HeapObj::Array {
                    elem_ty: ElemType::String,
                    items: vec![Value::String("new".into()); line_len],
                })
                .expect("line fixture");
            let Value::Ref(handle) = matrix else {
                unreachable!("matrix handle")
            };
            let before = vm.heap.get(handle).cloned();
            let elements = vm.heap.live_elements();
            let objects = vm.heap.len();
            let string_bytes = vm.string_bytes_allocated;
            let error = vm
                .call_collection(
                    add,
                    &[Value::Ref(handle), Value::Int(0), Value::Ref(line)],
                    0,
                )
                .expect_err("the established nonzero axis requires two values");
            assert_eq!(error.kind, RuntimeErrorKind::MatrixDimensionMismatch);
            assert_eq!(vm.heap.get(handle), before.as_ref());
            assert_eq!(vm.heap.live_elements(), elements);
            assert_eq!(vm.heap.len(), objects);
            assert_eq!(vm.string_bytes_allocated, string_bytes);
            assert!(
                matches!(vm.heap.get(handle), Some(HeapObj::Matrix { rows, cols, items, .. })
                if rows * cols == items.len() && items.is_empty())
            );
        }
    }
}

#[test]
fn matrix_reinsertion_preserves_shape_and_values_through_the_source_api() {
    for (rows, cols, remove, add, expected_rows, expected_cols) in [
        (1, 2, "remove_row", "add_row", 1, 2),
        (2, 1, "remove_col", "add_col", 2, 1),
    ] {
        let prefix = format!(
            "indicator(\"M\")\nm = matrix.new_int({rows}, {cols}, 0)\n\
             removed = matrix.{remove}(m, 0)\na = array.new_int(2, 7)\n\
             matrix.{add}(m, 0, a)\n"
        );
        let source = format!(
            "{prefix}ok = matrix.rows(m) == {expected_rows} and matrix.columns(m) == {expected_cols} and matrix.elements_count(m) == 2 and matrix.get(m, 0, 0) == 7\nplot(ok ? 1.0 : 0.0)\n"
        );
        assert_eq!(run_plot(&source, &[1.0]), vec![Some(1.0)]);

        let invalid = source.replace("array.new_int(2, 7)", "array.new_int(3, 7)");
        let outcome = run_outcome(&invalid, &[1.0], &RunOptions::default());
        assert_eq!(outcome.errors.len(), 1, "{:?}", outcome.errors);
        assert_eq!(
            outcome.errors[0].kind,
            RuntimeErrorKind::MatrixDimensionMismatch
        );
    }
}

