#[test]
fn matrix_concat_zero_axis_mismatches_preserve_operands_and_accounting() {
    let program = compile("indicator(\"M\")\nplot(close)\n");
    let data = data_from_close(&[1.0]);
    let options = RunOptions::default();
    let mut vm = crate::Vm::new(&program, &data, &options).expect("small VM state");
    let object = vm
        .heap
        .alloc(HeapObj::Object {
            table_identity: None,
            type_id: 7,
            fields: vec![Value::Int(42)],
        })
        .expect("object fixture");
    for (elem_ty, value) in [
        (ElemType::Int, Value::Int(9_007_199_254_740_993)),
        (ElemType::Float, Value::Float(1.25)),
        (ElemType::Bool, Value::Bool(true)),
        (ElemType::String, Value::String("kept".into())),
        (
            ElemType::Color,
            Value::Color {
                r: 1,
                g: 2,
                b: 3,
                t: 4.0,
                input_origin: None,
            },
        ),
        (ElemType::Object(7), Value::Ref(object)),
    ] {
        for (rows, cols, removal, established_cols) in [
            (0, 2, None, 2),
            (1, 2, Some(CollectionFunc::MatrixRemoveRow), 2),
            (2, 0, None, 0),
            (2, 1, Some(CollectionFunc::MatrixRemoveCol), 0),
        ] {
            for rhs_rows in [0, 1, 3] {
                for rhs_cols in [0, 1, 2, 3] {
                    if rhs_cols == established_cols {
                        continue;
                    }
                    let receiver = vm
                        .call_collection(
                            CollectionFunc::MatrixNew,
                            &[
                                Value::Int(rows),
                                Value::Int(cols),
                                value.clone(),
                                Value::Int(elem_ty.to_tag()),
                            ],
                            0,
                        )
                        .expect("receiver fixture");
                    if let Some(remove) = removal {
                        vm.call_collection(remove, &[receiver.clone(), Value::Int(0)], 0)
                            .expect("collapse one axis through the real removal path");
                    }
                    let rhs = vm
                        .call_collection(
                            CollectionFunc::MatrixNew,
                            &[
                                Value::Int(rhs_rows),
                                Value::Int(rhs_cols),
                                value.clone(),
                                Value::Int(elem_ty.to_tag()),
                            ],
                            0,
                        )
                        .expect("appended fixture");
                    let (Value::Ref(left), Value::Ref(right)) = (&receiver, &rhs) else {
                        unreachable!("matrix handles")
                    };
                    let before = (vm.heap.get(*left).cloned(), vm.heap.get(*right).cloned());
                    let accounting = (
                        vm.heap.live_elements(),
                        vm.heap.len(),
                        vm.string_bytes_allocated,
                    );
                    let error = vm
                        .call_collection(
                            CollectionFunc::MatrixConcat,
                            &[receiver.clone(), rhs.clone()],
                            0,
                        )
                        .expect_err("an established width cannot be adopted or erased");
                    assert_eq!(error.kind, RuntimeErrorKind::MatrixDimensionMismatch);
                    assert_eq!(
                        (vm.heap.get(*left), vm.heap.get(*right)),
                        (before.0.as_ref(), before.1.as_ref())
                    );
                    assert_eq!(
                        (
                            vm.heap.live_elements(),
                            vm.heap.len(),
                            vm.string_bytes_allocated
                        ),
                        accounting
                    );
                }
            }
        }
    }
}

#[test]
fn matrix_concat_zero_axis_shape_contract_through_source_api() {
    // Degenerate shapes follow PineWASM's explicit Assumed policy; these tests pin
    // that policy.
    for (rows, cols, remove, rhs_rows, rhs_cols, expected_rows, expected_cols) in [
        (0, 2, None, 3, 2, 3, 2),
        (1, 2, Some("remove_row"), 3, 2, 3, 2),
        (0, 2, None, 0, 2, 0, 2),
        (1, 2, Some("remove_row"), 0, 2, 0, 2),
        (2, 0, None, 3, 0, 5, 0),
        (2, 1, Some("remove_col"), 3, 0, 5, 0),
        (2, 0, None, 0, 0, 2, 0),
        (0, 0, None, 3, 2, 3, 2),
        (0, 0, None, 0, 3, 0, 3),
        (0, 0, None, 2, 0, 2, 0),
        (0, 0, None, 0, 0, 0, 0),
        (1, 2, None, 0, 2, 1, 2),
    ] {
        let removal = remove
            .map(|name| format!("removed = matrix.{name}(m, 0)\n"))
            .unwrap_or_default();
        let source = format!(
            "indicator(\"Concat shape\")\nm = matrix.new_int({rows}, {cols}, 7)\n\
             {removal}rhs = matrix.new_int({rhs_rows}, {rhs_cols}, 7)\n\
             alias = matrix.concat(m, rhs)\n\
             ok = matrix.rows(alias) == {expected_rows} and matrix.columns(alias) == {expected_cols} and matrix.elements_count(alias) == {}\n\
             plot(ok ? 1.0 : 0.0)\n", expected_rows * expected_cols
        );
        assert_eq!(run_plot(&source, &[1.0]), vec![Some(1.0)], "{source}");
    }
    for (rows, cols) in [(0, 0), (0, 2), (2, 0), (1, 2)] {
        let source = format!(
            "indicator(\"Concat self\")\nm = matrix.new_int({rows}, {cols}, 7)\n\
             matrix.concat(m, m)\n\
             ok = matrix.rows(m) == {} and matrix.columns(m) == {cols} and matrix.elements_count(m) == {}\n\
             plot(ok ? 1.0 : 0.0)\n", rows * 2, rows * cols * 2
        );
        assert_eq!(run_plot(&source, &[1.0]), vec![Some(1.0)]);
    }
}

#[test]
fn matrix_concat_preserves_all_element_tags_and_self_alias_values() {
    let program = compile("indicator(\"M\")\nplot(close)\n");
    let data = data_from_close(&[1.0]);
    let options = RunOptions::default();
    let mut vm = crate::Vm::new(&program, &data, &options).expect("small VM state");
    let objects: Vec<_> = [1, 2]
        .into_iter()
        .map(|value| {
            vm.heap
                .alloc(HeapObj::Object {
                    table_identity: None,
                    type_id: 7,
                    fields: vec![Value::Int(value)],
                })
                .expect("object fixture")
        })
        .collect();
    for (elem_ty, first, appended) in [
        (
            ElemType::Int,
            Value::Int(9_007_199_254_740_993),
            Value::Int(9_007_199_254_740_995),
        ),
        (ElemType::Float, Value::Float(1.25), Value::Float(2.5)),
        (ElemType::Bool, Value::Bool(false), Value::Bool(true)),
        (
            ElemType::String,
            Value::String("left".into()),
            Value::String("right".into()),
        ),
        (
            ElemType::Color,
            Value::Color {
                r: 1,
                g: 2,
                b: 3,
                t: 4.0,
                input_origin: None,
            },
            Value::Color {
                r: 5,
                g: 6,
                b: 7,
                t: 8.0,
                input_origin: None,
            },
        ),
        (
            ElemType::Object(7),
            Value::Ref(objects[0]),
            Value::Ref(objects[1]),
        ),
    ] {
        let receiver = vm
            .call_collection(
                CollectionFunc::MatrixNew,
                &[
                    Value::Int(1),
                    Value::Int(2),
                    first.clone(),
                    Value::Int(elem_ty.to_tag()),
                ],
                0,
            )
            .unwrap();
        let rhs = vm
            .call_collection(
                CollectionFunc::MatrixNew,
                &[
                    Value::Int(2),
                    Value::Int(2),
                    appended.clone(),
                    Value::Int(elem_ty.to_tag()),
                ],
                0,
            )
            .unwrap();
        let (Value::Ref(left), Value::Ref(right)) = (&receiver, &rhs) else {
            unreachable!("matrix handles")
        };
        let rhs_before = vm.heap.get(*right).cloned();
        let accounting = (
            vm.heap.live_elements(),
            vm.heap.len(),
            vm.string_bytes_allocated,
        );
        let result = vm
            .call_collection(
                CollectionFunc::MatrixConcat,
                &[receiver.clone(), rhs.clone()],
                0,
            )
            .unwrap();
        assert_eq!(result, receiver);
        let expected = vec![
            first.clone(),
            first,
            appended.clone(),
            appended.clone(),
            appended.clone(),
            appended.clone(),
        ];
        assert_eq!(
            vm.heap.get(*left),
            Some(&HeapObj::Matrix {
                elem_ty,
                rows: 3,
                cols: 2,
                items: expected.clone()
            })
        );
        assert_eq!(vm.heap.get(*right), rhs_before.as_ref());
        assert_eq!(vm.heap.live_elements(), accounting.0 + 4);
        assert_eq!(vm.heap.len(), accounting.1);
        let copied_bytes = if let Value::String(value) = &appended {
            value.len() * 4
        } else {
            0
        };
        assert_eq!(vm.string_bytes_allocated, accounting.2 + copied_bytes);
        let before_self = (
            vm.heap.live_elements(),
            vm.heap.len(),
            vm.string_bytes_allocated,
        );
        vm.call_collection(
            CollectionFunc::MatrixConcat,
            &[receiver.clone(), receiver.clone()],
            0,
        )
        .unwrap();
        let self_bytes: usize = expected
            .iter()
            .map(|value| {
                if let Value::String(value) = value {
                    value.len()
                } else {
                    0
                }
            })
            .sum();
        assert_eq!(
            vm.heap.get(*left),
            Some(&HeapObj::Matrix {
                elem_ty,
                rows: 6,
                cols: 2,
                items: [expected.clone(), expected].concat()
            })
        );
        assert_eq!(
            (
                vm.heap.live_elements(),
                vm.heap.len(),
                vm.string_bytes_allocated
            ),
            (before_self.0 + 6, before_self.1, before_self.2 + self_bytes)
        );
    }
}

#[test]
fn matrix_concat_resource_refusals_preserve_shape_values_and_accounting() {
    let program = compile("indicator(\"M\")\nplot(close)\n");
    let data = data_from_close(&[1.0]);
    for rows in [0, 1] {
        for string_limit in [false, true] {
            let initial_elements = (rows + 1) * 2;
            let options = RunOptions {
                max_collection_elements: initial_elements + if string_limit { 2 } else { 1 },
                max_string_bytes_per_run: if string_limit {
                    initial_elements * 2 + 3
                } else {
                    100
                },
                ..RunOptions::default()
            };
            let mut vm = crate::Vm::new(&program, &data, &options).unwrap();
            let receiver = vm
                .call_collection(
                    CollectionFunc::MatrixNew,
                    &[
                        Value::Int(rows as i64),
                        Value::Int(2),
                        Value::String("ab".into()),
                        Value::Int(ElemType::String.to_tag()),
                    ],
                    0,
                )
                .unwrap();
            let rhs = vm
                .call_collection(
                    CollectionFunc::MatrixNew,
                    &[
                        Value::Int(1),
                        Value::Int(2),
                        Value::String("cd".into()),
                        Value::Int(ElemType::String.to_tag()),
                    ],
                    0,
                )
                .unwrap();
            let (Value::Ref(left), Value::Ref(right)) = (&receiver, &rhs) else {
                unreachable!("matrix handles")
            };
            let before = (vm.heap.get(*left).cloned(), vm.heap.get(*right).cloned());
            let accounting = (
                vm.heap.live_elements(),
                vm.heap.len(),
                vm.string_bytes_allocated,
            );
            let error = vm
                .call_collection(
                    CollectionFunc::MatrixConcat,
                    &[receiver.clone(), rhs.clone()],
                    0,
                )
                .expect_err("concat exceeds one budget");
            assert_eq!(
                error.kind,
                if string_limit {
                    RuntimeErrorKind::StringLimitExceeded
                } else {
                    RuntimeErrorKind::CollectionLimitExceeded
                }
            );
            assert_eq!(
                (vm.heap.get(*left), vm.heap.get(*right)),
                (before.0.as_ref(), before.1.as_ref())
            );
            assert_eq!(
                (
                    vm.heap.live_elements(),
                    vm.heap.len(),
                    vm.string_bytes_allocated
                ),
                accounting
            );
        }
    }
}

#[test]
fn matrix_concat_zero_width_row_growth_is_checked_before_mutation() {
    let program = compile("indicator(\"M\")\nplot(close)\n");
    let data = data_from_close(&[1.0]);
    let options = RunOptions::default();
    // The heap uses usize dimensions, while the public row query returns i64.
    let maximum = usize::try_from(i64::MAX).unwrap_or(usize::MAX);
    for (rows, self_concat, succeeds) in [
        (maximum - 1, false, true),
        (maximum, false, false),
        (maximum, true, false),
    ] {
        let mut vm = crate::Vm::new(&program, &data, &options).unwrap();
        let receiver = vm
            .call_collection(
                CollectionFunc::MatrixNew,
                &[
                    Value::Int(i64::try_from(rows).unwrap()),
                    Value::Int(0),
                    Value::Int(7),
                    Value::Int(ElemType::Int.to_tag()),
                ],
                0,
            )
            .unwrap();
        let rhs = if self_concat {
            receiver.clone()
        } else {
            vm.call_collection(
                CollectionFunc::MatrixNew,
                &[
                    Value::Int(1),
                    Value::Int(0),
                    Value::Int(9),
                    Value::Int(ElemType::Int.to_tag()),
                ],
                0,
            )
            .unwrap()
        };
        let (Value::Ref(handle), Value::Ref(rhs_handle)) = (&receiver, &rhs) else {
            unreachable!("matrix handles")
        };
        let before = (
            vm.heap.get(*handle).cloned(),
            vm.heap.get(*rhs_handle).cloned(),
        );
        let accounting = (
            vm.heap.live_elements(),
            vm.heap.len(),
            vm.string_bytes_allocated,
        );
        let result = vm.call_collection(
            CollectionFunc::MatrixConcat,
            &[receiver.clone(), rhs.clone()],
            0,
        );
        if succeeds {
            assert_eq!(result.unwrap(), receiver);
            assert_eq!(
                vm.call_collection(
                    CollectionFunc::MatrixRows,
                    std::slice::from_ref(&receiver),
                    0
                )
                .unwrap(),
                Value::Int(i64::try_from(maximum).unwrap())
            );
            assert!(
                matches!(vm.heap.get(*handle), Some(HeapObj::Matrix { rows, cols: 0, items, .. }) if *rows == maximum && items.is_empty())
            );
            assert_eq!(vm.heap.get(*rhs_handle), before.1.as_ref());
        } else {
            assert_eq!(
                result
                    .expect_err("zero-width matrices still need representable row counts")
                    .kind,
                RuntimeErrorKind::CollectionLimitExceeded
            );
            assert_eq!(
                (vm.heap.get(*handle), vm.heap.get(*rhs_handle)),
                (before.0.as_ref(), before.1.as_ref())
            );
        }
        assert_eq!(
            (
                vm.heap.live_elements(),
                vm.heap.len(),
                vm.string_bytes_allocated
            ),
            accounting
        );
    }
}

