    let deficient = "indicator(\"M\")\n\
                     a = matrix.new_float(3, 3, 0.0)\n\
                     matrix.set(a, 0, 0, 1.0)\nmatrix.set(a, 0, 1, 2.0)\nmatrix.set(a, 0, 2, 3.0)\n\
                     matrix.set(a, 1, 0, 1.0)\nmatrix.set(a, 1, 1, 2.0)\nmatrix.set(a, 1, 2, 3.0)\n\
                     matrix.set(a, 2, 0, 4.0)\nmatrix.set(a, 2, 1, 5.0)\nmatrix.set(a, 2, 2, 7.0)\n\
                     plot(matrix.rank(a))\n";
    assert_eq!(run_plot(deficient, &[1.0]), vec![Some(2.0)]);
    // A 3x3 identity is full rank (3).
    let ident = "indicator(\"M\")\n\
                 a = matrix.new_float(3, 3, 0.0)\n\
                 matrix.set(a, 0, 0, 1.0)\nmatrix.set(a, 1, 1, 1.0)\nmatrix.set(a, 2, 2, 1.0)\n\
                 plot(matrix.rank(a))\n";
