#[test]
fn matrix_structural_lines_preserve_int_and_string_values() {
    // Source-level equality catches the former int -> float widening by its
    // value tag. Keeping a value above f64's exact integer range additionally
    // aligns this case with the lower-level payload and AOT regression tests. Method and namespace forms are both exercised, including a
    // returned removal array.
    let int_source = "indicator(\"M\")\n\
                      m = matrix.new<int>(1, 2, 9007199254740993)\n\
                      row = m.row(0)\n\
                      removed = matrix.remove_col(m, 0)\n\
                      ok = row.get(0) == 9007199254740993 and removed.get(0) == 9007199254740993 and matrix.get(m, 0, 0) == 9007199254740993\n\
                      plot(ok ? 1.0 : 0.0)\n";
    assert_eq!(run_plot(int_source, &[1.0]), vec![Some(1.0)]);

    let string_source = "indicator(\"M\")\n\
                         m = matrix.new<string>(2, 2, \"\")\n\
                         matrix.set(m, 0, 0, \"a\")\n\
                         matrix.set(m, 0, 1, \"b\")\n\
                         matrix.set(m, 1, 0, \"c\")\n\
                         matrix.set(m, 1, 1, \"d\")\n\
                         col = m.col(1)\n\
                         removed = m.remove_row(0)\n\
                         ok = col.get(0) == \"b\" and col.get(1) == \"d\" and removed.get(0) == \"a\" and removed.get(1) == \"b\" and matrix.get(m, 0, 0) == \"c\"\n\
                         plot(ok ? 1.0 : 0.0)\n";
    assert_eq!(run_plot(string_source, &[1.0]), vec![Some(1.0)]);
}

