#[test]
fn matrix_structural_lines_preserve_every_vm_element_tag_and_reference_identity() {
    let program = compile("indicator(\"C\")\nplot(close)\n");
    let data = data_from_close(&[1.0]);
    let options = RunOptions::default();
    let mut vm = crate::Vm::new(&program, &data, &options).expect("small VM state");
    let object = vm
        .heap
        .alloc(HeapObj::Object {
            table_identity: None,
            type_id: 7,
            fields: vec![Value::Float(42.0)],
        })
        .expect("object fixture");
    let cases = vec![
        (ElemType::Int, Value::Int(9_007_199_254_740_993)),
        (ElemType::Float, Value::Float(1.25)),
        (ElemType::Bool, Value::Bool(true)),
        (ElemType::String, Value::String("kept".to_string())),
        (
            ElemType::Color,
            Value::Color {
                r: 1,
                g: 2,
                b: 3,
                t: 4.0,
                input_origin: None,
            },
        ),
        (ElemType::Object(7), Value::Ref(object)),
    ];

    let array = |vm: &crate::Vm, value: &Value| -> (ElemType, Vec<Value>) {
        let Value::Ref(handle) = value else {
            panic!("expected array handle, got {value:?}");
        };
        match vm.heap.get(*handle) {
            Some(HeapObj::Array { elem_ty, items }) => (*elem_ty, items.clone()),
            other => panic!("expected heap array, got {other:?}"),
        }
    };

    for (elem_ty, value) in cases {
        let matrix = vm
            .call_collection(
                CollectionFunc::MatrixNew,
                &[
                    Value::Int(2),
                    Value::Int(2),
                    value.clone(),
                    Value::Int(elem_ty.to_tag()),
                ],
                0,
            )
            .expect("matrix fixture");
        let row = vm
            .call_collection(
                CollectionFunc::MatrixRow,
                &[matrix.clone(), Value::Int(0)],
                0,
            )
            .expect("row result");
        assert_eq!(array(&vm, &row), (elem_ty, vec![value.clone(); 2]));

        let col = vm
            .call_collection(
                CollectionFunc::MatrixCol,
                &[matrix.clone(), Value::Int(1)],
                0,
            )
            .expect("column result");
        assert_eq!(array(&vm, &col), (elem_ty, vec![value.clone(); 2]));

        let removed_row = vm
            .call_collection(
                CollectionFunc::MatrixRemoveRow,
                &[matrix.clone(), Value::Int(1)],
                0,
            )
            .expect("removed row");
        assert_eq!(array(&vm, &removed_row), (elem_ty, vec![value.clone(); 2]));
        let removed_col = vm
            .call_collection(
                CollectionFunc::MatrixRemoveCol,
                &[matrix.clone(), Value::Int(0)],
                0,
            )
            .expect("removed column");
        assert_eq!(array(&vm, &removed_col), (elem_ty, vec![value.clone()]));

        let Value::Ref(matrix_handle) = matrix else {
            unreachable!("matrix constructor returns a handle")
        };
        match vm.heap.get(matrix_handle) {
            Some(HeapObj::Matrix {
                elem_ty: remaining_ty,
                rows,
                cols,
                items,
            }) => {
                assert_eq!((*remaining_ty, *rows, *cols), (elem_ty, 1, 1));
                assert_eq!(items, &vec![value]);
            }
            other => panic!("expected heap matrix, got {other:?}"),
        }
    }
}

#[test]
fn matrix_removal_is_atomic_at_the_object_limit() {
    let program = compile("indicator(\"C\")\nplot(close)\n");
    let data = data_from_close(&[1.0]);
    let options = RunOptions::default();
    for func in [
        CollectionFunc::MatrixRemoveRow,
        CollectionFunc::MatrixRemoveCol,
    ] {
        let mut vm = crate::Vm::new(&program, &data, &options).expect("small VM state");
        vm.heap = Heap::with_limits(4, 1);
        let matrix = vm
            .call_collection(
                CollectionFunc::MatrixNew,
                &[
                    Value::Int(2),
                    Value::Int(2),
                    Value::Int(7),
                    Value::Int(ElemType::Int.to_tag()),
                ],
                0,
            )
            .expect("matrix at the sole object slot");

        let error = vm
            .call_collection(func, &[matrix.clone(), Value::Int(0)], 0)
            .expect_err("the returned array needs a second object slot");
        assert_eq!(error.kind, RuntimeErrorKind::CollectionLimitExceeded);
        assert_eq!(vm.heap.len(), 1);
        assert_eq!(vm.heap.live_elements(), 4);
        let Value::Ref(handle) = matrix else {
            unreachable!("matrix constructor returns a handle")
        };
        assert!(matches!(
            vm.heap.get(handle),
            Some(HeapObj::Matrix {
                rows: 2,
                cols: 2,
                items,
                ..
            }) if items == &vec![Value::Int(7); 4]
        ));
    }
}

#[test]
fn matrix_removal_transfers_cells_without_transient_element_or_string_growth() {
    let program = compile("indicator(\"C\")\nplot(close)\n");
    let data = data_from_close(&[1.0]);
    for (func, rows, cols) in [
        (CollectionFunc::MatrixRemoveRow, 1, 2),
        (CollectionFunc::MatrixRemoveCol, 2, 1),
    ] {
        let options = RunOptions {
            max_collection_elements: 2,
            max_string_bytes_per_run: 4,
            ..RunOptions::default()
        };
        let mut vm = crate::Vm::new(&program, &data, &options).expect("small VM state");
        let matrix = vm
            .call_collection(
                CollectionFunc::MatrixNew,
                &[
                    Value::Int(rows),
                    Value::Int(cols),
                    Value::String("ab".to_string()),
                    Value::Int(ElemType::String.to_tag()),
                ],
                0,
            )
            .expect("matrix exactly fills both budgets");
        let removed = vm
            .call_collection(func, &[matrix.clone(), Value::Int(0)], 0)
            .expect("ownership transfer does not need element or string headroom");
        let Value::Ref(handle) = removed else {
            unreachable!("removal returns an array handle")
        };
        assert!(matches!(
            vm.heap.get(handle),
            Some(HeapObj::Array {
                elem_ty: ElemType::String,
                items,
            }) if items == &vec![Value::String("ab".to_string()); 2]
        ));
        assert_eq!(vm.heap.live_elements(), 2);
        assert_eq!(vm.string_bytes_allocated, 4);

        let Value::Ref(matrix_handle) = matrix else {
            unreachable!("matrix constructor returns a handle")
        };
        assert_eq!(
            vm.heap.collect(&[matrix_handle]),
            1,
            "the unrooted returned array is collectible"
        );
        assert!(vm.heap.get(handle).is_none());
        assert_eq!(
            vm.heap.live_elements(),
            0,
            "collecting transferred cells must release their original charge"
        );
    }
}

