#[test]
fn matrix_eigenvalues_diagonal_are_descending_diagonal() {
    // Diagonal [[2,0],[0,3]] → eigenvalues {3, 2} (descending order).
    // ev[0] = 3, ev[1] = 2.
    let src = "indicator(\"M\")\n\
               a = matrix.new_float(2, 2, 0.0)\n\
               matrix.set(a, 0, 0, 2.0)\n\
               matrix.set(a, 1, 1, 3.0)\n\
               ev = matrix.eigenvalues(a)\n\
               plot(array.get(ev, 0) * 100 + array.get(ev, 1))\n";
    let got = run_plot(src, &[1.0])[0].unwrap();
    // 3*100 + 2 = 302.
    assert!((got - 302.0).abs() < 1e-6, "eigenvalues were {got}");
}

#[test]
