#[test]
fn matrix_eigenvalues_non_symmetric_is_error() {
    // [[0,1],[-1,0]] is non-symmetric (a rotation, complex spectrum).
    let src = "indicator(\"M\")\n\
               a = matrix.new_float(2, 2, 0.0)\n\
               matrix.set(a, 0, 1, 1.0)\nmatrix.set(a, 1, 0, -1.0)\n\
               ev = matrix.eigenvalues(a)\n\
               plot(array.get(ev, 0))\n";
    let outcome = run_outcome(src, &[1.0], &RunOptions::default());
    assert_eq!(outcome.errors.len(), 1, "{:?}", outcome.errors);
    assert_eq!(
        outcome.errors[0].kind,
        RuntimeErrorKind::MatrixDimensionMismatch
    );
}

#[test]
fn matrix_pinv_satisfies_moore_penrose_identity() {
    // A = [[1,0],[0,1],[1,1]] (3x2, full column rank). A⁺ is 2x3 and satisfies
    // A·A⁺·A ≈ A. Reconstruct AAᵖA and encode its 6 cells.
    let setup = "indicator(\"M\")\n\
                 a = matrix.new_float(3, 2, 0.0)\n\
                 matrix.set(a, 0, 0, 1.0)\nmatrix.set(a, 0, 1, 0.0)\n\
                 matrix.set(a, 1, 0, 0.0)\nmatrix.set(a, 1, 1, 1.0)\n\
                 matrix.set(a, 2, 0, 1.0)\nmatrix.set(a, 2, 1, 1.0)\n\
                 p = matrix.pinv(a)\n";
    // pinv shape: rows=2, cols=3.
    let shape = format!("{setup}plot(matrix.rows(p) * 10 + matrix.columns(p))\n");
    assert_eq!(run_plot(&shape, &[1.0]), vec![Some(23.0)]);
    // A·A⁺·A must reproduce A; check cell (2,1) which is 1.0.
    let recon = format!(
        "{setup}ap = matrix.mult(a, p)\n\
         apa = matrix.mult(ap, a)\n\
         plot(matrix.get(apa, 2, 0) * 100 + matrix.get(apa, 2, 1))\n"
    );
    let got = run_plot(&recon, &[1.0])[0].unwrap();
    // A[2] = [1, 1] → 1*100 + 1 = 101.
    assert!((got - 101.0).abs() < 1e-6, "A·A⁺·A row 2 was {got}");
}

#[test]
fn matrix_pinv_rank_deficient_is_error() {
    // [[1,2],[2,4]] is rank-deficient (rows linearly dependent). The
    // normal-equations Gram matrix is singular → structured error.
    let src = "indicator(\"M\")\n\
               a = matrix.new_float(2, 2, 0.0)\n\
               matrix.set(a, 0, 0, 1.0)\nmatrix.set(a, 0, 1, 2.0)\n\
               matrix.set(a, 1, 0, 2.0)\nmatrix.set(a, 1, 1, 4.0)\n\
               p = matrix.pinv(a)\n\
               plot(matrix.get(p, 0, 0))\n";
    let outcome = run_outcome(src, &[1.0], &RunOptions::default());
    assert_eq!(outcome.errors.len(), 1, "{:?}", outcome.errors);
    assert_eq!(outcome.errors[0].kind, RuntimeErrorKind::MatrixSingular);
}

#[test]
fn matrix_sort_reorders_rows_by_column() {
    // Rows [[3,10],[1,20],[2,30]]. Sort by column 0.
    let setup = "indicator(\"M\")\n\
                 a = matrix.new_float(3, 2, 0.0)\n\
                 matrix.set(a, 0, 0, 3.0)\nmatrix.set(a, 0, 1, 10.0)\n\
                 matrix.set(a, 1, 0, 1.0)\nmatrix.set(a, 1, 1, 20.0)\n\
                 matrix.set(a, 2, 0, 2.0)\nmatrix.set(a, 2, 1, 30.0)\n";
    // Ascending by col 0 → rows [1,20],[2,30],[3,10]. Encode key col and paired
    // col to prove the whole row moved: r0=(1,20) r1=(2,30) r2=(3,10).
    let asc = format!(
        "{setup}matrix.sort(a, 0, order.ascending)\n\
         plot(matrix.get(a, 0, 0) * 100000 + matrix.get(a, 0, 1) * 1000 + \
              matrix.get(a, 1, 0) * 100 + matrix.get(a, 2, 1))\n"
    );
    assert_eq!(run_plot(&asc, &[1.0]), vec![Some(120210.0)]);
    let desc = format!(
        "{setup}matrix.sort(a, 0, order.descending)\n\
         plot(matrix.get(a, 0, 0) * 1000 + matrix.get(a, 0, 1) * 100 + \
              matrix.get(a, 2, 0) * 10 + matrix.get(a, 2, 1))\n"
    );
    assert_eq!(run_plot(&desc, &[1.0]), vec![Some(4030.0)]);
    let default = format!("{setup}matrix.sort(a, 0)\nplot(matrix.get(a, 0, 0))\n");
    assert_eq!(run_plot(&default, &[1.0]), vec![Some(1.0)]);

    // Assignment aliases the same mutable matrix object.
    let alias = format!("{setup}b = a\nmatrix.sort(a, 0)\nplot(matrix.get(b, 0, 0))\n");
    assert_eq!(run_plot(&alias, &[1.0]), vec![Some(1.0)]);
}

#[test]
fn matrix_sort_supports_integer_string_and_na_keys() {
    let ints = concat!(
        "indicator(\"M\")\n",
        "a = matrix.new<int>(3, 1)\n",
        "matrix.set(a, 0, 0, 3)\n",
        "matrix.set(a, 1, 0, na)\n",
        "matrix.set(a, 2, 0, 1)\n",
        "matrix.sort(a)\n",
        "plot(matrix.get(a, 0, 0) == 1 and na(matrix.get(a, 2, 0)) ? 1 : 0)\n"
    );
    assert_eq!(run_plot(ints, &[1.0]), vec![Some(1.0)]);

    let descending = concat!(
        "indicator(\"M\")\n",
        "a = matrix.new<int>(3, 1)\n",
        "matrix.set(a, 0, 0, 3)\n",
        "matrix.set(a, 1, 0, na)\n",
        "matrix.set(a, 2, 0, 1)\n",
        "matrix.sort(a, 0, order.descending)\n",
        "plot(na(matrix.get(a, 0, 0)) ? 1 : 0)\n"
    );
    assert_eq!(run_plot(descending, &[1.0]), vec![Some(1.0)]);

    let strings = concat!(
        "indicator(\"M\")\n",
        "a = matrix.new<string>(3, 1)\n",
        "matrix.set(a, 0, 0, \"z\")\n",
        "matrix.set(a, 1, 0, \"a\")\n",
        "matrix.set(a, 2, 0, \"m\")\n",
        "matrix.sort(a)\n",
        "plot(matrix.get(a, 0, 0) == \"a\" ? 1 : 0)\n"
    );
    assert_eq!(run_plot(strings, &[1.0]), vec![Some(1.0)]);

    let empty_strings = concat!(
        "indicator(\"M\")\n",
        "a = matrix.new<string>(3, 1)\n",
        "matrix.set(a, 0, 0, \"z\")\n",
        "matrix.set(a, 1, 0, \"\")\n",
        "matrix.set(a, 2, 0, \"a\")\n",
        "matrix.sort(a)\n",
        "plot(matrix.get(a, 0, 0) == \"a\" and matrix.get(a, 2, 0) == \"\" ? 1 : 0)\n"
    );
    assert_eq!(run_plot(empty_strings, &[1.0]), vec![Some(1.0)]);

    let empty_strings_desc = concat!(
        "indicator(\"M\")\n",
        "a = matrix.new<string>(3, 1)\n",
        "matrix.set(a, 0, 0, \"z\")\n",
        "matrix.set(a, 1, 0, \"\")\n",
        "matrix.set(a, 2, 0, \"a\")\n",
        "matrix.sort(a, 0, order.descending)\n",
        "plot(matrix.get(a, 0, 0) == \"\" and matrix.get(a, 2, 0) == \"a\" ? 1 : 0)\n"
    );
    assert_eq!(run_plot(empty_strings_desc, &[1.0]), vec![Some(1.0)]);
}

#[test]
fn matrix_new_udt_and_sort_field_overloads() {
    let source = "indicator(\"UDT matrix sort\")\n\
                 type Item\n    float score\n    string name\n\
                 a = Item.new(3.0, \"c\")\n\
                 b = Item.new(1.0, \"a\")\n\
                 c = Item.new(2.0, \"b\")\n\
                 m = matrix.new<Item>(3, 1, a)\n\
                 matrix.set(m, 1, 0, b)\n\
                 matrix.set(m, 2, 0, c)\n\
                 alias = m\n\
                 matrix.sort(id=m, sort_field=\"score\")\n\
                 plot(matrix.get(alias, 0, 0).score * 100 + matrix.get(alias, 2, 0).score)\n";
    assert_eq!(run_plot(source, &[1.0]), vec![Some(103.0)]);

    let index = "indicator(\"UDT matrix sort field index\")\n\
                 type Item\n    string name\n    int score\n\
                 a = Item.new(\"a\", 1)\n\
                 b = Item.new(\"b\", 2)\n\
                 m = matrix.new<Item>(2, 1, a)\n\
                 matrix.set(m, 1, 0, b)\n\
                 matrix.sort(m, 0, order.descending, 1)\n\
                 plot(matrix.get(m, 0, 0).score)\n";
    assert_eq!(run_plot(index, &[1.0]), vec![Some(2.0)]);

    let strings = "indicator(\"UDT matrix string sort\")\n\
                   type Item\n    string key\n    int id\n\
                   a = Item.new(\"z\", 1)\n\
                   b = Item.new(\"\", 2)\n\
                   c = Item.new(\"a\", 3)\n\
                   m = matrix.new<Item>(3, 1, a)\n\
                   matrix.set(m, 1, 0, b)\n\
                   matrix.set(m, 2, 0, c)\n\
                   matrix.sort(m, sort_field=\"key\")\n\
                   plot(matrix.get(m, 0, 0).id * 100 + matrix.get(m, 2, 0).id)\n";
    assert_eq!(run_plot(strings, &[1.0]), vec![Some(302.0)]);

    let empty = "indicator(\"empty UDT matrix\")\n\
                 type Item\n    int score\n\
                 m = matrix.new<Item>()\n\
                 plot(matrix.rows(m) + matrix.columns(m))\n";
    assert_eq!(run_plot(empty, &[1.0]), vec![Some(0.0)]);

    let defaults = "indicator(\"matrix defaults\")\n\
                   a = matrix.new<float>()\n\
                   b = matrix.new<int>(rows=2)\n\
                   c = matrix.new<string>(columns=2)\n\
                   d = matrix.new<string>(1, 1)\n\
                   plot(matrix.rows(a) + matrix.columns(a) + matrix.rows(b) + matrix.columns(b) + matrix.rows(c) + matrix.columns(c))\n\
                   plot(na(matrix.get(d, 0, 0)) ? 1 : 0)\n";
    let outcome = run(
        &compile(defaults),
        &data_from_close(&[1.0]),
        &RunOptions::default(),
    );
    assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
    assert_eq!(floats(&outcome.plots[0].values), vec![Some(4.0)]);
    assert_eq!(floats(&outcome.plots[1].values), vec![Some(1.0)]);
}

