    assert_eq!(floats(&outcome.plots[0].values), vec![Some(4.0)]);
    let last = outcome.drawings.lines.last().unwrap();
    assert_eq!(last.fields.get("x1"), Some(&Value::Int(4)));
    assert_eq!(last.fields.get("y1"), Some(&Value::Float(7.5)));
    assert_eq!(last.fields.get("x2"), Some(&Value::Int(6)));
    assert_eq!(last.fields.get("y2"), Some(&Value::Float(8.5)));
