#[test]
fn drawing_methods_on_variables_and_chained_receivers_match_namespace_calls() {
    let src = r#"//@version=6
indicator("Drawing method namespace equivalence")
var line[] lines = array.new<line>()
if barstate.isfirst
    lines.push(line.new(na, na, na, na))
lines.get(0).set_xy1(bar_index, close)
lines.get(0).set_xy2(bar_index + 1, close + 1)
lines.get(0).set_color(color.red)
var label mark = label.new(na, na)
mark.set_xy(bar_index, close)
mark.set_text("ok")
mark.set_textcolor(color.blue)
plot(lines.get(0).get_x1() - bar_index, "x1 delta")
"#;
    let outcome = run_outcome(src, &[1.0, 2.0, 3.0], &RunOptions::default());
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    assert_eq!(floats(&outcome.plots[0].values), vec![Some(0.0); 3]);
    let line = outcome.drawings.lines.last().unwrap();
    assert_eq!(line.fields.get("x1"), Some(&Value::Int(2)));
    assert_eq!(line.fields.get("x2"), Some(&Value::Int(3)));
    let label = outcome.drawings.labels.last().unwrap();
    assert_eq!(
        label.fields.get("text"),
        Some(&Value::String("ok".to_string()))
    );
}

#[test]
fn line_get_price_interpolates_between_endpoints() {
    // A line from (x1=2, y1=10) to (x2=6, y2=30): slope 5/bar. At x=4 the
    // interpolated price is 10 + (4-2)*(30-10)/(6-2) = 20; extrapolating to x=8
    // gives 10 + (8-2)*20/4 = 40.
    let src = "indicator(\"D\")\n\
               ln = line.new(2, 10.0, 6, 30.0)\n\
               plot(line.get_price(ln, 4))\n\
               plot(line.get_price(ln, 8))\n";
    let outcome = run_outcome(src, &[1.0], &RunOptions::default());
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    assert_eq!(floats(&outcome.plots[0].values), vec![Some(20.0)]);
    assert_eq!(floats(&outcome.plots[1].values), vec![Some(40.0)]);
}

