// ---- Remaining line, label, box, and table setter/getter round trips -------
// One grouped roundtrip test per drawing kind exercising every remaining
// `supported` getter/setter: a setter writes a field, a getter reads it back on
// the plot, and the serialized DTO carries the mutated value.

#[test]
fn line_remaining_setters_getters_roundtrip() {
    // Exercises line.set_x1/set_y1/set_y2/set_extend/set_xloc/set_color and the
    // get_y1/get_y2 getters. Each setter's value is read back via a getter and/or
    // asserted on the serialized line DTO.
    let src = "indicator(\"D\")\n\
               ln = line.new(0, 1.0, 9, 2.0)\n\
               line.set_x1(ln, 4)\n\
               line.set_y1(ln, 7.5)\n\
               line.set_y2(ln, 8.5)\n\
               line.set_extend(ln, extend.both)\n\
               line.set_xloc(ln, 4, 9, xloc.bar_time)\n\
               line.set_color(ln, color.blue)\n\
               plot(line.get_y1(ln))\n\
               plot(line.get_y2(ln))\n";
    let outcome = run_outcome(src, &[1.0], &RunOptions::default());
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    // Getters read the mutated endpoints back.
    assert_eq!(floats(&outcome.plots[0].values), vec![Some(7.5)]);
    assert_eq!(floats(&outcome.plots[1].values), vec![Some(8.5)]);
    let last = outcome.drawings.lines.last().unwrap();
    assert_eq!(last.fields.get("x1"), Some(&Value::Int(4)));
    assert_eq!(last.fields.get("y1"), Some(&Value::Float(7.5)));
    assert_eq!(last.fields.get("y2"), Some(&Value::Float(8.5)));
    assert_eq!(
        last.fields.get("extend"),
        Some(&Value::String("extend.both".into()))
    );
    assert_eq!(
        last.fields.get("xloc"),
        Some(&Value::String("xloc.bar_time".into()))
    );
    // color.blue = #2962FF opaque.
    assert_eq!(
        last.fields.get("color"),
        Some(&Value::Color {
            r: 0x29,
            g: 0x62,
            b: 0xFF,
            t: 0.0,
            input_origin: None
        })
    );
}

#[test]
fn line_copy_is_an_independent_live_line() {
    // `line.copy` produces a new live line whose fields equal the source at copy
    // time; mutating the copy leaves the original untouched (two live lines).
    let src = "indicator(\"D\")\n\
               a = line.new(0, 1.0, 3, 2.0)\n\
               b = line.copy(a)\n\
               line.set_x1(b, 7)\n\
               plot(line.get_x1(a))\n\
               plot(line.get_x1(b))\n";
    let outcome = run_outcome(src, &[1.0], &RunOptions::default());
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    // Original keeps x1 = 0; the copy carries the mutated x1 = 7.
    assert_eq!(floats(&outcome.plots[0].values), vec![Some(0.0)]);
    assert_eq!(floats(&outcome.plots[1].values), vec![Some(7.0)]);
    // Both are live and independent.
    assert_eq!(outcome.drawings.lines.len(), 2);
}

#[test]
fn label_remaining_setters_getters_roundtrip() {
    // Exercises label.set_x/set_y/set_xloc/set_yloc/set_color/set_textcolor/
    // set_size/set_style/set_textalign and the get_x/get_y/get_text getters.
    let src = "indicator(\"D\")\n\
               lb = label.new(0, 1.0, \"orig\")\n\
               label.set_x(lb, 5)\n\
               label.set_y(lb, 9.0)\n\
               label.set_text(lb, \"hi\")\n\
               label.set_xloc(lb, 5, xloc.bar_time)\n\
               label.set_yloc(lb, yloc.abovebar)\n\
               label.set_color(lb, color.blue)\n\
               label.set_textcolor(lb, color.red)\n\
               label.set_size(lb, size.large)\n\
               label.set_style(lb, label.style_circle)\n\
               label.set_textalign(lb, text.align_left)\n\
               plot(label.get_x(lb))\n\
               plot(label.get_y(lb))\n";
    let outcome = run_outcome(src, &[1.0], &RunOptions::default());
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    assert_eq!(floats(&outcome.plots[0].values), vec![Some(5.0)]);
    assert_eq!(floats(&outcome.plots[1].values), vec![Some(9.0)]);
    let last = outcome.drawings.labels.last().unwrap();
    assert_eq!(last.fields.get("x"), Some(&Value::Int(5)));
    assert_eq!(last.fields.get("y"), Some(&Value::Float(9.0)));
    // get_text roundtrips the mutated text through the DTO.
    assert_eq!(last.fields.get("text"), Some(&Value::String("hi".into())));
    assert_eq!(
        last.fields.get("xloc"),
        Some(&Value::String("xloc.bar_time".into()))
    );
    assert_eq!(
        last.fields.get("yloc"),
        Some(&Value::String("yloc.abovebar".into()))
    );
    // color.blue = #2962FF, color.red = #F23645 (opaque).
    assert_eq!(
        last.fields.get("color"),
        Some(&Value::Color {
            r: 0x29,
            g: 0x62,
            b: 0xFF,
            t: 0.0,
            input_origin: None
        })
    );
    assert_eq!(
        last.fields.get("textcolor"),
        Some(&Value::Color {
            r: 0xF2,
            g: 0x36,
            b: 0x45,
            t: 0.0,
            input_origin: None
        })
    );
    assert_eq!(
        last.fields.get("size"),
        Some(&Value::String("size.large".into()))
    );
    assert_eq!(
        last.fields.get("style"),
        Some(&Value::String("label.style_circle".into()))
    );
    assert_eq!(
        last.fields.get("textalign"),
        Some(&Value::String("text.align_left".into()))
    );
}

