#[test]
fn box_table_polyline_linefill_all_arrays_hold_live_objects() {
    // `box.all`/`table.all`/`polyline.all`/`linefill.all` are per-kind arrays of
    // the live objects, via the same READ_DRAWINGS_ALL opcode. Each size is
    // asserted so every `*.all` accessor pins a concrete value.
    let src = "indicator(\"D\")\n\
               if bar_index == 0\n\
               \x20   box.new(0, 5.0, 2, 1.0)\n\
               \x20   box.new(1, 6.0, 3, 2.0)\n\
               \x20   table.new(position.top_left, 1, 1)\n\
               \x20   la = line.new(0, 1.0, 1, 2.0)\n\
               \x20   lb = line.new(2, 3.0, 3, 4.0)\n\
               \x20   linefill.new(la, lb, color.red)\n\
               \x20   pts = array.new<chart.point>()\n\
               \x20   array.push(pts, chart.point.from_index(0, 1.0))\n\
               \x20   polyline.new(pts)\n\
               plot(array.size(box.all))\n\
               plot(array.size(table.all))\n\
               plot(array.size(polyline.all))\n\
               plot(array.size(linefill.all))\n";
    let outcome = run_outcome(src, &[1.0, 2.0], &RunOptions::default());
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    assert_eq!(floats(&outcome.plots[0].values), vec![Some(2.0), Some(2.0)]);
    assert_eq!(floats(&outcome.plots[1].values), vec![Some(1.0), Some(1.0)]);
    assert_eq!(floats(&outcome.plots[2].values), vec![Some(1.0), Some(1.0)]);
    assert_eq!(floats(&outcome.plots[3].values), vec![Some(1.0), Some(1.0)]);
}

