#[test]
fn table_setter_on_na_receiver_is_runtime_error_not_panic() {
    // A table setter on an `na` receiver raises a structured runtime error
    // (NaFieldAccess), never a Rust panic.
    let src = "indicator(\"D\")\n\
               type Holder\n    table t = na\n\
               h = Holder.new()\n\
               table.set_frame_width(h.t, 3)\n\
               plot(close)\n";
    let outcome = run_outcome(src, &[1.0], &RunOptions::default());
    assert!(
        outcome
            .errors
            .iter()
            .any(|e| e.kind == RuntimeErrorKind::NaFieldAccess),
        "expected na-field-access error, got {:?}",
        outcome.errors
    );
}

