#[test]
fn same_position_table_new_replaces_cells_and_makes_old_aliases_na() {
    let source = r#"//@version=6
indicator("Table position replacement")
var table original = table.new(position.top_left, 1, 1)
var table alias = original
var array<table> saved = array.new_table()
array.push(saved, original)
if barstate.isfirst
    table.cell(original, 0, 0, "old")
table replacement = table.new(position.top_left, 2, 1, force_overlay = true)
table.cell(replacement, 1, 0, "new")
plot(na(original) ? 1 : 0)
plot(na(alias) ? 1 : 0)
plot(na(array.get(saved, 0)) ? 1 : 0)
plot(array.size(table.all))
"#;
    let outcome = run_outcome(source, &[1.0, 2.0], &RunOptions::default());
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    for plot in &outcome.plots[..3] {
        assert_eq!(floats(&plot.values), vec![Some(1.0); 2]);
    }
    assert_eq!(floats(&outcome.plots[3].values), vec![Some(1.0); 2]);
    assert_eq!(outcome.drawings.tables.len(), 1);
    assert_eq!(
        outcome.drawings.tables[0].fields.get("columns"),
        Some(&Value::Int(2))
    );
    assert_eq!(outcome.drawings.tables[0].cells.len(), 1);
    assert_eq!(
        (
            outcome.drawings.tables[0].cells[0].column,
            outcome.drawings.tables[0].cells[0].row
        ),
        (1, 0)
    );
    assert_eq!(
        outcome.drawings.tables[0].cells[0].attrs.get("text"),
        Some(&Value::String("new".into()))
    );

    let program = compile(source);
    let data = data_from_close(&[1.0]);
    let mut vm = crate::Vm::new(&program, &data, &RunOptions::default()).unwrap();
    let (_, errors) = vm.run_history();
    assert!(errors.is_empty(), "errors: {errors:?}");
    let table_slot = crate::DrawingRegistry::slot_of(pinewasm_hir::DrawKind::Table)
        .expect("tables are a registered drawing kind");
    let table_type = program
        .object_types
        .iter()
        .position(|object_type| object_type.name == "table")
        .expect("table object type") as u32;
    let old_table = (0..vm.heap.arena_len())
        .map(|index| HandleId(index as u32))
        .find(|&handle| {
            matches!(vm.heap.get(handle),
                Some(HeapObj::Object { type_id, fields, .. })
                    if *type_id == table_type && fields.get(1) == Some(&Value::Int(1)))
        })
        .expect("the displaced table remains allocated until collection");
    assert_eq!(vm.drawings.live[table_slot].len(), 1);
    assert_eq!(vm.drawings.table_cells.len(), 1);
    assert!(!vm.drawings.table_cells.contains_key(&old_table.0));
    assert!(!vm.gc_roots().contains(&old_table));
    vm.gc_threshold = 0;
    vm.gc_elem_threshold = 0;
    vm.maybe_collect_heap();
    assert!(vm.heap.get(old_table).is_none());
}

