#[test]
fn table_replacement_alias_rewrite_is_metered_before_side_effects() {
    let program = compile("indicator(\"Metered replacement\")\ntable t = na\nplot(close)\n");
    let data = data_from_close(&[1.0]);
    let mut vm = crate::Vm::new(&program, &data, &RunOptions::default()).unwrap();
    let table_type = program
        .object_types
        .iter()
        .position(|object_type| object_type.name == "table")
        .expect("table object type") as u32;
    let field_count = program.object_types[table_type as usize].field_count as usize;
    let position = crate::DrawKind::Table.field_index("position").unwrap() as usize;
    let columns = crate::DrawKind::Table.field_index("columns").unwrap() as usize;
    let rows = crate::DrawKind::Table.field_index("rows").unwrap() as usize;
    let mut fields = vec![Value::Na; field_count];
    fields[position] = Value::String("position.top_left".into());
    fields[columns] = Value::Int(1);
    fields[rows] = Value::Int(1);
    let old = vm
        .heap
        .alloc(HeapObj::Object {
            table_identity: None,
            type_id: table_type,
            fields: fields.clone(),
        })
        .unwrap();
    fields[columns] = Value::Int(2);
    let new = vm
        .heap
        .alloc(HeapObj::Object {
            table_identity: None,
            type_id: table_type,
            fields,
        })
        .unwrap();
    let table_slot = crate::DrawingRegistry::slot_of(pinewasm_hir::DrawKind::Table).unwrap();
    vm.stack.push(Value::Ref(old));
    vm.exec_register_drawing(pinewasm_hir::DrawKind::Table, 0, &mut 1_000_000)
        .unwrap();
    assert_eq!(vm.stack.pop(), Some(Value::Ref(old)));
    vm.drawings
        .table_cells
        .insert(old.0, crate::TableGrid::default());
    vm.user_slots[0][0] = Value::Ref(old);
    vm.stack.push(Value::Ref(new));

    let mut budget = 0;
    let error = vm
        .exec_register_drawing(pinewasm_hir::DrawKind::Table, 0, &mut budget)
        .unwrap_err();
    assert_eq!(error.kind, RuntimeErrorKind::InstructionLimitExceeded);
    assert_eq!(vm.user_slots[0][0], Value::Ref(old));
    assert_eq!(vm.drawings.live[table_slot], vec![old]);
    assert!(vm.drawings.table_cells.contains_key(&old.0));
}

