#[test]
fn table_delete_alias_rewrite_is_metered_before_side_effects() {
    let program = compile("indicator(\"Metered delete\")\ntable t = na\nplot(close)\n");
    let data = data_from_close(&[1.0]);
    let mut vm = crate::Vm::new(&program, &data, &RunOptions::default()).unwrap();
    let type_id = program
        .object_types
        .iter()
        .position(|object_type| object_type.name == "table")
        .expect("table object type") as u32;
    let field_count = program.object_types[type_id as usize].field_count as usize;
    let handle = vm
        .heap
        .alloc(HeapObj::Object {
            type_id,
            fields: vec![Value::Na; field_count],
            table_identity: None,
        })
        .unwrap();
    let slot = crate::DrawingRegistry::slot_of(pinewasm_hir::DrawKind::Table).unwrap();
    vm.drawings.live[slot].push(handle);
    vm.drawings.ids[slot].push(vm.drawings.next_id);
    vm.drawings.next_id = vm.drawings.next_id.wrapping_add(1);
    vm.drawings
        .table_cells
        .insert(handle.0, crate::TableGrid::default());
    vm.user_slots[0][0] = Value::Ref(handle);
    vm.stack.push(Value::Ref(handle));

    // The dispatch unit is outside this host call. A zero remainder cannot
    // cover the observable-slot and reachable-heap rewrite work.
    let mut budget = 0;
    let error = vm
        .exec_delete_drawing(pinewasm_hir::DrawKind::Table, 0, &mut budget)
        .unwrap_err();
    assert_eq!(error.kind, RuntimeErrorKind::InstructionLimitExceeded);
    assert_eq!(vm.user_slots[0][0], Value::Ref(handle));
    assert!(vm.drawings.live[slot].contains(&handle));
    assert!(vm.drawings.table_cells.contains_key(&handle.0));
}

#[test]
fn table_delete_heap_plan_stops_at_remaining_work_budget_before_mutation() {
    let program = compile(
        "indicator(\"Bounded table delete\")\ntable t = na\nvar array<table> ids = array.new_table()\nplot(close)\n",
    );
    let data = data_from_close(&[1.0]);
    let mut vm = crate::Vm::new(&program, &data, &RunOptions::default()).unwrap();
    let table_type = program
        .object_types
        .iter()
        .position(|object_type| object_type.name == "table")
        .expect("table object type") as u32;
    let field_count = program.object_types[table_type as usize].field_count as usize;
    let table = vm
        .heap
        .alloc(HeapObj::Object {
            table_identity: None,
            type_id: table_type,
            fields: vec![Value::Na; field_count],
        })
        .unwrap();
    let array = vm
        .heap
        .alloc(HeapObj::Array {
            elem_ty: ElemType::Object(table_type),
            items: vec![Value::Ref(table); 256],
        })
        .unwrap();
    let ids_slot = program
        .series_slots
        .iter()
        .position(|slot| slot.name == "ids")
        .expect("array alias slot");
    vm.user_slots[ids_slot][0] = Value::Ref(array);
    let table_registry_slot =
        crate::DrawingRegistry::slot_of(pinewasm_hir::DrawKind::Table).unwrap();
    vm.drawings.live[table_registry_slot].push(table);
    vm.drawings.ids[table_registry_slot].push(vm.drawings.next_id);
    vm.drawings.next_id = vm.drawings.next_id.wrapping_add(1);
    vm.drawings
        .table_cells
        .insert(table.0, crate::TableGrid::default());
    vm.stack.push(Value::Ref(table));

    // Leave exactly one unit after charging two direct slot values and the
    // slot/stack/call-argument headers. Planning must stop at the first array
    // value and refuse before changing the array or table registry.
    let direct_slot_values = vm.user_slots.len() as u64;
    let direct_scan_work = direct_slot_values
        .saturating_mul(2)
        .saturating_add(direct_slot_values.saturating_mul(3))
        .saturating_add(4);
    let mut budget = direct_scan_work.saturating_add(1);
    let error = vm
        .exec_delete_drawing(pinewasm_hir::DrawKind::Table, 0, &mut budget)
        .unwrap_err();
    assert_eq!(error.kind, RuntimeErrorKind::InstructionLimitExceeded);
    assert_eq!(vm.user_slots[ids_slot][0], Value::Ref(array));
    assert!(matches!(
        vm.heap.get(array),
        Some(HeapObj::Array { items, .. }) if items[0] == Value::Ref(table)
    ));
    assert!(vm.drawings.live[table_registry_slot].contains(&table));
    assert!(vm.drawings.table_cells.contains_key(&table.0));
}

#[test]
fn realtime_table_delete_rollback_restores_historical_aliases_and_grid() {
    let source = r#"//@version=6
indicator("Realtime table rollback")
var table t = table.new(position.top_left, 1, 1)
table.cell(t, 0, 0, "kept")
if barstate.isrealtime and barstate.isnew
    table.delete(t)
plot(na(t[1]) ? 1 : 0, "Prior alias")
plot(na(t) ? 1 : 0, "Current alias")
"#;
    let outcome = run_outcome(
        source,
        &[10.0, 20.0],
        &RunOptions {
            realtime_trace: true,
            realtime: Some(RealtimeSim {
                ticks: vec![tick(2, 30.0, false), tick(2, 31.0, true)],
            }),
            ..RunOptions::default()
        },
    );
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    let trace = outcome.realtime_trace.expect("realtime trace");
    assert_eq!(trace.len(), 2);
    assert_eq!(floats(&trace[0].values), vec![Some(1.0), Some(1.0)]);
    assert_eq!(floats(&trace[1].values), vec![Some(0.0), Some(0.0)]);
    assert_eq!(
        floats(&outcome.plots[0].values),
        vec![Some(1.0), Some(0.0), Some(0.0)]
    );
    assert_eq!(
        floats(&outcome.plots[1].values),
        vec![Some(0.0), Some(0.0), Some(0.0)]
    );
    assert_eq!(outcome.drawings.tables.len(), 1);
    assert_eq!(outcome.drawings.tables[0].cells.len(), 1);
    assert_eq!(
        outcome.drawings.tables[0].cells[0].attrs.get("text"),
        Some(&Value::String("kept".to_owned()))
    );
}

