#[test]
fn realtime_alias_journal_memory_refusal_leaves_table_state_unchanged() {
    let program =
        compile("indicator(\"Alias journal bytes\")\ntable t = na\nplot(na(t[1]) ? 1.0 : 0.0)\n");
    let data = data_from_close(&[10.0, 20.0]);
    let mut vm = crate::Vm::new(&program, &data, &RunOptions::default()).unwrap();
    let slot = program
        .series_slots
        .iter()
        .position(|slot| slot.name == "t")
        .expect("table slot");
    let table_type = program
        .object_types
        .iter()
        .position(|object_type| object_type.name == "table")
        .expect("table object type") as u32;
    let field_count = program.object_types[table_type as usize].field_count as usize;
    let table = vm
        .heap
        .alloc(HeapObj::Object {
            table_identity: None,
            type_id: table_type,
            fields: vec![Value::Na; field_count],
        })
        .unwrap();
    vm.bar = 1;
    let current = vm.bar & vm.slot_mask;
    let previous = (vm.bar - 1) & vm.slot_mask;
    assert_ne!(current, previous, "the test needs two history cells");
    vm.user_slots[slot][current] = Value::Ref(table);
    vm.user_slots[slot][previous] = Value::Ref(table);
    vm.realtime_active = true;
    vm.realtime_bar = Some(vm.bar);

    let table_registry_slot =
        crate::DrawingRegistry::slot_of(pinewasm_hir::DrawKind::Table).unwrap();
    vm.drawings.live[table_registry_slot].push(table);
    vm.drawings.ids[table_registry_slot].push(vm.drawings.next_id);
    vm.drawings.next_id = vm.drawings.next_id.wrapping_add(1);
    let mut grid = crate::TableGrid::default();
    grid.cells.insert(
        (0, 0),
        crate::TableCell {
            width: Some(Value::Int(1)),
            ..Default::default()
        },
    );
    vm.drawings.table_cells.insert(table.0, grid);
    vm.reserve_vm_bytes(crate::TABLE_CELL_RESERVATION_BYTES, 0)
        .expect("the test cell fits the existing VM budget");
    vm.stack.push(Value::Ref(table));

    let reserved = vm.bytes_reserved;
    let journal_bytes = crate::REALTIME_ALIAS_UNDO_ENTRY_RESERVATION_BYTES;
    std::sync::Arc::make_mut(&mut vm.options).max_vm_bytes_per_run = reserved + journal_bytes - 1;
    let mut instruction_budget = 1_000_000;
    let error = vm
        .exec_delete_drawing(pinewasm_hir::DrawKind::Table, 0, &mut instruction_budget)
        .unwrap_err();

    assert_eq!(error.kind, RuntimeErrorKind::VmMemoryLimitExceeded);
    assert_eq!(vm.bytes_reserved, reserved);
    assert!(vm.realtime_alias_undo.is_empty());
    assert_eq!(vm.user_slots[slot][current], Value::Ref(table));
    assert_eq!(vm.user_slots[slot][previous], Value::Ref(table));
    assert!(vm.drawings.live[table_registry_slot].contains(&table));
    let cell = vm
        .drawings
        .table_cells
        .get(&table.0)
        .and_then(|grid| grid.cells.get(&(0, 0)))
        .expect("cell grid remains live");
    assert_eq!(cell.width, Some(Value::Int(1)));
}

#[test]
fn realtime_table_replacement_alias_journal_memory_refusal_is_atomic() {
    let program = compile(
        "indicator(\"Replacement journal bytes\")\ntable t = na\nplot(na(t[1]) ? 1.0 : 0.0)\n",
    );
    let data = data_from_close(&[10.0, 20.0]);
    let mut vm = crate::Vm::new(&program, &data, &RunOptions::default()).unwrap();
    let slot = program
        .series_slots
        .iter()
        .position(|slot| slot.name == "t")
        .expect("table slot");
    let table_type = program
        .object_types
        .iter()
        .position(|object_type| object_type.name == "table")
        .expect("table object type") as u32;
    let field_count = program.object_types[table_type as usize].field_count as usize;
    let position = pinewasm_hir::DrawKind::Table
        .field_index("position")
        .expect("table position field") as usize;
    let mut old_fields = vec![Value::Na; field_count];
    old_fields[position] = Value::String("position.top_left".into());
    old_fields[1] = Value::Int(1);
    old_fields[2] = Value::Int(1);
    let old = vm
        .heap
        .alloc(HeapObj::Object {
            table_identity: None,
            type_id: table_type,
            fields: old_fields.clone(),
        })
        .unwrap();
    let mut new_fields = old_fields.clone();
    new_fields[1] = Value::Int(2);
    let new = vm
        .heap
        .alloc(HeapObj::Object {
            table_identity: None,
            type_id: table_type,
            fields: new_fields,
        })
        .unwrap();
    vm.bar = 1;
    let current = vm.bar & vm.slot_mask;
    let previous = (vm.bar - 1) & vm.slot_mask;
    assert_ne!(current, previous, "the test needs two history cells");
    vm.user_slots[slot][current] = Value::Ref(old);
    vm.user_slots[slot][previous] = Value::Ref(old);
    vm.realtime_active = true;
    vm.realtime_bar = Some(vm.bar);

    let table_registry_slot =
        crate::DrawingRegistry::slot_of(pinewasm_hir::DrawKind::Table).unwrap();
    vm.stack.push(Value::Ref(old));
    vm.exec_register_drawing(pinewasm_hir::DrawKind::Table, 0, &mut 1_000_000)
        .unwrap();
    assert_eq!(vm.stack.pop(), Some(Value::Ref(old)));
    let mut grid = crate::TableGrid::default();
    grid.cells.insert(
        (0, 0),
        crate::TableCell {
            text: Some(Value::String("old".into())),
            ..Default::default()
        },
    );
    vm.drawings.table_cells.insert(old.0, grid);
    vm.reserve_vm_bytes(crate::TABLE_CELL_RESERVATION_BYTES, 0)
        .expect("the test cell fits the existing VM budget");
    vm.stack.push(Value::Ref(new));

    let reserved = vm.bytes_reserved;
    let journal_bytes = crate::REALTIME_ALIAS_UNDO_ENTRY_RESERVATION_BYTES;
    std::sync::Arc::make_mut(&mut vm.options).max_vm_bytes_per_run = reserved + journal_bytes - 1;
    let mut instruction_budget = 1_000_000;
    let error = vm
        .exec_register_drawing(pinewasm_hir::DrawKind::Table, 0, &mut instruction_budget)
        .unwrap_err();

    assert_eq!(error.kind, RuntimeErrorKind::VmMemoryLimitExceeded);
    assert_eq!(vm.bytes_reserved, reserved);
    assert_eq!(vm.last_table_identity, 1);
    assert!(matches!(
        vm.heap.get(new),
        Some(HeapObj::Object {
            table_identity: None,
            ..
        })
    ));
    assert!(vm.realtime_alias_undo.is_empty());
    assert_eq!(vm.user_slots[slot][current], Value::Ref(old));
    assert_eq!(vm.user_slots[slot][previous], Value::Ref(old));
    assert_eq!(vm.drawings.live[table_registry_slot], vec![old]);
    assert_eq!(
        vm.drawings.table_cells[&old.0].cells[&(0, 0)].text,
        Some(Value::String("old".into()))
    );
}

#[test]
fn table_cell_after_delete_matches_na_receiver_for_direct_and_array_aliases() {
    let explicit_na = run_outcome(
        "indicator(\"Deleted table cell\")\ntable t = na\ntable.cell(t, 0, 0, \"x\")\nplot(close)\n",
        &[1.0],
        &RunOptions::default(),
    );
    assert_eq!(explicit_na.errors.len(), 1);
    assert_eq!(explicit_na.errors[0].kind, RuntimeErrorKind::NaFieldAccess);

    let deleted_sources = [
        "indicator(\"Deleted table cell\")\ntable t = table.new(position.top_left, 1, 1)\ntable.delete(t)\ntable.cell(t, 0, 0, \"x\")\nplot(close)\n",
        "indicator(\"Deleted table cell\")\ntable t = table.new(position.top_left, 1, 1)\nvar array<table> ids = array.new_table()\narray.push(ids, t)\ntable.delete(t)\ntable.cell(array.get(ids, 0), 0, 0, \"x\")\nplot(close)\n",
    ];
    for src in deleted_sources {
        let outcome = run_outcome(src, &[1.0], &RunOptions::default());
        assert_eq!(outcome.errors.len(), 1, "source: {src}");
        assert_eq!(
            outcome.errors[0].kind, explicit_na.errors[0].kind,
            "source: {src}"
        );
        assert!(outcome.drawings.tables.is_empty(), "source: {src}");
    }
}

