#[test]
fn table_cell_reordered_named_arguments_evaluate_in_parameter_order() {
    // Arguments are evaluated in parameter order, so this script plots 1234.
    let src = r#"//@version=6
indicator("Named table evaluation order check")
var int[] order = array.new_int()
var table t = table.new(position.top_right, 1, 1)
f_table() =>
    array.push(order, 1)
    t
f_column() =>
    array.push(order, 2)
    0
f_row() =>
    array.push(order, 3)
    0
f_text() =>
    array.push(order, 4)
    "ok"
array.clear(order)
table.cell(text = f_text(), row = f_row(), column = f_column(), table_id = f_table())
plot(array.get(order, 0) * 1000 + array.get(order, 1) * 100 + array.get(order, 2) * 10 + array.get(order, 3), "Evaluation order")
"#;
    assert_eq!(run_plot(src, &[1.0, 2.0, 3.0]), vec![Some(1234.0); 3]);
}

/// A Pine expression of the parameter's type for the drawing evaluation-order
/// checks below. Style tokens come from the member's own namespace.
fn drawing_order_check_value(callee: &str, name: &str, ty: &pinewasm_hir::Type) -> String {
    use pinewasm_hir::Type;
    let token = match name {
        "xloc" => Some("xloc.bar_index"),
        "yloc" => Some("yloc.price"),
        "extend" => Some("extend.none"),
        "style" if callee.starts_with("label.") => Some("label.style_label_down"),
        "style" | "border_style" | "line_style" => Some("line.style_solid"),
        "size" => Some("size.normal"),
        "textalign" | "text_halign" | "text_valign" => Some("text.align_center"),
        "text_wrap" => Some("text.wrap_none"),
        "text_font_family" => Some("font.family_default"),
        "text_formatting" => Some("text.format_none"),
        "text_size" if *ty == Type::String => Some("size.normal"),
        _ => None,
    };
    if let Some(token) = token {
        return token.to_string();
    }
    match ty {
        Type::Int => "bar_index".into(),
        Type::Float => "close".into(),
        Type::String => "\"ok\"".into(),
        Type::Color => "color.red".into(),
        Type::Bool => "false".into(),
        Type::Object(kind) => match kind.as_str() {
            "line" => "ln".into(),
            "label" => "lb".into(),
            "box" => "bx".into(),
            "polyline" => "pl".into(),
            "linefill" => "lf".into(),
            "chart.point" => "chart.point.from_index(bar_index, close)".into(),
            other => panic!("`{callee}` parameter `{name}`: no check value for {other}"),
        },
        Type::Array(elem) if **elem == Type::Object("chart.point".into()) => "pts".into(),
        other => panic!("`{callee}` parameter `{name}`: no check value for {other:?}"),
    }
}

/// One evaluation-order check per overload in PineWASM's drawing surface
/// (every line, label, box, polyline and linefill member that takes two or
/// more expressions), built
/// like the table.cell check above. Each argument comes from a helper that
/// pushes its parameter position to `order`, and the call names every
/// argument in REVERSE parameter order. The script plots `order`, one plot
/// per position. `force_overlay` is left out: it accepts only a `const`
/// argument, which a helper call cannot be.
fn drawing_order_checks() -> Vec<(String, usize, String)> {
    let mut probes = Vec::new();
    for spec in pinewasm_hir::drawing::drawing_function_surface() {
        let namespace = spec.name.split('.').next().unwrap_or_default();
        if !matches!(
            namespace,
            "line" | "label" | "box" | "polyline" | "linefill"
        ) {
            continue;
        }
        for (overload, params) in spec.overloads.iter().enumerate() {
            let params: Vec<_> = params
                .iter()
                .filter(|param| param.required_qualifier.is_none())
                .collect();
            if params.len() < 2 {
                continue;
            }
            let mut src = String::from(
                "//@version=6\n\
                 indicator(\"Named drawing evaluation order check\", overlay = true)\n\
                 var int[] order = array.new_int()\n\
                 ln = line.new(bar_index, close, bar_index, close)\n\
                 ln2 = line.new(bar_index, close, bar_index, close)\n\
                 lb = label.new(bar_index, close)\n\
                 bx = box.new(bar_index, close, bar_index, close)\n\
                 pts = array.from(chart.point.from_index(bar_index, close), chart.point.from_index(bar_index, close))\n\
                 pl = polyline.new(pts)\n\
                 lf = linefill.new(ln, ln2, color.red)\n",
            );
            for (position, param) in params.iter().enumerate() {
                src.push_str(&format!(
                    "f_{}() =>\n    array.push(order, {})\n    {}\n",
                    param.name,
                    position + 1,
                    drawing_order_check_value(&spec.name, &param.name, &param.ty)
                ));
            }
            src.push_str("array.clear(order)\n");
            let reversed: Vec<String> = params
                .iter()
                .rev()
                .map(|param| format!("{0} = f_{0}()", param.name))
                .collect();
            src.push_str(&format!("{}({})\n", spec.name, reversed.join(", ")));
            for position in 0..params.len() {
                src.push_str(&format!(
                    "plot(array.size(order) > {position} ? array.get(order, {position}) : -1, \"Position {position}\")\n"
                ));
            }
            probes.push((format!("{}#{overload}", spec.name), params.len(), src));
        }
    }
    probes
}

#[test]
fn drawing_members_evaluate_reversed_named_arguments_in_parameter_order() {
    // Named arguments are evaluated in parameter order (the
    // table.cell test above pins 1234). Every line,
    // label, box, polyline and linefill constructor and setter must agree,
    // whatever order the names are written in.
    let probes = drawing_order_checks();
    for name in [
        "line.new#0",
        "line.new#1",
        "label.new#0",
        "label.new#1",
        "box.new#0",
        "box.new#1",
        "polyline.new#0",
        "linefill.new#0",
        "line.set_xy1#0",
        "label.set_xy#0",
        "box.set_lefttop#0",
        "linefill.set_color#0",
    ] {
        assert!(
            probes.iter().any(|(probe, _, _)| probe == name),
            "check `{name}` missing"
        );
    }
    let mut wrong = Vec::new();
    for (name, arity, src) in &probes {
        let program = compile(src);
        let outcome = run(
            &program,
            &data_from_close(&[1.0, 2.0]),
            &RunOptions::default(),
        );
        assert!(outcome.errors.is_empty(), "{name}: {:?}", outcome.errors);
        let observed: Vec<f64> = outcome
            .plots
            .iter()
            .map(|plot| floats(&plot.values)[1].expect("present"))
            .collect();
        let expected: Vec<f64> = (1..=*arity).map(|k| k as f64).collect();
        if observed != expected {
            wrong.push(format!("{name}: {observed:?}"));
        }
    }
    assert!(
        wrong.is_empty(),
        "written-order evaluation:\n{}",
        wrong.join("\n")
    );
}

