#[test]
fn strategy_section_present_with_seeded_equity() {
    // A strategy script produces a strategy section; with no orders yet the
    // position is flat and equity is held at initial_capital across every
    // executed bar.
    let src = "strategy(\"S\", initial_capital=10000)\nplot(close)\n";
    let outcome = run_outcome(src, &[10.0, 11.0, 12.0], &RunOptions::default());
    assert!(outcome.errors.is_empty());
    let strat = outcome.strategy.as_ref().expect("strategy section present");
    assert_eq!(strat.initial_capital, 10000.0);
    assert!(strat.trades.is_empty());
    assert_eq!(strat.position.size, 0.0);
    assert_eq!(strat.equity, vec![10000.0, 10000.0, 10000.0]);
    assert_eq!(strat.max_contracts_held, 0.0);
    assert_eq!(strat.max_contracts_held_long, 0.0);
    assert_eq!(strat.max_contracts_held_short, 0.0);
    assert_eq!(strat.margin_used, vec![0.0, 0.0, 0.0]);
    assert!(strat
        .margin_used
        .iter()
        .all(|value| value.is_sign_positive()));
    assert_eq!(strat.maximum_margin_used, 0.0);
    assert_eq!(strat.required_account_size, None);
    let report = strat.report_aggregates.as_ref().expect("report aggregates");
    assert_eq!(report.all.closed_trades, 0);
    assert_eq!(report.all.open_trades, 0);
    assert_eq!(strat.margin_calls, 0);
    assert_eq!(strat.total_liquidated, 0.0);
    assert_eq!(strat.largest_liquidation, 0.0);
    assert_eq!(strat.net_profit, 0.0);
    assert_eq!(strat.open_profit, 0.0);
}

#[test]
fn strategy_section_summary_metrics_are_flat_baseline() {
    // With no order primitives in the script the broker holds no trades, so every
    // summary metric computed by the broker-metrics core sits at its flat
    // baseline: zero profit, zero counts, zero drawdown/run-up.
    let src = "strategy(\"S\", initial_capital=25000)\nplot(close)\n";
    let outcome = run_outcome(src, &[10.0, 11.0, 12.0, 13.0], &RunOptions::default());
    assert!(outcome.errors.is_empty());
    let strat = outcome.strategy.as_ref().expect("strategy section present");
    assert_eq!(strat.gross_profit, 0.0);
    assert_eq!(strat.gross_loss, 0.0);
    assert_eq!(strat.closed_trades, 0);
    assert_eq!(strat.win_trades, 0);
    assert_eq!(strat.loss_trades, 0);
    assert_eq!(strat.even_trades, 0);
    assert_eq!(strat.avg_trade, 0.0);
    assert_eq!(strat.max_drawdown, 0.0);
    assert_eq!(strat.max_runup, 0.0);
    // Equity stays at initial_capital + net(0) + open(0) on every bar.
    assert_eq!(strat.equity, vec![25000.0; 4]);
}

