// ---------------------------------------------------------------------------
// Strategy broker: order primitives and fill loop.
//
// Every fill rule and metric below is asserted against the exact value the
// broker produces through `RunOutcome.strategy`. Fixture: valid/strategy_orders.pine.
// ---------------------------------------------------------------------------

/// Compile+run a strategy source over an OHLC feed and return the full run
/// outcome (so tests can read the plotted `strategy.*` getter series). Panics
/// with the run errors if execution aborted.
fn run_strategy_full(source: &str, bars: &[(f64, f64, f64, f64)]) -> crate::RunOutcome {
    let program = compile(source);
    let data = ohlc_data(bars);
    let outcome = run(&program, &data, &RunOptions::default());
    assert!(
        outcome.errors.is_empty(),
        "run errors: {:?}",
        outcome.errors
    );
    outcome
}

/// Compile+run a strategy source over an OHLC feed and return its (required)
/// strategy outcome. Panics with the run errors if execution aborted.
fn run_strategy(source: &str, bars: &[(f64, f64, f64, f64)]) -> crate::StrategyOutcome {
    let program = compile(source);
    let data = ohlc_data(bars);
    let outcome = run(&program, &data, &RunOptions::default());
    assert!(
        outcome.errors.is_empty(),
        "run errors: {:?}",
        outcome.errors
    );
    outcome
        .strategy
        .expect("strategy scripts carry a strategy outcome")
}

/// A minimal strategy header with an explicit initial capital and unit qty and
/// no commission/slippage, so fills are exact.
const HDR: &str = "//@version=6\nstrategy(\"S\", initial_capital=10000, default_qty_value=1)\n";

#[test]
fn market_entry_fills_next_bar_open() {
    // Enter long on bar 0 (only on the first bar); it fills at bar 1's OPEN.
    let src =
        format!("{HDR}if bar_index == 0\n    strategy.entry(\"L\", strategy.long)\nplot(close)\n");
    // bar0 O=10, bar1 O=12 (the fill price), bar2 O=15.
    let s = run_strategy(
        &src,
        &[
            (10.0, 11.0, 9.0, 10.0),
            (12.0, 13.0, 11.0, 12.5),
            (15.0, 16.0, 14.0, 15.0),
        ],
    );
    assert_eq!(s.position.size, 1.0, "one long contract open");
    assert_eq!(
        s.position.avg_price, 12.0,
        "filled at bar 1 open, not bar 0"
    );
    assert!(s.trades.is_empty(), "entry alone opens no closed trade");
}

#[test]
fn strategy_outcome_records_margin_at_each_bar_close() {
    let src = "//@version=6\n\
               strategy(\"S\", initial_capital=1000, default_qty_value=2, margin_long=25)\n\
               if bar_index == 0\n    strategy.entry(\"L\", strategy.long)\n\
               plot(close)\n";
    let s = run_strategy(
        src,
        &[
            (10.0, 10.0, 10.0, 10.0),
            (10.0, 12.0, 10.0, 12.0),
            (12.0, 30.0, 12.0, 20.0),
        ],
    );
    // No position on bar 0. The two-contract long is marked to each later
    // close and requires 25% of current notional.
    assert_eq!(s.margin_used, vec![0.0, 6.0, 10.0]);
    assert_eq!(s.maximum_margin_used, 15.0);
    assert_eq!(s.margin_calls, 0);

    let short = run_strategy(
        "//@version=6\n\
         strategy(\"S\", initial_capital=1000, default_qty_value=2, margin_short=40)\n\
         if bar_index == 0\n    strategy.entry(\"S\", strategy.short)\n\
         plot(close)\n",
        &[
            (10.0, 10.0, 10.0, 10.0),
            (10.0, 12.0, 10.0, 12.0),
            (12.0, 30.0, 12.0, 20.0),
        ],
    );
    assert_eq!(short.margin_used, vec![0.0, 9.6, 16.0]);
    assert_eq!(short.maximum_margin_used, 24.0);
}

#[test]
fn required_account_size_adds_maximum_margin_and_intrabar_drawdown() {
    let source = |margin: u32| {
        format!(
            "//@version=6\nstrategy(\"S\", initial_capital=10000, margin_long={margin})\nif bar_index == 0\n    strategy.entry(\"L\", strategy.long, qty=1)\nif bar_index == 1\n    strategy.close_all()\nplot(close)\n"
        )
    };

    let fully_margined = run_strategy(
        &source(100),
        &[
            (100.0, 100.0, 100.0, 100.0),
            (100.0, 100.0, 80.0, 80.0),
            (80.0, 80.0, 80.0, 80.0),
        ],
    );
    assert_eq!(fully_margined.position.size, 0.0);
    assert_eq!(fully_margined.maximum_margin_used, 100.0);
    assert_eq!(fully_margined.max_drawdown, 20.0);
    assert_eq!(fully_margined.required_account_size, Some(120.0));

    let quarter_margined = run_strategy(
        &source(25),
        &[
            (400.0, 400.0, 400.0, 400.0),
            (400.0, 400.0, 300.0, 300.0),
            (300.0, 300.0, 300.0, 300.0),
        ],
    );
    assert_eq!(quarter_margined.position.size, 0.0);
    assert_eq!(quarter_margined.maximum_margin_used, 100.0);
    assert_eq!(quarter_margined.max_drawdown, 100.0);
    assert_eq!(quarter_margined.required_account_size, Some(200.0));

    let wire = serde_json::to_value(&quarter_margined).expect("serialize account size");
    assert_eq!(wire["requiredAccountSize"], 200.0);

    let pyramided = run_strategy(
        "//@version=6\nstrategy(\"S\", initial_capital=10000, pyramiding=2, margin_long=25)\nif bar_index == 0\n    strategy.entry(\"A\", strategy.long, qty=1)\n    strategy.entry(\"B\", strategy.long, qty=1)\nplot(close)\n",
        &[
            (100.0, 100.0, 100.0, 100.0),
            (100.0, 100.0, 80.0, 80.0),
        ],
    );
    assert_eq!(pyramided.maximum_margin_used, 50.0);
    // Both lots fall 20 on the same bar, and the account drawdown adds them:
    // it is 40, not the 20 of either trade on its own.
    assert_eq!(pyramided.max_drawdown, 40.0);
    assert_eq!(pyramided.required_account_size, Some(90.0));
}

#[test]
fn report_aggregates_cover_directional_closed_and_open_commission_state() {
    let closed = run_strategy(
        "//@version=6\nstrategy(\"S\", initial_capital=10000, commission_type=\"cash_per_order\", commission_value=1)\nif bar_index == 0\n    strategy.entry(\"L\", strategy.long, qty=1)\nif bar_index == 1\n    strategy.close_all()\nplot(close)\n",
        &[
            (10.0, 10.0, 10.0, 10.0),
            (10.0, 10.0, 10.0, 10.0),
            (20.0, 20.0, 20.0, 20.0),
        ],
    );
    let report = closed.report_aggregates.expect("report aggregates");
    for scope in [&report.all, &report.long] {
        assert_eq!(scope.closed_trades, 1);
        assert_eq!(scope.open_trades, 0);
        assert_eq!(scope.win_trades, 1);
        assert_eq!(scope.net_profit, 8.0);
        assert_eq!(scope.gross_profit, 8.0);
        assert_eq!(scope.gross_loss, 0.0);
        assert_eq!(scope.commission, 2.0);
        assert_eq!(scope.return_percent_sum, 80.0);
        assert_eq!(scope.return_percent_count, 1);
        assert_eq!(scope.bars_held_sum, 2);
        assert_eq!(scope.favorable_excursion_sum, 9.0);
        assert_eq!(scope.adverse_excursion_sum, 1.0);
        assert_eq!(
            scope.largest_winning_trade.as_ref().map(|trade| (
                trade.trade_index,
                trade.entry_id.as_str(),
                trade.pnl
            )),
            Some((0, "L", 8.0))
        );
    }
    assert_eq!(report.short.closed_trades, 0);

    let open = run_strategy(
        "//@version=6\nstrategy(\"S\", initial_capital=10000, commission_type=\"cash_per_order\", commission_value=5)\nif bar_index == 0\n    strategy.entry(\"L\", strategy.long, qty=1)\nplot(close)\n",
        &[(10.0, 10.0, 10.0, 10.0), (10.0, 10.0, 10.0, 10.0)],
    );
    let report = open.report_aggregates.expect("open report aggregates");
    for scope in [&report.all, &report.long] {
        assert_eq!(scope.closed_trades, 0);
        assert_eq!(scope.open_trades, 1);
        assert_eq!(scope.commission, 5.0);
        assert_eq!(scope.open_profit, 0.0);
    }
    assert_eq!(report.short.open_trades, 0);
}

#[test]
fn margin_calls_expose_event_count_and_liquidation_volume() {
    let src = "//@version=6\n\
               strategy(\"S\", initial_capital=1000, default_qty_value=400, margin_long=25)\n\
               if bar_index == 0\n    strategy.entry(\"L\", strategy.long)\n\
               plot(close)\n";
    let s = run_strategy(
        src,
        &[
            (10.0, 10.0, 10.0, 10.0),
            (10.0, 10.0, 10.0, 10.0),
            (9.0, 9.0, 9.0, 9.0),
        ],
    );
    assert_eq!(s.margin_used, vec![0.0, 1_000.0, 0.0]);
    assert_eq!(s.maximum_margin_used, 1_000.0);
    assert_eq!(s.margin_calls, 1);
    assert_eq!(s.total_liquidated, 3_600.0);
    assert_eq!(s.largest_liquidation, 3_600.0);
    assert_eq!(s.position.size, 0.0);

    // Liquidation telemetry is account-currency notional: quantity times fill
    // price times point value (and, for cross-currency symbols, the fill-bar FX
    // rate). This keeps the public money label semantically honest.
    let program = compile(
        "//@version=6\n\
         strategy(\"S\", initial_capital=1000, default_qty_value=40, margin_long=25)\n\
         if bar_index == 0\n    strategy.entry(\"L\", strategy.long)\n\
         plot(close)\n",
    );
    let mut data = ohlc_data(&[
        (10.0, 10.0, 10.0, 10.0),
        (10.0, 10.0, 10.0, 10.0),
        (9.0, 9.0, 9.0, 9.0),
    ]);
    data.syminfo.pointvalue = 10.0;
    let outcome = run(&program, &data, &RunOptions::default());
    assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
    let pointvalued = outcome.strategy.expect("strategy outcome");
    assert_eq!(pointvalued.margin_calls, 1);
    assert_eq!(pointvalued.total_liquidated, 3_600.0);
    assert_eq!(pointvalued.largest_liquidation, 3_600.0);

    let mut wire = serde_json::to_value(&pointvalued).expect("serialize strategy telemetry");
    assert_eq!(wire["marginCalls"], 1);
    assert_eq!(wire["totalLiquidated"], 3_600.0);
    assert_eq!(wire["largestLiquidation"], 3_600.0);
    let object = wire.as_object_mut().expect("strategy wire object");
    for field in [
        "marginUsed",
        "maximumMarginUsed",
        "requiredAccountSize",
        "reportAggregates",
        "marginCalls",
        "totalLiquidated",
        "largestLiquidation",
    ] {
        object.remove(field);
    }
    let legacy: crate::StrategyOutcome =
        serde_json::from_value(wire).expect("decode strategy outcome without the telemetry fields");
    assert!(legacy.margin_used.is_empty());
    assert_eq!(legacy.maximum_margin_used, 0.0);
    assert_eq!(legacy.required_account_size, None);
    assert_eq!(legacy.report_aggregates, None);
    assert_eq!(legacy.margin_calls, 0);
    assert_eq!(legacy.total_liquidated, 0.0);
    assert_eq!(legacy.largest_liquidation, 0.0);
}

#[test]
fn margin_call_volume_uses_fractional_contracts_and_the_slipped_fill_price() {
    let program = compile(
        "//@version=6\n\
         strategy(\"S\", initial_capital=1251, default_qty_value=1, margin_long=25, slippage=2)\n\
         if bar_index == 0\n    strategy.entry(\"L\", strategy.long)\n\
         plot(close)\n",
    );
    let mut data = ohlc_data(&[
        (100.0, 100.0, 100.0, 100.0),
        (100.0, 100.0, 100.0, 100.0),
        (99.0, 99.0, 99.0, 99.0),
    ]);
    data.syminfo.pointvalue = 50.0;
    data.syminfo.mincontract = 0.01;

    let outcome = run(&program, &data, &RunOptions::default());
    assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
    let strategy = outcome.strategy.expect("strategy outcome");

    // Entry fills at 100.02 and is affordable at that fill. At the later 99.00
    // mark, the 4x margin cushion liquidates 0.12 contracts at the slipped
    // sell fill of 98.98. Report liquidation is account notional and therefore
    // includes the symbol's point value.
    assert_eq!(strategy.margin_calls, 1);
    assert!((strategy.maximum_margin_used - 1_250.25).abs() < 1e-9);
    assert!((strategy.position.size - 0.88).abs() < 1e-9);
    assert!((strategy.trades[0].qty - 0.12).abs() < 1e-9);
    assert!((strategy.trades[0].exit_price - 98.98).abs() < 1e-9);
    let expected_volume = 0.12 * 98.98 * 50.0;
    assert!((strategy.total_liquidated - expected_volume).abs() < 1e-9);
    assert!((strategy.largest_liquidation - expected_volume).abs() < 1e-9);
}

#[test]
fn strategy_entry_and_order_reject_unaffordable_opening_margin() {
    for (primitive, order_call) in [
        ("entry", "strategy.entry(\"L\", strategy.long, qty=101)"),
        ("order", "strategy.order(\"L\", strategy.long, qty=101)"),
    ] {
        let source = format!(
            "//@version=6\nstrategy(\"S\", initial_capital=1000, margin_long=100)\nif bar_index == 0\n    {order_call}\nplot(strategy.position_size)\n"
        );
        let outcome = run_strategy_full(
            &source,
            &[(10.0, 10.0, 10.0, 10.0), (10.0, 10.0, 10.0, 10.0)],
        );
        assert_eq!(
            floats(&outcome.plots[0].values),
            vec![Some(0.0), Some(0.0)],
            "{primitive} must not create exposure beyond available funds"
        );
        let strategy = outcome.strategy.expect("strategy outcome");
        assert_eq!(strategy.position.size, 0.0, "{primitive}");
        assert!(strategy.trades.is_empty(), "{primitive}");
        assert_eq!(strategy.max_contracts_held, 0.0, "{primitive}");
    }
}

#[test]
fn same_direction_additions_reserve_the_existing_positions_margin() {
    for (primitive, first_call, second_call) in [
        (
            "entry",
            "strategy.entry(\"L1\", strategy.long, qty=60)",
            "strategy.entry(\"L2\", strategy.long, qty=50)",
        ),
        (
            "order",
            "strategy.order(\"L1\", strategy.long, qty=60)",
            "strategy.order(\"L2\", strategy.long, qty=50)",
        ),
    ] {
        let source = format!(
            "//@version=6\nstrategy(\"S\", initial_capital=1000, margin_long=100, pyramiding=2)\nif bar_index == 0\n    {first_call}\nif bar_index == 1\n    {second_call}\nplot(strategy.position_size)\n"
        );
        let outcome = run_strategy_full(
            &source,
            &[
                (10.0, 10.0, 10.0, 10.0),
                (10.0, 10.0, 10.0, 10.0),
                (10.0, 10.0, 10.0, 10.0),
            ],
        );
        assert_eq!(
            floats(&outcome.plots[0].values),
            vec![Some(0.0), Some(60.0), Some(60.0)],
            "{primitive} must reserve the first fill's EUR 600 margin before testing the EUR 500 addition"
        );
        let strategy = outcome.strategy.expect("strategy outcome");
        assert_eq!(strategy.position.size, 60.0, "{primitive}");
        assert_eq!(strategy.max_contracts_held, 60.0, "{primitive}");
    }
}

