#[test]
fn series_strategy_direction_dispatches_each_bar_value() {
    let src = format!(
        "{HDR}direction = close > open ? strategy.long : strategy.short\n\
         if bar_index < 2\n    strategy.entry(\"D\", direction)\n\
         plot(strategy.position_size)\n"
    );
    let s = run_strategy(
        &src,
        &[
            // bar 0 selects long; its order fills at bar 1 open (=12).
            (10.0, 11.5, 9.5, 11.0),
            // bar 1 selects short; its reversing order fills at bar 2 open (=10).
            (12.0, 12.5, 10.5, 11.0),
            (10.0, 10.5, 9.5, 10.0),
        ],
    );

    assert_eq!(
        s.position.size, -1.0,
        "the bar-1 series value must open short"
    );
    assert_eq!(s.position.avg_price, 10.0);
    assert_eq!(s.trades.len(), 1, "the short entry reverses the prior long");
    assert_eq!(s.trades[0].sign, 1.0);
    assert_eq!(s.trades[0].pnl, -2.0, "long 12 -> 10 before reversing");
}

#[test]
fn limit_fills_when_touched_and_not_when_untouched() {
    // A buy limit at 9.0 placed on bar 0. It rests until a bar's low <= 9.
    let src = format!(
        "{HDR}if bar_index == 0\n    strategy.entry(\"L\", strategy.long, limit=9.0)\nplot(close)\n"
    );
    // Touched case: bar1 low dips to 8.5 (<= 9), fills at min(open, limit).
    let touched = run_strategy(
        &src,
        &[
            (10.0, 11.0, 9.5, 10.0),
            (10.0, 10.5, 8.5, 10.0),
            (11.0, 12.0, 10.0, 11.0),
        ],
    );
    assert_eq!(touched.position.size, 1.0);
    // open 10 > limit 9, so fill is at the limit price 9.0.
    assert_eq!(touched.position.avg_price, 9.0);

    // Untouched case: no bar ever trades at/below 9 => never fills.
    let untouched = run_strategy(
        &src,
        &[
            (10.0, 11.0, 9.5, 10.0),
            (10.0, 11.0, 9.5, 10.0),
            (11.0, 12.0, 10.0, 11.0),
        ],
    );
    assert_eq!(untouched.position.size, 0.0, "limit never touched => flat");
}

#[test]
fn price_orders_crossed_in_an_interbar_gap_fill_at_the_current_open() {
    // The broker contract treats the previous-close -> current-open gap as
    // having no intrabars. A price order crossed inside that gap fills at the
    // current open, not at its limit/stop price. Pin both directions and order
    // types.
    for (direction, parameter, order_price, gap_open, expected_size) in [
        ("strategy.long", "stop", 105.0, 110.0, 1.0),
        ("strategy.short", "stop", 95.0, 90.0, -1.0),
        ("strategy.long", "limit", 95.0, 90.0, 1.0),
        ("strategy.short", "limit", 105.0, 110.0, -1.0),
    ] {
        let source = format!(
            "{HDR}if bar_index == 0\n    strategy.entry(\"E\", {direction}, {parameter}={order_price})\nplot(close)\n"
        );
        let strategy = run_strategy(
            &source,
            &[
                (100.0, 101.0, 99.0, 100.0),
                (gap_open, gap_open + 1.0, gap_open - 1.0, gap_open),
            ],
        );
        assert_eq!(
            strategy.position.size, expected_size,
            "{direction} {parameter} must fill after the gap"
        );
        assert_eq!(
            strategy.position.avg_price, gap_open,
            "{direction} {parameter} must fill at the current open, not {order_price}"
        );
    }
}

#[test]
fn stop_fills_when_price_trades_through() {
    // A buy stop at 12.0 fills when a later bar's high reaches 12.
    let src = format!(
        "{HDR}if bar_index == 0\n    strategy.entry(\"L\", strategy.long, stop=12.0)\nplot(close)\n"
    );
    // bar1 high 12.5 >= 12; open 10 < stop 12 => fill at the stop price 12.
    let s = run_strategy(
        &src,
        &[
            (10.0, 10.5, 9.5, 10.0),
            (10.0, 12.5, 9.8, 12.0),
            (13.0, 14.0, 12.0, 13.0),
        ],
    );
    assert_eq!(s.position.size, 1.0);
    assert_eq!(s.position.avg_price, 12.0);
}

#[test]
fn stop_limit_activates_before_limit_and_persists_across_bars() {
    // A buy stop-limit does not fill merely because the bar crossed its stop.
    // The stop first activates a buy limit, which then waits for price to
    // return to 11 or better.
    let src = format!(
        "{HDR}if bar_index == 0\n    strategy.entry(\"L\", strategy.long, stop=12.0, limit=11.0)\nplot(close)\n"
    );
    let delayed = run_strategy(
        &src,
        &[
            (10.0, 10.0, 10.0, 10.0),
            // Activates at 12, then remains above the 11 limit.
            (10.0, 13.0, 10.0, 13.0),
            // The activated limit persists and fills on the later decline.
            (13.0, 13.0, 10.0, 11.0),
        ],
    );
    assert_eq!(delayed.position.size, 1.0);
    assert_eq!(delayed.position.avg_price, 11.0);

    // When the path crosses the stop and subsequently returns through the
    // limit on the same bar, activation and fill can occur on that bar.
    let same_bar = run_strategy(&src, &[(10.0, 10.0, 10.0, 10.0), (10.0, 13.0, 10.0, 10.0)]);
    assert_eq!(same_bar.position.size, 1.0);
    assert_eq!(same_bar.position.avg_price, 11.0);
}

#[test]
fn limit_verification_applies_after_stop_limit_activation_at_declared_price() {
    let source = concat!(
        "//@version=6\n",
        "strategy(\"S\", initial_capital=10000, backtest_fill_limits_assumption=2)\n",
        "if bar_index == 0\n",
        "    strategy.entry(\"L\", strategy.long, qty=1, stop=12, limit=11)\n",
        "plot(strategy.position_size)\n",
    );
    let outcome = run_strategy_full(
        source,
        &[
            (10.0, 10.0, 10.0, 10.0),
            // The gap/open activates the stop, then 10.99 reaches the declared
            // limit but not its two-tick verification price of 10.98.
            (12.0, 13.0, 10.99, 11.0),
            (11.0, 11.0, 10.98, 11.0),
        ],
    );
    assert_eq!(
        floats(&outcome.plots[0].values),
        vec![Some(0.0), Some(0.0), Some(1.0)],
        "the unverified touch stays queued until the two-tick threshold"
    );
    let strategy = outcome.strategy.expect("strategy outcome");
    assert_eq!(strategy.position.size, 1.0);
    assert_eq!(strategy.position.avg_price, 11.0);
}

#[test]
fn limit_verification_applies_to_fixed_and_trailing_take_profit_legs() {
    for (name, trailing_args) in [
        ("fixed", ""),
        ("trailing", ", trail_price=20, trail_offset=100"),
    ] {
        let source = format!(
            "//@version=6\nstrategy(\"S\", initial_capital=10000, backtest_fill_limits_assumption=2)\nif bar_index == 0\n    strategy.entry(\"L\", strategy.long, qty=1)\nif bar_index == 1\n    strategy.exit(\"X\", \"L\", limit=11{trailing_args})\nplot(strategy.position_size)\n"
        );
        let outcome = run_strategy(
            &source,
            &[
                (10.0, 10.0, 10.0, 10.0),
                (10.0, 10.0, 10.0, 10.0),
                (10.0, 11.01, 10.0, 11.0),
                (11.0, 11.02, 11.0, 11.02),
            ],
        );
        assert_eq!(outcome.trades.len(), 1, "{name}");
        assert_eq!(outcome.trades[0].exit_bar, 3, "{name}");
        assert_eq!(
            outcome.trades[0].exit_price, 11.0,
            "{name}: verification changes eligibility, not fill price"
        );
    }
}

#[test]
fn fixed_exit_bracket_honors_a_marketable_gap_leg_before_later_crossings() {
    let source = concat!(
        "//@version=6\n",
        "strategy(\"S\", initial_capital=10000)\n",
        "if bar_index == 0\n",
        "    strategy.entry(\"L\", strategy.long, qty=1)\n",
        "if bar_index == 1\n",
        "    strategy.exit(\"X\", \"L\", limit=11, stop=9)\n",
        "plot(strategy.position_size)\n",
    );
    let outcome = run_strategy(
        source,
        &[
            (10.0, 10.0, 10.0, 10.0),
            (10.0, 10.0, 10.0, 10.0),
            // The stop is already marketable at the gap-down open. The
            // synthetic path would visit the high first, but that later limit
            // crossing cannot outrank the open fill.
            (8.0, 12.0, 3.0, 10.0),
        ],
    );
    assert_eq!(outcome.trades.len(), 1);
    assert_eq!(outcome.trades[0].exit_price, 8.0);
    assert_eq!(outcome.trades[0].pnl, -2.0);
}

#[test]
fn exit_bracket_profit_and_loss_legs() {
    // Enter long at bar1 open (=10), then exit with a +5 profit and a -3 loss
    // bracket (mintick default 0.01 => points are price units here since we
    // pass absolute limit/stop). Use absolute limit=15 (profit) and stop=8 (loss).
    let profit_src = format!(
        "{HDR}if bar_index == 0\n    strategy.entry(\"L\", strategy.long)\nif bar_index == 1\n    strategy.exit(\"X\", from_entry=\"L\", limit=15.0, stop=8.0)\nplot(close)\n"
    );
    // bar1 fills entry at open 10. bar2 high 16 >= 15 => profit leg fills at 15.
    let win = run_strategy(
        &profit_src,
        &[
            (9.0, 9.5, 8.5, 9.0),
            (10.0, 10.5, 9.5, 10.0),
            (14.0, 16.0, 13.0, 15.0),
            (15.0, 15.0, 15.0, 15.0),
        ],
    );
    assert_eq!(win.trades.len(), 1);
    assert_eq!(win.trades[0].exit_price, 15.0);
    assert_eq!(win.trades[0].pnl, 5.0, "long 10 -> 15 = +5");
    assert_eq!(win.position.size, 0.0);

    // Loss leg: bar2 low 7 <= 8 => stop fills at 8, pnl = -2.
    let loss = run_strategy(
        &profit_src,
        &[
            (9.0, 9.5, 8.5, 9.0),
            (10.0, 10.5, 9.5, 10.0),
            (9.0, 9.5, 7.0, 8.0),
            (8.0, 8.0, 8.0, 8.0),
        ],
    );
    assert_eq!(loss.trades.len(), 1);
    assert_eq!(loss.trades[0].exit_price, 8.0);
    assert_eq!(loss.trades[0].pnl, -2.0, "long 10 -> 8 = -2");
}

#[test]
fn both_legs_touched_same_bar_uses_open_proximity_path() {
    // Long position; an exit carries limit=15 (take-profit) and stop=8 (loss).
    // On the exit bar both are touched. Open is nearer the LOW, so the assumed
    // path is open->low->high: the stop (8, lower) is reached first.
    let src = format!(
        "{HDR}if bar_index == 0\n    strategy.entry(\"L\", strategy.long)\nif bar_index == 1\n    strategy.exit(\"X\", from_entry=\"L\", limit=15.0, stop=8.0)\nplot(close)\n"
    );
    // bar1 entry at open 10. bar2: O=9 (nearer low 7 than high 16), both hit.
    let s = run_strategy(
        &src,
        &[
            (9.0, 9.5, 8.5, 9.0),
            (10.0, 10.5, 9.5, 10.0),
            (9.0, 16.0, 7.0, 12.0),
            (12.0, 12.0, 12.0, 12.0),
        ],
    );
    assert_eq!(s.trades.len(), 1);
    assert_eq!(s.trades[0].exit_price, 8.0, "open near low => stop first");
    assert_eq!(s.trades[0].pnl, -2.0);
}

#[test]
fn strategy_oca_cancel_none_and_reduce_apply_to_entry_order_groups() {
    let cancel = concat!(
        "//@version=6\n",
        "strategy(\"S\", initial_capital=10000, default_qty_value=1)\n",
        "if bar_index == 0\n",
        "    strategy.order(\"up\", strategy.long, stop=12, oca_name=\"cross\", oca_type=strategy.oca.cancel)\n",
        "    strategy.order(\"down\", strategy.short, stop=8, oca_name=\"cross\", oca_type=strategy.oca.cancel)\n",
        "plot(strategy.position_size)\n",
    );
    let cross_bars = [
        (10.0, 10.0, 10.0, 10.0),
        (10.0, 13.0, 7.0, 10.0),
        (10.0, 10.0, 10.0, 10.0),
    ];
    let cancelled = run_strategy(cancel, &cross_bars);
    assert_eq!(
        cancelled.position.size, 1.0,
        "the first triggered order cancels its peer before a later path tick"
    );

    let same_tick_cancel = concat!(
        "//@version=6\n",
        "strategy(\"S\", initial_capital=10000, default_qty_value=1)\n",
        "if bar_index == 0\n",
        "    strategy.order(\"first\", strategy.long, oca_name=\"same-tick\", oca_type=strategy.oca.cancel)\n",
        "    strategy.order(\"second\", strategy.long, oca_name=\"same-tick\", oca_type=strategy.oca.cancel)\n",
        "plot(strategy.position_size)\n",
    );
    let same_tick = run_strategy(
        same_tick_cancel,
        &[(10.0, 10.0, 10.0, 10.0), (11.0, 11.0, 11.0, 11.0)],
    );
    assert_eq!(
        same_tick.position.size, 2.0,
        "OCA cancel cannot affect a peer executable on the same tick"
    );

    let independent = cancel.replace("strategy.oca.cancel", "strategy.oca.none");
    let none = run_strategy(&independent, &cross_bars);
    assert_eq!(
        none.position.size, 0.0,
        "oca.none leaves both opposite one-contract orders independent"
    );

    let reduce = concat!(
        "//@version=6\n",
        "strategy(\"S\", initial_capital=10000, default_qty_value=1)\n",
        "if bar_index == 0\n",
        "    strategy.entry(\"L\", strategy.long, qty=6)\n",
        "if bar_index == 1\n",
        "    strategy.order(\"first\", strategy.short, qty=3, oca_name=\"reduce\", oca_type=strategy.oca.reduce)\n",
        "    strategy.order(\"rest\", strategy.short, qty=6, oca_name=\"reduce\", oca_type=strategy.oca.reduce)\n",
        "plot(strategy.position_size)\n",
    );
    let reduced = run_strategy(
        reduce,
        &[
            (9.0, 9.0, 9.0, 9.0),
            (10.0, 10.0, 10.0, 10.0),
            (12.0, 12.0, 12.0, 12.0),
            (12.0, 12.0, 12.0, 12.0),
        ],
    );
    assert_eq!(
        reduced.position.size, -3.0,
        "same-tick OCA reduce leaves both executable quantities unchanged"
    );
    assert_eq!(
        reduced.trades.iter().map(|trade| trade.qty).sum::<f64>(),
        6.0
    );
}

#[test]
fn strategy_exit_named_oca_group_keeps_same_tick_peer_executable() {
    let source = concat!(
        "//@version=6\n",
        "strategy(\"S\", initial_capital=10000, default_qty_value=1)\n",
        "if bar_index == 0\n",
        "    strategy.entry(\"L\", strategy.long, qty=2)\n",
        "if bar_index == 1\n",
        "    strategy.exit(\"X1\", \"L\", qty=1, limit=11, oca_name=\"take-profits\")\n",
        "    strategy.exit(\"X2\", \"L\", qty=1, limit=12, oca_name=\"take-profits\")\n",
        "plot(strategy.position_size)\n",
    );
    let outcome = run_strategy(
        source,
        &[
            (9.0, 9.0, 9.0, 9.0),
            (10.0, 10.0, 10.0, 10.0),
            (10.0, 13.0, 10.0, 13.0),
            (13.0, 13.0, 13.0, 13.0),
        ],
    );
    assert_eq!(outcome.position.size, 0.0);
    assert_eq!(outcome.trades.len(), 2);
    assert_eq!(outcome.trades[0].exit_id.as_deref(), Some("X1"));
    assert_eq!(outcome.trades[1].exit_id.as_deref(), Some("X2"));
}

#[test]
fn calc_on_order_fills_recalculates_once_for_a_multi_fill_tick() {
    let source = concat!(
        "//@version=6\n",
        "strategy(\"S\", initial_capital=10000, calc_on_order_fills=true)\n",
        "varip int executions = 0\n",
        "executions += 1\n",
        "if bar_index == 0\n",
        "    strategy.order(\"A\", strategy.long, qty=1)\n",
        "    strategy.order(\"B\", strategy.long, qty=1)\n",
        "plot(executions)\n",
    );
    let outcome = run_strategy_full(
        source,
        &[
            (10.0, 10.0, 10.0, 10.0),
            (11.0, 11.0, 11.0, 11.0),
            (12.0, 12.0, 12.0, 12.0),
        ],
    );
    assert_eq!(
        floats(&outcome.plots[0].values),
        vec![Some(1.0), Some(3.0), Some(4.0)],
        "two fills on one available tick schedule one fill recalculation"
    );
}

#[test]
fn new_lot_does_not_inherit_pre_entry_extrema_or_margin_exposure() {
    let source = concat!(
        "//@version=6\n",
        "strategy(\"S\", initial_capital=100, margin_long=50)\n",
        "if bar_index == 0\n",
        "    strategy.entry(\"L\", strategy.long, qty=15, stop=13)\n",
        "if bar_index == 1 and strategy.position_size > 0\n",
        "    strategy.close(\"L\")\n",
        "plot(strategy.position_size)\n",
    );
    let outcome = run_strategy(
        source,
        &[
            (10.0, 10.0, 10.0, 10.0),
            // The low-first path is 10 -> 9 -> 13 -> 13. The stop entry only
            // exists from 13 onward, so the earlier low cannot count as an
            // adverse excursion or trigger a historical margin call.
            (10.0, 13.0, 9.0, 13.0),
            (13.0, 13.0, 13.0, 13.0),
        ],
    );
    assert_eq!(outcome.trades.len(), 1);
    assert_eq!(outcome.trades[0].entry_price, 13.0);
    assert_eq!(outcome.trades[0].max_drawdown, 0.0);
    assert_eq!(outcome.margin_calls, 0);
    assert_eq!(outcome.position.size, 0.0);
}

#[test]
fn strategy_exit_reserves_each_trade_and_reduces_oversubscribed_later_calls() {
    let source = concat!(
        "//@version=6\n",
        "strategy(\"S\", initial_capital=10000)\n",
        "if bar_index == 0\n",
        "    strategy.entry(\"L\", strategy.long, qty=20)\n",
        "if bar_index == 1\n",
        "    strategy.exit(\"limit\", \"L\", qty=19, limit=12)\n",
        "    strategy.exit(\"stop\", \"L\", qty=20, stop=9)\n",
        "plot(strategy.position_size)\n",
    );
    let outcome = run_strategy(
        source,
        &[
            (10.0, 10.0, 10.0, 10.0),
            (10.0, 10.0, 10.0, 10.0),
            // Only the later stop triggers. The earlier limit call reserved
            // 19 of 20 units, so this bracket can close only the final unit.
            (10.0, 10.0, 8.0, 9.0),
        ],
    );
    assert_eq!(outcome.trades.len(), 1);
    assert_eq!(outcome.trades[0].qty, 1.0);
    assert_eq!(outcome.trades[0].exit_id.as_deref(), Some("stop"));
    assert_eq!(outcome.position.size, 19.0);
}

