#[test]
fn pyramiding_three_same_id_generations_coexist_and_cancel_removes_all() {
    let source = |cancel: bool| {
        format!(
            "//@version=6\nstrategy(\"S\", initial_capital=10000, pyramiding=3)\n\
             if bar_index <= 2\n    strategy.entry(\"L\", strategy.long, qty=1, limit=5 + bar_index)\n\
             {}\
             plot(strategy.position_size)\n",
            if cancel {
                "if bar_index == 2\n    strategy.cancel(\"L\")\n"
            } else {
                ""
            }
        )
    };
    let bars = [
        (10.0, 10.0, 10.0, 10.0),
        (10.0, 10.0, 10.0, 10.0),
        (10.0, 10.0, 10.0, 10.0),
        (10.0, 10.0, 4.0, 6.0),
    ];
    let coexist = run_strategy(&source(false), &bars);
    assert_eq!(coexist.position.size, 3.0);
    assert_eq!(coexist.position.avg_price, 6.0);

    let cancelled = run_strategy(&source(true), &bars);
    assert_eq!(cancelled.position.size, 0.0);
    assert!(cancelled.trades.is_empty());
}

#[test]
fn pyramiding_one_distinct_same_execution_price_entries_share_capacity_snapshot() {
    let source = concat!(
        "//@version=6\n",
        "strategy(\"S\", initial_capital=10000, pyramiding=1)\n",
        "if bar_index == 0\n",
        "    strategy.entry(\"A\", strategy.long, qty=1, limit=9)\n",
        "    strategy.entry(\"B\", strategy.long, qty=1, limit=9)\n",
        "plot(strategy.position_size)\n",
    );
    let outcome = run_strategy(source, &[(10.0, 10.0, 10.0, 10.0), (10.0, 10.0, 8.0, 9.0)]);
    assert_eq!(outcome.position.size, 2.0);
    assert_eq!(outcome.position.avg_price, 9.0);
}

