#[test]
fn entry_order_cross_command_modification_preserves_unrelated_ids() {
    let entry_then_order = concat!(
        "//@version=6\nstrategy(\"S\", initial_capital=10000, pyramiding=3)\n",
        "if bar_index == 0\n",
        "    strategy.entry(\"X\", strategy.long, qty=1, limit=5)\n",
        "    strategy.order(\"X\", strategy.long, qty=2, limit=9)\n",
        "plot(close)\n",
    );
    let first = run_strategy(
        entry_then_order,
        &[(10.0, 10.0, 10.0, 10.0), (10.0, 10.0, 8.0, 9.0)],
    );
    assert_eq!(first.position.size, 2.0);
    assert_eq!(first.position.avg_price, 9.0);

    let order_then_entry = concat!(
        "//@version=6\nstrategy(\"S\", initial_capital=10000, pyramiding=3)\n",
        "if bar_index == 0\n",
        "    strategy.order(\"X\", strategy.long, qty=1, limit=5)\n",
        "    strategy.entry(\"X\", strategy.long, qty=3, limit=9)\n",
        "    strategy.entry(\"A\", strategy.long, qty=1, limit=5)\n",
        "    strategy.order(\"B\", strategy.long, qty=2, limit=9)\n",
        "plot(close)\n",
    );
    let second = run_strategy(
        order_then_entry,
        &[(10.0, 10.0, 10.0, 10.0), (10.0, 10.0, 8.0, 9.0)],
    );
    // X and unrelated B fill at 9; unrelated A remains pending at 5.
    assert_eq!(second.position.size, 5.0);
    assert_eq!(second.position.avg_price, 9.0);
}

