#[test]
fn strategy_close_closes_a_named_entry_with_partial_qty() {
    // `strategy.close(id, qty=...)` closes a specific named entry (distinct
    // from close_all). Enter 3 long, then close 2 of the "L" entry.
    let src = "//@version=6\n\
        strategy(\"S\", initial_capital=10000, default_qty_value=3, pyramiding=1)\n\
        if bar_index == 0\n    strategy.entry(\"L\", strategy.long)\n\
        if bar_index == 1\n    strategy.close(\"L\", qty=2)\n\
        plot(close)\n";
    let s = run_strategy(
        src,
        &[
            (9.0, 9.5, 8.5, 9.0),
            (10.0, 10.5, 9.5, 10.0),
            (20.0, 20.5, 19.5, 20.0),
        ],
    );
    // Entry of 3 fills at bar1 open (10); close 2 fills at bar2 open (20),
    // leaving 1 open.
    assert_eq!(s.position.size, 1.0, "1 of the 3 remains open");
    assert_eq!(s.trades.len(), 1);
    assert_eq!(s.trades[0].qty, 2.0);
    assert_eq!(s.trades[0].exit_price, 20.0);
    assert_eq!(s.trades[0].pnl, 20.0, "(20 - 10) * 2 = 20, no commission");
}

#[test]
fn close_all_flattens_the_position() {
    // Enter long at bar1 open (=10), close_all on bar1 => market-closes at bar2 open.
    let src = format!(
        "{HDR}if bar_index == 0\n    strategy.entry(\"L\", strategy.long)\nif bar_index == 2\n    strategy.close_all()\nplot(close)\n"
    );
    // bar1 entry at 10; bar2 close_all placed; bar3 open 13 closes it.
    let s = run_strategy(
        &src,
        &[
            (9.0, 9.5, 8.5, 9.0),
            (10.0, 10.5, 9.5, 10.0),
            (12.0, 12.5, 11.5, 12.0),
            (13.0, 13.5, 12.5, 13.0),
        ],
    );
    assert_eq!(s.position.size, 0.0, "flat after close_all");
    assert_eq!(s.trades.len(), 1);
    assert_eq!(s.trades[0].exit_price, 13.0);
    assert_eq!(s.trades[0].pnl, 3.0, "long 10 -> 13 = +3");
}

#[test]
fn commission_and_slippage_are_exact() {
    // 1 tick slippage (mintick 0.01 default => 0.01) adverse on buy and sell,
    // plus 0.1% percent commission per fill. Enter long, then close_all.
    let src = "//@version=6\nstrategy(\"S\", initial_capital=10000, default_qty_value=1, slippage=1, commission_type=\"percent\", commission_value=0.1)\nif bar_index == 0\n    strategy.entry(\"L\", strategy.long)\nif bar_index == 1\n    strategy.close_all()\nplot(close)\n";
    // bar1 open 10 -> buy fill 10.01 (slippage +0.01).
    // bar2 open 20 -> sell fill 19.99 (slippage -0.01).
    let s = run_strategy(
        src,
        &[
            (9.0, 9.5, 8.5, 9.0),
            (10.0, 10.5, 9.5, 10.0),
            (20.0, 20.5, 19.5, 20.0),
        ],
    );
    assert_eq!(s.trades.len(), 1);
    let t = &s.trades[0];
    assert!((t.entry_price - 10.01).abs() < 1e-12);
    assert!((t.exit_price - 19.99).abs() < 1e-12);
    // gross = (19.99 - 10.01) * 1 = 9.98; entry commission 0.1% * 10.01 and
    // exit commission 0.1% * 19.99. The closed trade's pnl is net of BOTH
    // commissions, so it equals the equity delta.
    let expected_pnl = (19.99 - 10.01) - 0.001 * 10.01 - 0.001 * 19.99;
    assert!(
        (t.pnl - expected_pnl).abs() < 1e-9,
        "pnl {} vs {}",
        t.pnl,
        expected_pnl
    );
    // Invariant: net_profit equals the final equity delta.
    let final_equity = *s.equity.last().unwrap();
    assert!(
        (s.net_profit - (final_equity - 10000.0)).abs() < 1e-9,
        "net_profit {} vs equity delta {}",
        s.net_profit,
        final_equity - 10000.0
    );
}

#[test]
fn market_fills_are_quantized_to_symbol_mintick() {
    let src = "//@version=6\n\
               strategy(\"S\", initial_capital=10000, default_qty_value=1)\n\
               if bar_index == 0\n    strategy.entry(\"L\", strategy.long)\n\
               if bar_index == 1\n    strategy.close_all()\n\
               plot(close)\n";
    let program = compile(src);
    let mut data = ohlc_data(&[
        (1.0, 1.0, 1.0, 1.0),
        (1.280355, 1.3, 1.2, 1.25),
        (1.218005, 1.3, 1.2, 1.25),
    ]);
    data.mintick = 0.00001;
    let outcome = run(&program, &data, &RunOptions::default());
    assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
    let strategy = outcome.strategy.expect("strategy outcome");
    assert_eq!(strategy.trades.len(), 1);
    assert!((strategy.trades[0].entry_price - 1.28035).abs() < 1e-12);
    assert!((strategy.trades[0].exit_price - 1.218).abs() < 1e-12);
}

#[test]
fn cash_per_order_is_charged_once_when_one_close_spans_multiple_lots() {
    let source = concat!(
        "//@version=6\n",
        "strategy(\"S\", initial_capital=10000, pyramiding=2, commission_type=\"cash_per_order\", commission_value=5)\n",
        "if bar_index == 0\n",
        "    strategy.entry(\"A\", strategy.long, qty=1)\n",
        "    strategy.entry(\"B\", strategy.long, qty=1)\n",
        "if bar_index == 1\n",
        "    strategy.close_all()\n",
        "plot(strategy.position_size)\n",
    );
    let outcome = run_strategy(
        source,
        &[
            (10.0, 10.0, 10.0, 10.0),
            (10.0, 10.0, 10.0, 10.0),
            (10.0, 10.0, 10.0, 10.0),
        ],
    );
    assert_eq!(outcome.trades.len(), 2);
    let commission: f64 = outcome.trades.iter().map(|trade| trade.commission).sum();
    assert!((commission - 15.0).abs() < 1e-9);
    assert!((outcome.net_profit + 15.0).abs() < 1e-9);
    for trade in &outcome.trades {
        // Each entry contributes $5; the one $5 close commission is split
        // evenly across its two one-contract trade records.
        assert!((trade.commission - 7.5).abs() < 1e-9);
    }
}

#[test]
fn cash_per_order_is_shared_across_every_leg_of_a_reversal_fill() {
    let source = concat!(
        "//@version=6\n",
        "strategy(\"S\", initial_capital=10000, pyramiding=2, commission_type=\"cash_per_order\", commission_value=5)\n",
        "if bar_index == 0\n",
        "    strategy.entry(\"A\", strategy.long, qty=1)\n",
        "    strategy.entry(\"B\", strategy.long, qty=1)\n",
        "if bar_index == 1\n",
        "    strategy.entry(\"R\", strategy.short, qty=1)\n",
        "if bar_index == 2\n",
        "    strategy.close_all()\n",
        "plot(strategy.position_size)\n",
    );
    let outcome = run_strategy(
        source,
        &[
            (10.0, 10.0, 10.0, 10.0),
            (10.0, 10.0, 10.0, 10.0),
            (10.0, 10.0, 10.0, 10.0),
            (10.0, 10.0, 10.0, 10.0),
        ],
    );
    assert_eq!(outcome.trades.len(), 3);
    let commission: f64 = outcome.trades.iter().map(|trade| trade.commission).sum();
    // Four executed orders (two entries, one reversal, one final close) at $5.
    assert!((commission - 20.0).abs() < 1e-9);
    assert!((outcome.net_profit + 20.0).abs() < 1e-9);
    for trade in &outcome.trades {
        assert!((trade.commission - 20.0 / 3.0).abs() < 1e-9);
    }
}

#[test]
fn filled_order_retention_preserves_global_gaps_accessors_wire_and_metrics() {
    // Keep one old lot open while 4,500 fresh lots open and close. Once the old
    // entry's order leaves the latest-9,000-fill window, closing it creates a
    // full-run trade index that is immediately absent from retained detail.
    // A final fresh trade then proves retained indices can contain a gap.
    let source = concat!(
        "//@version=6\n",
        "strategy(\"S\", initial_capital=10000, process_orders_on_close=true, close_entries_rule=\"ANY\")\n",
        "if bar_index == 0\n",
        "    strategy.order(\"A\", strategy.long, qty=1)\n",
        "else if bar_index >= 1 and bar_index <= 9000\n",
        "    if bar_index % 2 == 1\n",
        "        strategy.order(\"F\", strategy.long, qty=1)\n",
        "    else\n",
        "        strategy.close(\"F\")\n",
        "else if bar_index == 9001\n",
        "    strategy.close(\"A\")\n",
        "else if bar_index == 9002\n",
        "    strategy.order(\"C\", strategy.long, qty=1)\n",
        "else if bar_index == 9003\n",
        "    strategy.close(\"C\")\n",
        "last = bar_index == 9004\n",
        "plot(last ? strategy.closedtrades.first_index : na)\n",
        "plot(last ? strategy.closedtrades.profit(4499) : na)\n",
        "plot(last ? strategy.closedtrades.profit(4500) : na)\n",
        "plot(last ? strategy.closedtrades.profit(4501) : na)\n",
    );
    let mut bars = vec![(10.0, 10.0, 10.0, 10.0); 9_005];
    for (bar, tuple) in bars.iter_mut().enumerate().take(9_001).skip(1) {
        let price = if bar % 2 == 1 { 10.0 } else { 11.0 };
        *tuple = (price, price, price, price);
    }
    bars[9_001] = (20.0, 20.0, 20.0, 20.0);
    bars[9_002] = (30.0, 30.0, 30.0, 30.0);
    bars[9_003] = (32.0, 32.0, 32.0, 32.0);
    bars[9_004] = (32.0, 32.0, 32.0, 32.0);

    let outcome = run_strategy_full(source, &bars);
    assert_eq!(
        floats(&outcome.plots[0].values).last().copied().flatten(),
        Some(2.0),
        "first_index is the first retained global trade index"
    );
    assert_eq!(
        floats(&outcome.plots[1].values).last().copied().flatten(),
        Some(1.0),
        "the last fresh filler trade remains addressable by global index"
    );
    assert_eq!(
        floats(&outcome.plots[2].values).last().copied().flatten(),
        None,
        "the old-entry trade is a genuine hole, not a shifted local index"
    );
    assert_eq!(
        floats(&outcome.plots[3].values).last().copied().flatten(),
        Some(2.0),
        "a later retained global index remains readable across the hole"
    );

    let strategy = outcome.strategy.expect("strategy outcome");
    assert_eq!(strategy.closed_trades, 4_502);
    assert_eq!(strategy.win_trades, 4_502);
    assert_eq!(strategy.loss_trades, 0);
    assert_eq!(strategy.even_trades, 0);
    assert_eq!(strategy.net_profit, 4_512.0);
    assert_eq!(strategy.gross_profit, 4_512.0);
    assert_eq!(strategy.gross_loss, 0.0);
    assert!((strategy.avg_trade - 4_512.0 / 4_502.0).abs() < 1e-12);
    assert_eq!(strategy.first_retained_trade_index, Some(2));
    assert_eq!(strategy.retained_trade_pnl_baseline, Some(2.0));
    assert_eq!(strategy.first_entry_bar, Some(0));
    assert_eq!(strategy.first_entry_price, Some(10.0));
    assert_eq!(strategy.first_entry_account_notional_per_unit, Some(10.0));
    let report = strategy
        .report_aggregates
        .as_ref()
        .expect("full-run report aggregates");
    for scope in [&report.all, &report.long] {
        assert_eq!(scope.closed_trades, 4_502);
        assert_eq!(scope.open_trades, 0);
        assert_eq!(scope.win_trades, 4_502);
        assert_eq!(scope.loss_trades, 0);
        assert_eq!(scope.net_profit, 4_512.0);
        assert_eq!(scope.gross_profit, 4_512.0);
        assert_eq!(scope.gross_loss, 0.0);
        assert_eq!(scope.commission, 0.0);
        assert_eq!(scope.bars_held_sum, 18_004);
        assert_eq!(scope.bars_held_count, 4_502);
        assert_eq!(scope.favorable_excursion_sum, 4_512.0);
        assert_eq!(scope.favorable_excursion_count, 4_502);
        assert_eq!(scope.favorable_excursion_max, Some(10.0));
        assert_eq!(scope.adverse_excursion_sum, 0.0);
        assert_eq!(scope.adverse_excursion_count, 4_502);
        assert_eq!(scope.outliers.count, 2);
        assert_eq!(scope.outliers.total_pnl, 12.0);
        assert!(
            (scope.outliers.lower_fence.expect("lower fence") - 0.5973969045530854).abs() < 1e-12
        );
        assert!(
            (scope.outliers.upper_fence.expect("upper fence") - 1.407045565460242).abs() < 1e-12
        );
        assert_eq!(scope.outliers.trade_indices, vec![4_500, 4_501]);
        assert_eq!(
            scope
                .largest_winning_trade
                .as_ref()
                .map(|trade| (trade.trade_index, trade.pnl)),
            Some((4_500, 10.0))
        );
    }
    assert_eq!(report.short.closed_trades, 0);
    assert_eq!(strategy.trades.len(), 4_499);
    assert_eq!(
        strategy.trades.first().and_then(|trade| trade.index),
        Some(2)
    );
    assert_eq!(
        strategy
            .trades
            .first()
            .and_then(|trade| trade.cumulative_pnl),
        Some(3.0)
    );
    let last = strategy.trades.last().expect("final retained trade");
    assert_eq!(last.index, Some(4_501));
    assert_eq!(last.cumulative_pnl, Some(4_512.0));
    assert!(strategy
        .trades
        .iter()
        .all(|trade| trade.index != Some(4_500)));

    let wire = serde_json::to_value(&strategy).expect("serialize retained strategy outcome");
    assert_eq!(wire["firstRetainedTradeIndex"], 2);
    assert_eq!(wire["retainedTradePnlBaseline"], 2.0);
    assert_eq!(wire["firstEntryBar"], 0);
    assert_eq!(wire["firstEntryPrice"], 10.0);
    assert_eq!(wire["firstEntryAccountNotionalPerUnit"], 10.0);
    assert_eq!(wire["reportAggregates"]["all"]["closedTrades"], 4_502);
    assert_eq!(wire["reportAggregates"]["all"]["outliers"]["count"], 2);
    assert_eq!(wire["trades"][0]["index"], 2);
    assert_eq!(wire["trades"][0]["cumulativePnl"], 3.0);
    assert!(wire["trades"][0].get("entryOrderOrdinal").is_none());
    assert!(wire["trades"][0].get("exitOrderOrdinal").is_none());

    // Optional wire fields preserve deserialization compatibility with result
    // artifacts produced before global retention metadata existed.
    let mut legacy_wire = wire;
    let object = legacy_wire
        .as_object_mut()
        .expect("strategy outcome wire object");
    object.remove("firstRetainedTradeIndex");
    object.remove("retainedTradePnlBaseline");
    object.remove("firstEntryBar");
    object.remove("firstEntryPrice");
    object.remove("firstEntryAccountNotionalPerUnit");
    object.remove("reportAggregates");
    for trade in object
        .get_mut("trades")
        .expect("strategy trades field")
        .as_array_mut()
        .expect("strategy trades array")
    {
        let trade = trade.as_object_mut().expect("strategy trade object");
        trade.remove("index");
        trade.remove("cumulativePnl");
    }
    let legacy: crate::StrategyOutcome =
        serde_json::from_value(legacy_wire).expect("deserialize outcome without telemetry");
    assert_eq!(legacy.first_retained_trade_index, None);
    assert_eq!(legacy.retained_trade_pnl_baseline, None);
    assert_eq!(legacy.first_entry_bar, None);
    assert_eq!(legacy.first_entry_price, None);
    assert_eq!(legacy.first_entry_account_notional_per_unit, None);
    assert_eq!(legacy.report_aggregates, None);
    assert!(legacy
        .trades
        .iter()
        .all(|trade| trade.index.is_none() && trade.cumulative_pnl.is_none()));
}

#[test]
fn filled_order_retention_reports_total_trade_count_when_no_detail_survives() {
    use crate::broker::{Broker, OrderMetadata};

    let program = compile("//@version=6\nstrategy(\"S\")\nplot(close)\n");
    let info = program
        .metadata
        .strategy
        .as_ref()
        .expect("strategy metadata");
    let mut broker = Broker::new_with_symbol(info, 0.01, 1.0, 1.0, "");
    broker.place_order(
        "A".to_string(),
        1.0,
        Some(9_000.0),
        None,
        None,
        OrderMetadata::default(),
    );
    assert_eq!(broker.process_fills(0, 10.0, 10.0, 10.0, 10.0, false), 1);
    for bar in 1..=9_000 {
        broker.place_close(
            Some("A".to_string()),
            Some(1.0),
            None,
            OrderMetadata::default(),
            None,
        );
        assert_eq!(
            broker.process_fills(bar, 11.0, 11.0, 11.0, 11.0, false),
            1,
            "close fill {bar}"
        );
    }
    assert!(broker.trade_view(0, false).is_none());
    broker.record_snapshot(9_001, 11.0, 11.0, 11.0, 11.0);
    assert_eq!(
        broker
            .snapshot_at(9_001)
            .expect("post-retention snapshot")
            .closed_trades_first_index,
        9_000
    );

    let outcome = broker.into_outcome(11.0);
    assert!(outcome.trades.is_empty());
    assert_eq!(outcome.first_retained_trade_index, 9_000);
    assert_eq!(outcome.retained_trade_pnl_baseline, 9_000.0);
    assert_eq!(outcome.metrics.closed_trades, 9_000);
    assert_eq!(outcome.metrics.net_profit, 9_000.0);
    assert_eq!(outcome.metrics.gross_profit, 9_000.0);
}

#[test]
fn strategy_close_with_explicit_zero_quantity_creates_no_order() {
    for sizing in ["qty=0", "qty_percent=0"] {
        let source = format!(
            "//@version=6\nstrategy(\"S\", initial_capital=10000)\nif bar_index == 0\n    strategy.entry(\"L\", strategy.long, qty=2)\nif bar_index == 1\n    strategy.close(\"L\", {sizing})\nplot(strategy.position_size)\n"
        );
        let outcome = run_strategy(
            &source,
            &[
                (10.0, 10.0, 10.0, 10.0),
                (10.0, 10.0, 10.0, 10.0),
                (10.0, 10.0, 10.0, 10.0),
            ],
        );
        assert_eq!(outcome.position.size, 2.0, "{sizing}");
        assert!(outcome.trades.is_empty(), "{sizing}");
    }
}

#[test]
fn mincontract_floor_is_ulp_safe_at_decimal_boundaries() {
    let program = compile(
        "//@version=6\nstrategy(\"S\", initial_capital=10000)\nif bar_index == 0\n    strategy.entry(\"L\", strategy.long, qty=0.3)\nplot(strategy.position_size)\n",
    );
    let mut data = ohlc_data(&[(10.0, 10.0, 10.0, 10.0), (10.0, 10.0, 10.0, 10.0)]);
    data.syminfo.mincontract = 0.1;
    let outcome = run(&program, &data, &RunOptions::default());
    assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
    let strategy = outcome.strategy.expect("strategy outcome");
    assert!((strategy.position.size - 0.3).abs() < 1e-12);
}

#[test]
fn equity_series_is_exact_over_a_feed() {
    // Enter long at bar1 open (=10); hold. Equity each bar = 10000 + open PnL
    // marked to that bar's close (no realized until an exit).
    let src =
        format!("{HDR}if bar_index == 0\n    strategy.entry(\"L\", strategy.long)\nplot(close)\n");
    let s = run_strategy(
        &src,
        &[
            (9.0, 9.5, 8.5, 9.0),
            (10.0, 10.5, 9.5, 11.0),
            (12.0, 12.5, 11.5, 13.0),
        ],
    );
    // bar0: flat => 10000.
    // bar1: filled at open 10, close 11 => open PnL +1 => 10001.
    // bar2: close 13 => open PnL +3 => 10003.
    assert_eq!(s.equity, vec![10000.0, 10001.0, 10003.0]);
}

#[test]
fn report_books_open_entry_commission_while_equity_remains_consistent() {
    // The report books the open entry fee while preserving total equity.
    let src = "//@version=6\nstrategy(\"S\", initial_capital=10000, default_qty_value=1, commission_type=\"cash_per_contract\", commission_value=1.0)\nif bar_index == 0\n    strategy.entry(\"L\", strategy.long)\nplot(close)\n";
    let s = run_strategy(
        src,
        &[
            (9.0, 9.5, 8.5, 9.0),
            (10.0, 10.5, 9.5, 11.0),
            (12.0, 12.5, 11.5, 13.0),
        ],
    );
    // The report books the paid open entry fee as a realized loss.
    assert_eq!(s.net_profit, -1.0);
    assert!(s.trades.is_empty());
    // Baseline (no commission) is [10000, 10001, 10003]; every open bar here is
    // exactly the 1.0 entry commission lower, and the dip lands on the entry
    // bar (bar1: mtm +1 − 1 = 0), NOT only at close.
    assert_eq!(s.equity, vec![10000.0, 10000.0, 10002.0]);
    // The report open-profit field holds the gross price movement.
    assert_eq!(s.open_profit, 3.0);
    // The two equity surfaces agree: equity == initial + net_profit + openprofit.
    assert_eq!(
        *s.equity.last().unwrap(),
        s.initial_capital + s.net_profit + s.open_profit
    );
}

#[test]
fn reversing_entry_closes_opposite_and_opens_new() {
    // Long 1 filled at bar1 open (=10). A short entry on bar1 fills bar2 open
    // (=20): it closes the long (+10) and opens a 1-lot short.
    let src = format!(
        "{HDR}if bar_index == 0\n    strategy.entry(\"L\", strategy.long)\nif bar_index == 1\n    strategy.entry(\"S\", strategy.short)\nplot(close)\n"
    );
    let s = run_strategy(
        &src,
        &[
            (9.0, 9.5, 8.5, 9.0),
            (10.0, 10.5, 9.5, 10.0),
            (20.0, 20.5, 19.5, 20.0),
            (20.0, 20.0, 20.0, 20.0),
        ],
    );
    assert_eq!(s.trades.len(), 1, "the long leg closed");
    assert_eq!(s.trades[0].pnl, 10.0, "long 10 -> 20 = +10");
    assert_eq!(s.position.size, -1.0, "now short 1");
    assert_eq!(s.position.avg_price, 20.0);
}

#[test]
fn strategy_order_ignores_pyramiding_and_splits_reversal_quantity() {
    // `strategy.order` is not subject to the `strategy.entry` pyramiding cap:
    // both distinct long orders fill even with the declaration default of 0.
    // A later short order for 3 contracts then closes those 2 long contracts
    // and opens only its 1-contract remainder on the short side.
    let outcome = run_strategy_full(
        concat!(
            "//@version=6\n",
            "strategy(\"S\", initial_capital=10000, pyramiding=0)\n",
            "if bar_index == 0\n",
            "    strategy.order(\"A\", strategy.long, qty=1)\n",
            "    strategy.order(\"B\", strategy.long, qty=1)\n",
            "if bar_index == 1\n",
            "    strategy.order(\"Reverse\", strategy.short, qty=3)\n",
            "plot(strategy.position_size)\n",
        ),
        &[
            (9.0, 9.0, 9.0, 9.0),
            (10.0, 10.0, 10.0, 10.0),
            (20.0, 20.0, 20.0, 20.0),
            (20.0, 20.0, 20.0, 20.0),
        ],
    );

    assert_eq!(
        floats(&outcome.plots[0].values),
        vec![Some(0.0), Some(2.0), Some(-1.0), Some(-1.0)]
    );
    let strategy = outcome.strategy.expect("strategy outcome");
    assert_eq!(strategy.position.size, -1.0);
    assert_eq!(strategy.position.avg_price, 20.0);
    assert_eq!(strategy.trades.len(), 2);
    assert_eq!(
        strategy.trades.iter().map(|trade| trade.qty).sum::<f64>(),
        2.0
    );
    assert!(strategy
        .trades
        .iter()
        .all(|trade| trade.exit_id.as_deref() == Some("Reverse")));
}

#[test]
fn order_primitive_requires_strategy_declaration() {
    // `strategy.*` in an indicator script is a compile error (E0241), so it
    // never reaches the VM. Assert the analyzer rejects it.
    let parsed = parse(
        "//@version=6\nindicator(\"I\")\nstrategy.entry(\"L\", strategy.long)\nplot(close)\n",
    );
    assert!(!has_errors(&parsed.diagnostics), "{:?}", parsed.diagnostics);
    let analysis = analyze(&parsed.program);
    let codes: Vec<String> = analysis
        .diagnostics
        .iter()
        .filter(|d| d.severity == pinewasm_span::Severity::Error)
        .filter_map(|d| d.code.clone())
        .collect();
    assert!(
        codes.iter().any(|c| c == "E0241"),
        "expected E0241, got {codes:?}"
    );
}

// -- strategy.* read surface -------------------------------------------------

/// The four-bar entry/close scenario used by the read-surface tests: enter long
/// on bar 0 (fills at bar 1's open = 10), place `close_all` on bar 2 (fills at
/// bar 3's open = 13). One closed trade +3. Snapshots are frozen at the start of
/// each bar *after* prior-bar fills, so the getter series lag placement by a bar.
const RS_BARS: [(f64, f64, f64, f64); 4] = [
    (9.0, 9.5, 8.5, 9.0),
    (10.0, 10.5, 9.5, 10.0),
    (12.0, 12.5, 11.5, 12.0),
    (13.0, 13.5, 12.5, 13.0),
];

fn rs_src(getter: &str) -> String {
    format!(
        "{HDR}if bar_index == 0\n    strategy.entry(\"L\", strategy.long)\nif bar_index == 2\n    strategy.close_all()\nplot({getter})\n"
    )
}

#[test]
fn strategy_position_size_and_avg_price_series() {
    let out = run_strategy_full(&rs_src("strategy.position_size"), &RS_BARS);
    // bar0 flat; bar1 the bar-0 entry has filled at open (size 1); bar2 still 1;
    // bar3 the close_all filled at open (flat again).
    assert_eq!(
        floats(&out.plots[0].values),
        vec![Some(0.0), Some(1.0), Some(1.0), Some(0.0)]
    );
    let avg = run_strategy_full(&rs_src("strategy.position_avg_price"), &RS_BARS);
    // Flat bars read `na`; while long the avg entry price is bar 1's open (10).
    assert_eq!(
        floats(&avg.plots[0].values),
        vec![None, Some(10.0), Some(10.0), None]
    );
}

#[test]
fn strategy_openprofit_and_equity_series() {
    // Open profit marks the open long to each bar's close: bar1 close 10 -> +0,
    // bar2 close 12 -> +2. Flat bars are 0. Equity = 10000 + net + open.
    let op = run_strategy_full(&rs_src("strategy.openprofit"), &RS_BARS);
    assert_eq!(
        floats(&op.plots[0].values),
        vec![Some(0.0), Some(0.0), Some(2.0), Some(0.0)]
    );
    let eq = run_strategy_full(&rs_src("strategy.equity"), &RS_BARS);
    // bar0 10000; bar1 10000+0; bar2 10000+0+2; bar3 10000+3 (realized) +0 open.
    assert_eq!(
        floats(&eq.plots[0].values),
        vec![Some(10000.0), Some(10000.0), Some(10002.0), Some(10003.0)]
    );
}

#[test]
fn strategy_netprofit_and_trade_counts_series() {
    // The single +3 trade closes on bar 3 (close_all fill), so its realized
    // metrics appear in the bar-3 snapshot only.
    let np = run_strategy_full(&rs_src("strategy.netprofit"), &RS_BARS);
    assert_eq!(
        floats(&np.plots[0].values),
        vec![Some(0.0), Some(0.0), Some(0.0), Some(3.0)]
    );
    let gp = run_strategy_full(&rs_src("strategy.grossprofit"), &RS_BARS);
    assert_eq!(
        floats(&gp.plots[0].values),
        vec![Some(0.0), Some(0.0), Some(0.0), Some(3.0)]
    );
    // wintrades/closedtrades: series int, coerced to float by plot.
    let wt = run_strategy_full(&rs_src("strategy.wintrades"), &RS_BARS);
    assert_eq!(
        floats(&wt.plots[0].values),
        vec![Some(0.0), Some(0.0), Some(0.0), Some(1.0)]
    );
    let ct = run_strategy_full(&rs_src("strategy.closedtrades"), &RS_BARS);
    assert_eq!(
        floats(&ct.plots[0].values),
        vec![Some(0.0), Some(0.0), Some(0.0), Some(1.0)]
    );
    // No losing/even trades in this scenario.
    let lt = run_strategy_full(&rs_src("strategy.losstrades"), &RS_BARS);
    assert_eq!(
        floats(&lt.plots[0].values),
        vec![Some(0.0), Some(0.0), Some(0.0), Some(0.0)]
    );
}

#[test]
fn strategy_opentrades_and_max_contracts_series() {
    // opentrades counts live lots: 0 until the entry fills, 1 while long, 0 after
    // the close.
    let ot = run_strategy_full(&rs_src("strategy.opentrades"), &RS_BARS);
    assert_eq!(
        floats(&ot.plots[0].values),
        vec![Some(0.0), Some(1.0), Some(1.0), Some(0.0)]
    );
    // max_contracts_held is a running peak — it never drops back to 0 after the
    // position closes.
    let mc = run_strategy_full(&rs_src("strategy.max_contracts_held_all"), &RS_BARS);
    assert_eq!(
        floats(&mc.plots[0].values),
        vec![Some(0.0), Some(1.0), Some(1.0), Some(1.0)]
    );
}

#[test]
fn strategy_initial_capital_is_constant_series() {
    let ic = run_strategy_full(&rs_src("strategy.initial_capital"), &RS_BARS);
    assert_eq!(
        floats(&ic.plots[0].values),
        vec![Some(10000.0), Some(10000.0), Some(10000.0), Some(10000.0)]
    );
}

#[test]
fn strategy_avg_trade_is_na_until_a_trade_closes() {
    // avg_trade = netprofit / closedtrades, `na` while there are no closed
    // trades; after the single +3 trade it is 3 / 1 = 3.
    let at = run_strategy_full(&rs_src("strategy.avg_trade"), &RS_BARS);
    assert_eq!(
        floats(&at.plots[0].values),
        vec![None, None, None, Some(3.0)]
    );
    // avg_winning_trade = grossprofit / wintrades; the winning trade is +3.
    let aw = run_strategy_full(&rs_src("strategy.avg_winning_trade"), &RS_BARS);
    assert_eq!(
        floats(&aw.plots[0].values),
        vec![None, None, None, Some(3.0)]
    );
    // avg_losing_trade stays `na` — there are no losing trades.
    let al = run_strategy_full(&rs_src("strategy.avg_losing_trade"), &RS_BARS);
    assert_eq!(floats(&al.plots[0].values), vec![None, None, None, None]);
}

#[test]
fn strategy_max_drawdown_over_a_losing_then_winning_sequence() {
    // Two trades: a losing one then a winning one, so the mark-to-market equity
    // path dips before recovering. Enter long bar 0 (fill bar1
    // open 10), close bar 1 (fill bar2 open 8 -> -2). Enter long bar 2 (fill bar3
    // open 8), close bar 3 (fill bar4 open 13 -> +5).
    let src = format!(
        "{HDR}if bar_index == 0 or bar_index == 2\n    strategy.entry(\"L\", strategy.long)\nif bar_index == 1 or bar_index == 3\n    strategy.close_all()\nplot(strategy.max_drawdown)\n"
    );
    let bars = [
        (9.0, 9.5, 8.5, 9.0),
        (10.0, 10.5, 9.5, 10.0),
        (8.0, 8.5, 7.5, 8.0),
        (8.0, 8.5, 7.5, 8.0),
        (13.0, 13.5, 12.5, 13.0),
    ];
    let out = run_strategy_full(&src, &bars);
    // The broker excursion contract anchors each trade at the highest closed
    // equity before its entry; an unrealized favorable move to 10.5 does not
    // promote that anchor. The first trade's adverse excursion is 0.5, then 2
    // at its exit. The second trade begins with a 2-point closed-equity gap and
    // reaches 0.5 adverse excursion, for a final maximum of 2.5.
    assert_eq!(
        floats(&out.plots[0].values),
        vec![Some(0.0), Some(0.5), Some(2.0), Some(2.5), Some(2.5)]
    );
    let s = out.strategy.expect("strategy outcome");
    assert_eq!(s.trades.len(), 2);
    assert_eq!(s.trades[0].pnl, -2.0);
    assert_eq!(s.trades[1].pnl, 5.0);
}

#[test]
fn global_excursions_do_not_reanchor_at_unrealized_intratrade_extrema() {
    let scenario = |direction: &str, bars: &[(f64, f64, f64, f64)]| {
        run_strategy(
            &format!(
                "//@version=6\nstrategy(\"S\", initial_capital=10000)\nif bar_index == 0\n    strategy.entry(\"E\", strategy.{direction}, qty=1)\nplot(close)\n"
            ),
            bars,
        )
    };

    let long_favorable_then_giveback = scenario(
        "long",
        &[(100.0, 100.0, 100.0, 100.0), (100.0, 120.0, 100.0, 110.0)],
    );
    assert_eq!(long_favorable_then_giveback.max_drawdown, 0.0);
    assert_eq!(long_favorable_then_giveback.max_runup, 20.0);

    let long_adverse_then_rebound = scenario(
        "long",
        &[(100.0, 100.0, 100.0, 100.0), (100.0, 100.0, 80.0, 90.0)],
    );
    assert_eq!(long_adverse_then_rebound.max_drawdown, 20.0);
    assert_eq!(long_adverse_then_rebound.max_runup, 0.0);

    let short_favorable_then_giveback = scenario(
        "short",
        &[(100.0, 100.0, 100.0, 100.0), (100.0, 100.0, 80.0, 90.0)],
    );
    assert_eq!(short_favorable_then_giveback.max_drawdown, 0.0);
    assert_eq!(short_favorable_then_giveback.max_runup, 20.0);

    let short_adverse_then_rebound = scenario(
        "short",
        &[(100.0, 100.0, 100.0, 100.0), (100.0, 120.0, 100.0, 110.0)],
    );
    assert_eq!(short_adverse_then_rebound.max_drawdown, 20.0);
    assert_eq!(short_adverse_then_rebound.max_runup, 0.0);
}

#[test]
fn trade_anchored_excursions_respect_entry_and_exit_path_boundaries() {
    // The high occurs before a long limit entry on the high-to-low segment, so
    // the new trade sees only the movement from its 90 fill to 80 and then 100.
    let entered_midbar = run_strategy(
        "//@version=6\nstrategy(\"S\", initial_capital=10000)\nif bar_index == 0\n    strategy.entry(\"L\", strategy.long, qty=1, limit=90)\nplot(close)\n",
        &[
            (100.0, 100.0, 100.0, 100.0),
            (100.0, 120.0, 80.0, 100.0),
        ],
    );
    assert_eq!(entered_midbar.max_drawdown, 10.0);
    assert_eq!(entered_midbar.max_runup, 10.0);

    // This stop closes at 90 on the later downward segment. The trade sees the
    // prior high of 120 and the path to its stop, but not the subsequent low 80.
    let exited_midbar = run_strategy(
        "//@version=6\nstrategy(\"S\", initial_capital=10000)\nif bar_index == 0\n    strategy.entry(\"L\", strategy.long, qty=1)\n    strategy.exit(\"X\", \"L\", loss=1000)\nplot(close)\n",
        &[
            (100.0, 100.0, 100.0, 100.0),
            (100.0, 120.0, 80.0, 100.0),
        ],
    );
    assert_eq!(exited_midbar.position.size, 0.0);
    assert_eq!(exited_midbar.max_drawdown, 10.0);
    assert_eq!(exited_midbar.max_runup, 20.0);
}

#[test]
fn global_excursion_percentages_keep_their_peak_trough_equity_definition() {
    let outcome = run_strategy_full(
        "//@version=6\nstrategy(\"S\", initial_capital=1000)\nif bar_index == 0\n    strategy.entry(\"L\", strategy.long, qty=1)\nplot(strategy.max_drawdown_percent)\nplot(strategy.max_runup_percent)\n",
        &[
            (100.0, 100.0, 100.0, 100.0),
            (100.0, 150.0, 0.0, 100.0),
        ],
    );
    // Absolute metrics are trade-entry anchored (100 adverse, 50 favorable). The
    // percent built-ins are separately defined from the marked equity peak
    // and trough: 1050 -> 900 is 14.285...%, then 900 -> 1000 is 11.111...%.
    let strategy = outcome.strategy.expect("strategy outcome");
    assert_eq!(strategy.max_drawdown, 100.0);
    assert_eq!(strategy.max_runup, 50.0);
    let drawdown_percent = floats(&outcome.plots[0].values)
        .last()
        .copied()
        .flatten()
        .expect("drawdown percent");
    let runup_percent = floats(&outcome.plots[1].values)
        .last()
        .copied()
        .flatten()
        .expect("runup percent");
    assert!((drawdown_percent - 150.0 / 1_050.0 * 100.0).abs() < 1e-12);
    assert!((runup_percent - 100.0 / 900.0 * 100.0).abs() < 1e-12);
}

#[test]
fn trade_anchored_global_excursions_include_prior_closed_equity_gaps() {
    let losing_first = concat!(
        "//@version=6\nstrategy(\"S\", initial_capital=1000)\n",
        "if bar_index == 0\n    strategy.entry(\"A\", strategy.long, qty=1)\n",
        "if bar_index == 1\n    strategy.close(\"A\")\n",
        "if bar_index == 2\n    strategy.entry(\"B\", strategy.long, qty=1)\n",
        "plot(close)\n",
    );
    let drawdown = run_strategy(
        losing_first,
        &[
            (100.0, 100.0, 100.0, 100.0),
            (100.0, 100.0, 100.0, 100.0),
            (80.0, 80.0, 80.0, 80.0),
            (100.0, 100.0, 100.0, 100.0),
            (100.0, 100.0, 90.0, 90.0),
        ],
    );
    assert_eq!(drawdown.net_profit, -20.0);
    assert_eq!(drawdown.max_drawdown, 30.0);

    let winning_first = concat!(
        "//@version=6\nstrategy(\"S\", initial_capital=1000)\n",
        "if bar_index == 0\n    strategy.entry(\"A\", strategy.long, qty=1)\n",
        "if bar_index == 1\n    strategy.close(\"A\")\n",
        "if bar_index == 2\n    strategy.entry(\"B\", strategy.long, qty=1)\n",
        "plot(close)\n",
    );
    let runup = run_strategy(
        winning_first,
        &[
            (100.0, 100.0, 100.0, 100.0),
            (100.0, 100.0, 100.0, 100.0),
            (120.0, 120.0, 120.0, 120.0),
            (100.0, 100.0, 100.0, 100.0),
            (100.0, 110.0, 100.0, 110.0),
        ],
    );
    assert_eq!(runup.net_profit, 20.0);
    assert_eq!(runup.max_runup, 30.0);
}

#[test]
fn trade_anchored_drawdown_applies_commission_after_it_enters_closed_equity() {
    let outcome = run_strategy(
        "//@version=6\nstrategy(\"S\", initial_capital=1000, commission_type=\"cash_per_order\", commission_value=5)\nif bar_index == 0\n    strategy.entry(\"A\", strategy.long, qty=1)\nif bar_index == 1\n    strategy.close(\"A\")\nif bar_index == 2\n    strategy.entry(\"B\", strategy.long, qty=1)\nplot(close)\n",
        &[
            (100.0, 100.0, 100.0, 100.0),
            (100.0, 100.0, 100.0, 100.0),
            (100.0, 100.0, 100.0, 100.0),
            (100.0, 100.0, 100.0, 100.0),
        ],
    );
    // The report includes both closed fees and the new open entry fee.
    assert_eq!(outcome.net_profit, -15.0);
    assert_eq!(outcome.open_profit, 0.0);
    assert_eq!(outcome.max_drawdown, 15.0);
    assert_eq!(
        outcome
            .report_aggregates
            .expect("report aggregates")
            .all
            .commission,
        15.0
    );
}

/// A two-trade feed: enter long bar0 (fill bar1 open 10), close bar1 (fill bar2
/// open 8 → −2); enter long bar2 (fill bar3 open 8), close bar3 (fill bar4 open
/// 13 → +5). Both trades are closed by bar4. Shared by the trade-accessor tests.
const TWO_TRADE_BARS: [(f64, f64, f64, f64); 5] = [
    (9.0, 9.5, 8.5, 9.0),
    (10.0, 10.5, 9.5, 10.0),
    (8.0, 8.5, 7.5, 8.0),
    (8.0, 8.5, 7.5, 8.0),
    (13.0, 13.5, 12.5, 13.0),
];

fn two_trade_src(getter: &str) -> String {
    format!(
        "{HDR}if bar_index == 0 or bar_index == 2\n    strategy.entry(\"L\", strategy.long)\nif bar_index == 1 or bar_index == 3\n    strategy.close_all()\nplot({getter})\n"
    )
}

#[test]
fn strategy_closedtrades_accessors_read_each_closed_trade() {
    // Two closed trades: [entry 10, exit 8, −2] then [entry 8, exit 13, +5]. The
    // accessors read the broker's retained trade list (index 0 = oldest). On the
    // final bar both trades are closed, so `plot(...(0))` / `...(1))` resolve.
    let ep0 = run_strategy_full(
        &two_trade_src("strategy.closedtrades.entry_price(0)"),
        &TWO_TRADE_BARS,
    );
    assert_eq!(
        floats(&ep0.plots[0].values).last().copied().flatten(),
        Some(10.0)
    );
    let xp0 = run_strategy_full(
        &two_trade_src("strategy.closedtrades.exit_price(0)"),
        &TWO_TRADE_BARS,
    );
    assert_eq!(
        floats(&xp0.plots[0].values).last().copied().flatten(),
        Some(8.0)
    );
    let pr0 = run_strategy_full(
        &two_trade_src("strategy.closedtrades.profit(0)"),
        &TWO_TRADE_BARS,
    );
    assert_eq!(
        floats(&pr0.plots[0].values).last().copied().flatten(),
        Some(-2.0)
    );
    let sz0 = run_strategy_full(
        &two_trade_src("strategy.closedtrades.size(0)"),
        &TWO_TRADE_BARS,
    );
    assert_eq!(
        floats(&sz0.plots[0].values).last().copied().flatten(),
        Some(1.0)
    );
    // Second trade.
    let ep1 = run_strategy_full(
        &two_trade_src("strategy.closedtrades.entry_price(1)"),
        &TWO_TRADE_BARS,
    );
    assert_eq!(
        floats(&ep1.plots[0].values).last().copied().flatten(),
        Some(8.0)
    );
    let xp1 = run_strategy_full(
        &two_trade_src("strategy.closedtrades.exit_price(1)"),
        &TWO_TRADE_BARS,
    );
    assert_eq!(
        floats(&xp1.plots[0].values).last().copied().flatten(),
        Some(13.0)
    );
    let pr1 = run_strategy_full(
        &two_trade_src("strategy.closedtrades.profit(1)"),
        &TWO_TRADE_BARS,
    );
    assert_eq!(
        floats(&pr1.plots[0].values).last().copied().flatten(),
        Some(5.0)
    );
    // Commission is zero with the default (no-commission) header.
    let cm1 = run_strategy_full(
        &two_trade_src("strategy.closedtrades.commission(1)"),
        &TWO_TRADE_BARS,
    );
    assert_eq!(
        floats(&cm1.plots[0].values).last().copied().flatten(),
        Some(0.0)
    );
    // Out-of-range index reads `na` — not a panic.
    let oob = run_strategy_full(
        &two_trade_src("strategy.closedtrades.entry_price(2)"),
        &TWO_TRADE_BARS,
    );
    assert_eq!(floats(&oob.plots[0].values).last().copied().flatten(), None);
}

#[test]
fn strategy_closedtrades_commission_includes_entry_and_exit() {
    // With a per-contract commission of 1.0, each 1-contract trade pays 1 on the
    // entry fill and 1 on the exit fill: total commission 2.0 per trade.
    let hdr = "//@version=6\nstrategy(\"S\", initial_capital=10000, default_qty_value=1, commission_type=\"cash_per_contract\", commission_value=1.0)\n";
    let src = format!(
        "{hdr}if bar_index == 0 or bar_index == 2\n    strategy.entry(\"L\", strategy.long)\nif bar_index == 1 or bar_index == 3\n    strategy.close_all()\nplot(strategy.closedtrades.commission(0))\n"
    );
    let out = run_strategy_full(&src, &TWO_TRADE_BARS);
    assert_eq!(
        floats(&out.plots[0].values).last().copied().flatten(),
        Some(2.0)
    );
}

