#[test]
fn strategy_risk_max_intraday_loss_cash_measures_giveback_from_session_peak() {
    let program = compile(
        "//@version=6\nstrategy(\"S\", initial_capital=1000)\nstrategy.risk.max_intraday_loss(50, strategy.cash)\nif bar_index == 0\n    strategy.entry(\"L\", strategy.long, qty=10)\nif bar_index >= 2\n    strategy.entry(\"Again\", strategy.long, qty=1)\nplot(strategy.position_size)\n",
    );
    let mut data = ohlc_data(&[
        (10.0, 10.0, 10.0, 10.0),
        (10.0, 20.0, 10.0, 20.0),
        (20.0, 20.0, 14.0, 14.0),
        (14.0, 14.0, 14.0, 14.0),
    ]);
    // All bars share one exchange-day risk session.
    data.time = vec![0, 60_000, 120_000, 180_000];
    let outcome = run(&program, &data, &RunOptions::default());
    assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
    let strategy = outcome.strategy.expect("strategy outcome");
    // Equity peaks at 1,100, then falls to 1,040. The account is still above
    // its 1,000 session open, so only a high-water-mark rule can trigger.
    assert_eq!(strategy.equity, vec![1_000.0, 1_100.0, 1_040.0, 1_040.0]);
    assert_eq!(strategy.position.size, 0.0);
    assert_eq!(strategy.trades.len(), 1);
    assert_eq!(strategy.trades[0].pnl, 40.0);
    assert_eq!(
        strategy.trades[0].exit_id.as_deref(),
        Some("risk.max_intraday_loss")
    );
}

#[test]
fn intraday_loss_uses_host_trading_day_across_forex_midnight() {
    let program = compile(
        "//@version=6\nstrategy(\"FX\", initial_capital=1000)\nstrategy.risk.max_intraday_loss(50, strategy.cash)\nif bar_index == 0\n    strategy.entry(\"L\", strategy.long, qty=10)\nplot(strategy.position_size)\n",
    );
    let mut data = ohlc_data(&[
        (10.0, 10.0, 10.0, 10.0),
        (10.0, 20.0, 10.0, 20.0),
        (20.0, 20.0, 14.0, 14.0),
    ]);
    data.timeframe = "60".to_string();
    data.syminfo.kind = "forex".to_string();
    data.syminfo.session = "1700-1700".to_string();
    data.time = vec![86_340_000, 86_370_000, 90_000_000];
    data.trading_day = vec![0, 0, 0];
    let outcome = run(&program, &data, &RunOptions::default());
    assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
    let strategy = outcome.strategy.expect("strategy outcome");
    assert_eq!(strategy.position.size, 0.0);
    assert_eq!(strategy.trades.len(), 1);
    assert_eq!(strategy.trades[0].pnl, 40.0);
    assert_eq!(
        strategy.trades[0].exit_id.as_deref(),
        Some("risk.max_intraday_loss")
    );
}

#[test]
fn higher_than_daily_charts_use_one_risk_session_per_bar() {
    let program = compile(
        "//@version=6\nstrategy(\"W\", initial_capital=1000)\nstrategy.risk.max_intraday_loss(50, strategy.cash)\nif bar_index == 0\n    strategy.entry(\"L\", strategy.long, qty=10)\nplot(strategy.position_size)\n",
    );
    let mut data = ohlc_data(&[
        (10.0, 10.0, 10.0, 10.0),
        (10.0, 20.0, 10.0, 20.0),
        (14.0, 14.0, 14.0, 14.0),
    ]);
    data.timeframe = "1W".to_string();
    // Even a malformed trading_day value cannot merge >1D bars
    // into one risk session: every chart bar is its own broker risk day.
    data.trading_day = vec![0, 0, 0];
    let outcome = run(&program, &data, &RunOptions::default());
    assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
    let strategy = outcome.strategy.expect("strategy outcome");
    assert_eq!(strategy.position.size, 10.0);
    assert!(strategy.trades.is_empty());
    assert_eq!(strategy.equity, vec![1_000.0, 1_100.0, 1_040.0]);
}

#[test]
fn strategy_risk_max_intraday_loss_percent_uses_peak_equity_as_its_basis() {
    let program = compile(
        "//@version=6\nstrategy(\"S\", initial_capital=1000)\nstrategy.risk.max_intraday_loss(5, strategy.percent_of_equity)\nif bar_index == 0\n    strategy.entry(\"L\", strategy.long, qty=10)\nplot(strategy.position_size)\n",
    );
    let mut data = ohlc_data(&[
        (10.0, 10.0, 10.0, 10.0),
        (10.0, 20.0, 10.0, 20.0),
        (20.0, 20.0, 14.0, 14.0),
    ]);
    data.time = vec![0, 60_000, 120_000];
    let outcome = run(&program, &data, &RunOptions::default());
    assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
    let strategy = outcome.strategy.expect("strategy outcome");
    // Five percent of the 1,100 peak is 55; the 60 giveback trips the rule
    // even though ending equity remains 40 above the session opening equity.
    assert_eq!(strategy.position.size, 0.0);
    assert_eq!(strategy.trades.len(), 1);
    assert_eq!(strategy.trades[0].pnl, 40.0);
    assert_eq!(
        strategy.trades[0].exit_id.as_deref(),
        Some("risk.max_intraday_loss")
    );
}

#[test]
fn percent_intraday_loss_at_nonpositive_equity_permanently_halts_next_session() {
    let program = compile(
        "//@version=6\nstrategy(\"S\", initial_capital=100, margin_long=0)\nstrategy.risk.max_intraday_loss(100, strategy.percent_of_equity)\nif bar_index == 0 or bar_index >= 3\n    strategy.entry(\"L\", strategy.long, qty=20)\nplot(strategy.position_size)\n",
    );
    let mut data = ohlc_data(&[
        (10.0, 10.0, 10.0, 10.0),
        (10.0, 10.0, 10.0, 10.0),
        (10.0, 10.0, 5.0, 5.0),
        (20.0, 20.0, 20.0, 20.0),
        (20.0, 20.0, 20.0, 20.0),
    ]);
    data.time = vec![0, 60_000, 120_000, 86_400_000, 86_460_000];
    let outcome = run(&program, &data, &RunOptions::default());
    assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
    let strategy = outcome.strategy.expect("strategy outcome");
    assert_eq!(strategy.equity, vec![100.0, 100.0, 0.0, 0.0, 0.0]);
    assert_eq!(strategy.position.size, 0.0);
    assert_eq!(strategy.trades.len(), 1);
    assert_eq!(strategy.trades[0].pnl, -100.0);
    assert_eq!(
        strategy.trades[0].exit_id.as_deref(),
        Some("risk.max_intraday_loss")
    );
    assert_eq!(
        strategy.max_contracts_held, 20.0,
        "the next-session entry must never open after the permanent halt"
    );
}

#[test]
fn strategy_zero_drawdown_and_intraday_loss_thresholds_remain_active() {
    for member in ["max_drawdown", "max_intraday_loss"] {
        for unit in ["strategy.cash", "strategy.percent_of_equity"] {
            let src = format!(
                "{HDR}strategy.risk.{member}(0, {unit})\n\
                 strategy.entry(\"L\", strategy.long)\n\
                 plot(strategy.position_size)\n"
            );
            let out = run_strategy_full(&src, &TWO_TRADE_BARS);
            assert!(
                out.errors.is_empty(),
                "strategy.risk.{member}(0, {unit}) errors: {:?}",
                out.errors
            );
            let strategy = out.strategy.expect("strategy outcome");
            assert_eq!(
                strategy.position.size, 0.0,
                "strategy.risk.{member}(0, {unit}) must halt before an entry fills"
            );
            assert!(
                strategy.trades.is_empty(),
                "strategy.risk.{member}(0, {unit}) must cancel the pending entry"
            );
        }
    }
}

#[test]
fn strategy_risk_max_cons_loss_days_permanently_halts_after_limit() {
    let src = format!(
        "{HDR}strategy.risk.max_cons_loss_days(2)\n\
         if bar_index == 0 or bar_index >= 3\n    strategy.entry(\"L\", strategy.long)\n\
         plot(strategy.position_size)\n\
         plot(strategy.closedtrades)\n"
    );
    let out = run_strategy_full(
        &src,
        &[
            (10.0, 10.0, 10.0, 10.0),
            (10.0, 10.0, 9.0, 9.0),
            (9.0, 9.0, 8.0, 8.0),
            (8.0, 8.0, 8.0, 8.0),
            (20.0, 20.0, 20.0, 20.0),
        ],
    );
    assert_eq!(
        floats(&out.plots[0].values),
        vec![Some(0.0), Some(1.0), Some(1.0), Some(0.0), Some(0.0)]
    );
    assert_eq!(
        floats(&out.plots[1].values),
        vec![Some(0.0), Some(0.0), Some(0.0), Some(1.0), Some(1.0)]
    );
    let strategy = out.strategy.as_ref().unwrap();
    assert_eq!(strategy.position.size, 0.0);
    assert_eq!(strategy.trades.len(), 1);
    assert_eq!(
        strategy.trades[0].exit_id.as_deref(),
        Some("risk.max_cons_loss_days")
    );
}

#[test]
fn strategy_risk_directives_are_const_folded_and_stored_on_the_broker() {
    // VALUE-ASSERTING: the four risk directives are const-folded and registered
    // on the broker with the exact value/unit. End-to-end enforcement is covered
    // by the strategy_risk_* tests above; this pins the setter contract.
    use crate::broker::{Broker, RiskUnit};
    let program = compile("//@version=6\nstrategy(\"S\")\nplot(close)\n");
    let info = program
        .metadata
        .strategy
        .as_ref()
        .expect("strategy metadata present");
    let mut broker = Broker::new(info, 0.01);
    // Defaults: nothing registered.
    assert_eq!(broker.risk_max_drawdown(), None);
    assert_eq!(broker.risk_max_intraday_loss(), None);
    assert_eq!(broker.risk_max_intraday_filled_orders(), None);
    assert_eq!(broker.risk_max_cons_loss_days(), None);
    // Register each directive with a const-folded value/unit.
    broker.set_max_drawdown(50.0, RiskUnit::PercentOfEquity);
    broker.set_max_intraday_loss(100.0, RiskUnit::Cash);
    broker.set_max_intraday_filled_orders(5.0);
    broker.set_max_cons_loss_days(3.0);
    assert_eq!(
        broker.risk_max_drawdown(),
        Some((50.0, RiskUnit::PercentOfEquity))
    );
    assert_eq!(
        broker.risk_max_intraday_loss(),
        Some((100.0, RiskUnit::Cash))
    );
    assert_eq!(broker.risk_max_intraday_filled_orders(), Some(5));
    assert_eq!(broker.risk_max_cons_loss_days(), Some(3));
    // Zero is an active threshold, not a disable sentinel.
    broker.set_max_drawdown(0.0, RiskUnit::Cash);
    assert_eq!(broker.risk_max_drawdown(), Some((0.0, RiskUnit::Cash)));
}

#[test]
fn strategy_risk_registrations_are_distinct_and_idempotent_by_call_site() {
    use crate::broker::{Broker, RiskUnit};
    let program = compile("//@version=6\nstrategy(\"S\")\nplot(close)\n");
    let info = program
        .metadata
        .strategy
        .as_ref()
        .expect("strategy metadata present");
    let mut broker = Broker::new(info, 0.01);

    // Site 0 is the direct-test registration. Re-registering site 7 changes
    // that site's config in place; it must not append once per calculation.
    broker.set_max_position_size(10.0);
    broker.set_max_position_size_at_site(7, 3.0);
    broker.set_max_position_size_at_site(7, 4.0);
    broker.set_allow_entry_in(0);
    broker.set_allow_entry_in_at_site(8, 1);
    broker.set_allow_entry_in_at_site(8, 1);
    broker.set_max_drawdown_at_site(9, 1.0, RiskUnit::Cash, None);
    broker.set_max_drawdown_at_site(9, 2.0, RiskUnit::Cash, None);
    broker.set_max_intraday_loss_at_site(10, 1.0, RiskUnit::Cash, None);
    broker.set_max_intraday_loss_at_site(10, 2.0, RiskUnit::Cash, None);
    broker.set_max_intraday_filled_orders_at_site(11, 1.0, None);
    broker.set_max_intraday_filled_orders_at_site(11, 2.0, None);
    broker.set_max_cons_loss_days_at_site(12, 1.0, None);
    broker.set_max_cons_loss_days_at_site(12, 2.0, None);

    assert_eq!(broker.risk_rule_site_counts(), [2, 2, 1, 1, 1, 1]);
}

#[test]
fn strategy_same_type_risk_calls_apply_the_strictest_rule() {
    let cap = format!(
        "{HDR}strategy.risk.max_position_size(3)\n\
         strategy.risk.max_position_size(8)\n\
         if bar_index == 0\n    strategy.entry(\"L\", strategy.long, qty=10)\n\
         plot(strategy.position_size)\n"
    );
    assert_eq!(run_strategy(&cap, &TWO_TRADE_BARS).position.size, 3.0);

    let intersection = format!(
        "{HDR}strategy.risk.allow_entry_in(strategy.direction.long)\n\
         strategy.risk.allow_entry_in(strategy.direction.all)\n\
         if bar_index == 0\n    strategy.entry(\"S\", strategy.short)\n\
         plot(strategy.position_size)\n"
    );
    assert_eq!(
        run_strategy(&intersection, &TWO_TRADE_BARS).position.size,
        0.0
    );

    let empty_intersection = format!(
        "{HDR}strategy.risk.allow_entry_in(strategy.direction.long)\n\
         strategy.risk.allow_entry_in(strategy.direction.short)\n\
         if bar_index == 0\n    strategy.entry(\"L\", strategy.long)\n\
         if bar_index == 0\n    strategy.entry(\"S\", strategy.short)\n\
         plot(strategy.position_size)\n"
    );
    let blocked = run_strategy(&empty_intersection, &TWO_TRADE_BARS);
    assert_eq!(blocked.position.size, 0.0);
    assert!(blocked.trades.is_empty());

    // The cash rule is stricter for this fixture than the later 50%-of-equity
    // rule. Both must remain active despite using incomparable source units.
    let mixed_drawdown = format!(
        "{HDR}strategy.risk.max_drawdown(1, strategy.cash)\n\
         strategy.risk.max_drawdown(50, strategy.percent_of_equity)\n\
         if bar_index == 0\n    strategy.entry(\"L\", strategy.long)\n\
         if bar_index >= 2\n    strategy.entry(\"Again\", strategy.long)\n\
         plot(strategy.position_size)\n"
    );
    let outcome = run_strategy_full(
        &mixed_drawdown,
        &[
            (10.0, 10.0, 10.0, 10.0),
            (10.0, 10.0, 10.0, 10.0),
            (8.0, 8.0, 8.0, 8.0),
            (20.0, 20.0, 20.0, 20.0),
        ],
    );
    assert_eq!(
        outcome
            .strategy
            .expect("strategy outcome")
            .trades
            .first()
            .and_then(|trade| trade.exit_id.as_deref()),
        Some("risk.max_drawdown")
    );
}

