// ---- request.security ------------------------------------------------------

/// Nine daily bars whose closes are 100..108, beginning Monday 2020-01-06.
/// Their explicit calendar time axis makes "1W" group days 0..6 into
/// bucket 0 (close 106) and days 7..8 into bucket 1 (close 108) — matching the
/// `resample` unit tests. `request.security(syminfo.tickerid, "1W", close)`
/// maps those weekly closes back per chart bar under the gaps/lookahead modes.
fn monday_daily_closes(closes: &[f64]) -> MarketData {
    let mut data = data_from_close(closes);
    data.time = (0..closes.len())
        .map(|i| crate::SYNTHETIC_EPOCH_MS + (i as i64 + 5) * crate::MS_PER_DAY)
        .collect();
    data
}

fn nine_daily_closes() -> MarketData {
    monday_daily_closes(&[
        100.0, 101.0, 102.0, 103.0, 104.0, 105.0, 106.0, 107.0, 108.0,
    ])
}

fn security_plot(source: &str) -> Vec<Option<f64>> {
    let program = compile(source);
    let outcome = run(&program, &nine_daily_closes(), &RunOptions::default());
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    floats(&outcome.plots[0].values)
}

#[test]
fn script_selected_resample_caches_respect_the_vm_memory_budget() {
    let sources = [
        (
            "simple security",
            "//@version=6\nindicator(\"S\")\nplot(request.security(syminfo.tickerid, \"1W\", close))\n",
        ),
        (
            "compound security",
            "//@version=6\nindicator(\"S\")\nplot(request.security(syminfo.tickerid, \"1W\", close + 1.0))\n",
        ),
        (
            "time function",
            "//@version=6\nindicator(\"T\")\nplot(time(\"1W\"))\n",
        ),
    ];

    for (name, source) in sources {
        let program = compile(source);
        let data = nine_daily_closes();
        let defaults = RunOptions::default();
        let base = crate::vm_preallocation_bytes(
            &program,
            &data,
            &defaults,
            data.bars(),
            program.history_ring() as usize,
        )
        .expect("bounded base projection");
        let first_cache = data
            .bars()
            .checked_mul(crate::RESAMPLE_CACHE_RESERVATION_BYTES_PER_BAR)
            .and_then(|bytes| bytes.checked_add(crate::RESAMPLE_CACHE_ENTRY_RESERVATION_BYTES))
            .expect("bounded cache projection");
        let options = RunOptions {
            max_vm_bytes_per_run: base + first_cache - 1,
            ..defaults
        };
        let outcome = run(&program, &data, &options);
        assert_eq!(outcome.bars_executed, 0, "{name}: {outcome:?}");
        assert_eq!(outcome.errors.len(), 1, "{name}: {:?}", outcome.errors);
        assert_eq!(
            outcome.errors[0].kind,
            RuntimeErrorKind::VmMemoryLimitExceeded,
            "{name}: {:?}",
            outcome.errors
        );
    }
}

#[test]
fn resample_cache_construction_is_charged_to_the_run_instruction_budget() {
    let source =
        "//@version=6\nindicator(\"S\")\nplot(request.security(syminfo.tickerid, \"1W\", close))\n";
    let program = compile(source);
    let closes: Vec<f64> = (0..256).map(|bar| bar as f64).collect();
    let data = data_from_close(&closes);
    let options = RunOptions {
        max_instructions_per_bar: u64::MAX,
        max_instructions_per_run: 64,
        ..RunOptions::default()
    };
    let outcome = run(&program, &data, &options);
    assert_eq!(outcome.bars_executed, 0);
    assert_eq!(outcome.errors.len(), 1, "{:?}", outcome.errors);
    assert_eq!(
        outcome.errors[0].kind,
        RuntimeErrorKind::RunInstructionLimitExceeded
    );
}

#[test]
fn security_close_weekly_gaps_off_lookahead_off_repeats_completed_htf_close() {
    // Default gaps/lookahead (both off): each chart bar shows the last COMPLETED
    // weekly close, repeated. Bars 0..5 precede any weekly close ⇒ na; bar 6
    // closes bucket 0 ⇒ 106, repeated on 7; bar 8 closes bucket 1 ⇒ 108.
    let series = security_plot(
        "//@version=6\nindicator(\"S\")\nplot(request.security(syminfo.tickerid, \"1W\", close))\n",
    );
    assert_eq!(
        series,
        vec![
            None,
            None,
            None,
            None,
            None,
            None,
            Some(106.0),
            Some(106.0),
            Some(108.0),
        ]
    );
}

#[test]
fn security_close_weekly_gaps_on_yields_na_between_closes() {
    // gaps_on: a value appears ONLY on the bar that closes a weekly bucket.
    let series = security_plot(
        "//@version=6\nindicator(\"S\")\nplot(request.security(syminfo.tickerid, \"1W\", close, gaps=barmerge.gaps_on))\n",
    );
    assert_eq!(
        series,
        vec![
            None,
            None,
            None,
            None,
            None,
            None,
            Some(106.0),
            None,
            Some(108.0),
        ]
    );
}

#[test]
fn security_close_weekly_lookahead_on_repaints_forming_bucket() {
    // lookahead_on leaks the forming bucket's close onto its earlier chart bars
    // (repaint): bars 0..6 all show bucket 0's close 106; the BOUNDARY bar 7
    // now shows bucket 1's future close 108 (vs 106 under lookahead_off).
    let series = security_plot(
        "//@version=6\nindicator(\"S\")\nplot(request.security(syminfo.tickerid, \"1W\", close, lookahead=barmerge.lookahead_on))\n",
    );
    assert_eq!(
        series,
        vec![
            Some(106.0),
            Some(106.0),
            Some(106.0),
            Some(106.0),
            Some(106.0),
            Some(106.0),
            Some(106.0),
            Some(108.0),
            Some(108.0),
        ]
    );
    // The boundary bar 7 is exactly where lookahead flips the value.
    assert_eq!(series[7], Some(108.0));
}

#[test]
fn security_hl2_weekly_aggregates_high_low_across_the_bucket() {
    // hl2 over the weekly bucket uses the bucket's max-high and min-low, not a
    // single daily bar. High/low mirror close in data_from_close, so bucket 0
    // (days 0..6) has high 106, low 100 ⇒ hl2 = 103; bucket 1 (days 7..8) has
    // high 108, low 107 ⇒ hl2 = 107.5.
    let series = security_plot(
        "//@version=6\nindicator(\"S\")\nplot(request.security(syminfo.tickerid, \"1W\", hl2))\n",
    );
    assert_eq!(series[6], Some(103.0));
    assert_eq!(series[8], Some(107.5));
}

