fn security_error_codes(source: &str) -> Vec<String> {
    let parsed = parse(source);
    assert!(!has_errors(&parsed.diagnostics), "{:?}", parsed.diagnostics);
    let analysis = analyze(&parsed.program);
    analysis
        .diagnostics
        .iter()
        .filter(|d| d.severity == pinewasm_span::Severity::Error)
        .filter_map(|d| d.code.clone())
        .collect()
}

#[test]
fn security_lower_timeframe_is_a_clean_runtime_error() {
    // The actual chart timeframe is a runtime property (carried on
    // `MarketData`, defaulting to "1D" here), not something the compile-time
    // checker can see — so a lower-than-chart request compiles cleanly and is
    // rejected by the VM instead, against the real feed.
    let program = compile(
        "//@version=6\nindicator(\"S\")\nplot(request.security(syminfo.tickerid, \"60\", close))\n",
    );
    let outcome = run(&program, &nine_daily_closes(), &RunOptions::default());
    assert_eq!(outcome.errors.len(), 1);
    assert_eq!(
        outcome.errors[0].kind,
        RuntimeErrorKind::SecurityTimeframeBelowChart
    );
}

