#[test]
fn security_input_selected_symbol_tracks_host_override() {
    // Input-selected request symbol follows a RunOptions input override.
    let program = compile(
        "//@version=6\nindicator('Input-selected request symbol', dynamic_requests = false)\nchoice = input.string('AAPL', options = ['AAPL', 'MSFT'])\nsymbol = choice == 'AAPL' ? 'NASDAQ:AAPL' : 'NASDAQ:MSFT'\nplot(request.security(symbol, timeframe.period, close))\n",
    );
    let mut data = nine_daily_closes();
    data.request_data
        .insert("security/NASDAQ:AAPL/1D/close".into(), vec![31.0; 9]);
    data.request_data
        .insert("security/NASDAQ:MSFT/1D/close".into(), vec![47.0; 9]);
    let default = run(&program, &data, &RunOptions::default());
    assert!(default.errors.is_empty(), "errors: {:?}", default.errors);
    assert_eq!(floats(&default.plots[0].values), vec![Some(31.0); 9]);
    let mut options = RunOptions::default();
    options
        .inputs
        .insert(0, pinewasm_hir::InputValue::String("MSFT".into()));
    let overridden = run(&program, &data, &options);
    assert!(
        overridden.errors.is_empty(),
        "errors: {:?}",
        overridden.errors
    );
    assert_eq!(floats(&overridden.plots[0].values), vec![Some(47.0); 9]);
    data.request_data.remove("security/NASDAQ:MSFT/1D/close");
    let missing = run(&program, &data, &options);
    assert!(missing.errors.is_empty());
    assert_eq!(floats(&missing.plots[0].values), vec![None; 9]);
}

