#[test]
fn security_input_timeframe_override_changes_the_requested_buckets() {
    let input = compile(
        "//@version=6\nindicator(\"S\")\ntf = input.timeframe(\"1W\")\nplot(request.security(syminfo.tickerid, tf, close))\n",
    );
    let weekly = compile(
        "//@version=6\nindicator(\"S\")\nplot(request.security(syminfo.tickerid, \"1W\", close))\n",
    );
    let fortnightly = compile(
        "//@version=6\nindicator(\"S\")\nplot(request.security(syminfo.tickerid, \"2W\", close))\n",
    );
    let data = nineteen_daily_closes();
    let default = run(&input, &data, &RunOptions::default());
    let weekly = run(&weekly, &data, &RunOptions::default());
    assert!(default.errors.is_empty(), "errors: {:?}", default.errors);
    assert_eq!(default.plots[0].values, weekly.plots[0].values);

    let mut options = RunOptions::default();
    options
        .inputs
        .insert(0, pinewasm_hir::InputValue::String("2W".into()));
    let override_run = run(&input, &data, &options);
    let fortnightly = run(&fortnightly, &data, &RunOptions::default());
    assert!(
        override_run.errors.is_empty(),
        "errors: {:?}",
        override_run.errors
    );
    assert_eq!(override_run.plots[0].values, fortnightly.plots[0].values);
    assert_ne!(override_run.plots[0].values, default.plots[0].values);
}

