#[test]
fn security_history_offset_can_select_between_historical_and_realtime_contexts() {
    let dynamic = compile(
        "//@version=6\nindicator(\"S\")\nplot(request.security(syminfo.tickerid, \"2D\", close[barstate.isrealtime ? 1 : 0], lookahead=barmerge.lookahead_on))\n",
    );
    let current = compile(
        "//@version=6\nindicator(\"S\")\nplot(request.security(syminfo.tickerid, \"2D\", close, lookahead=barmerge.lookahead_on))\n",
    );
    let previous = compile(
        "//@version=6\nindicator(\"S\")\nplot(request.security(syminfo.tickerid, \"2D\", close[1], lookahead=barmerge.lookahead_on))\n",
    );
    let data = nineteen_daily_closes();

    let historical = run(&dynamic, &data, &RunOptions::default());
    let historical_reference = run(&current, &data, &RunOptions::default());
    assert!(historical.errors.is_empty(), "{:?}", historical.errors);
    assert!(historical_reference.errors.is_empty());
    assert_eq!(
        historical.plots[0].values,
        historical_reference.plots[0].values
    );

    let options = RunOptions {
        realtime: Some(RealtimeSim {
            ticks: vec![tick(data.bars() - 1, 999.0, true)],
        }),
        ..RunOptions::default()
    };
    let realtime = run(&dynamic, &data, &options);
    let realtime_reference = run(&previous, &data, &options);
    assert!(realtime.errors.is_empty(), "{:?}", realtime.errors);
    assert!(
        realtime_reference.errors.is_empty(),
        "{:?}",
        realtime_reference.errors
    );
    assert_eq!(
        realtime.plots[0].values.last(),
        realtime_reference.plots[0].values.last(),
        "a realtime request evaluates the history offset in the requested context"
    );
}

