#[test]
fn security_compound_ema_history_runs_in_the_weekly_context() {
    // Weekly closes are 106, 113, 118. The EMA(2) seeds at 109.5 on
    // bucket 1, then advances to 115.166... on bucket 2. Its [1] read must
    // therefore return 109.5 at the third bucket's close, not a daily EMA.
    let ema = security_expr_plot(
        "//@version=6\nindicator(\"S\")\nplot(request.security(syminfo.tickerid, \"1W\", ta.ema(close, 2)))\n",
    );
    assert_eq!(ema[6], None);
    assert_eq!(ema[13], Some(109.5));
    assert!((ema[18].unwrap() - 115.16666666666667).abs() < 1e-12);

    let prior_ema = security_expr_plot(
        "//@version=6\nindicator(\"S\")\nplot(request.security(syminfo.tickerid, \"1W\", ta.ema(close, 2)[1]))\n",
    );
    assert_eq!(prior_ema[13], None);
    assert_eq!(prior_ema[18], Some(109.5));
}

#[test]
fn security_hma_and_vwma_match_chart_context_on_daily_feed() {
    let closes: Vec<f64> = (0..230)
        .map(|i| 100.0 + (i as f64 * 0.17).sin() * 8.0 + i as f64 * 0.04)
        .collect();
    let mut data = data_from_close(&closes);
    data.volume = (0..closes.len())
        .map(|i| 1.0 + (i % 11) as f64 * 3.0)
        .collect();

    for (func, length) in [("hma", 2), ("hma", 9), ("vwma", 2), ("vwma", 193)] {
        let source = format!(
            "//@version=6\nindicator(\"S\")\nplot(ta.{func}(close, {length}))\nplot(request.security(syminfo.tickerid, \"1D\", ta.{func}(close, {length})))\n"
        );
        let outcome = run(&compile(&source), &data, &RunOptions::default());
        assert!(
            outcome.errors.is_empty(),
            "{func}({length}): {:?}",
            outcome.errors
        );
        assert_eq!(
            floats(&outcome.plots[0].values),
            floats(&outcome.plots[1].values),
            "{func}({length}) differs between chart and secondary context"
        );
    }
}

#[test]
fn security_hma_and_vwma_use_weekly_closes_and_bucket_volumes() {
    let hma = security_expr_plot(
        "//@version=6\nindicator(\"S\")\nplot(request.security(syminfo.tickerid, \"1W\", ta.hma(close, 2)))\n",
    );
    assert_eq!(hma[6], None);
    assert!((hma[13].unwrap() - (2.0 * 113.0 - (106.0 + 2.0 * 113.0) / 3.0)).abs() < 1e-12);
    assert!((hma[18].unwrap() - (2.0 * 118.0 - (113.0 + 2.0 * 118.0) / 3.0)).abs() < 1e-12);

    let vwma = security_expr_plot(
        "//@version=6\nindicator(\"S\")\nplot(request.security(syminfo.tickerid, \"1W\", ta.vwma(close, 2)))\n",
    );
    assert_eq!(vwma[6], None);
    assert_eq!(vwma[13], Some(109.5));
    assert!((vwma[18].unwrap() - (113.0 * 7.0 + 118.0 * 5.0) / 12.0).abs() < 1e-12);
}

#[test]
fn security_compound_ta_source_and_length_follow_run_inputs() {
    use pinewasm_hir::{BuiltinSeries, ExternalSourceRef, InputValue};

    let mut data = data_from_close(
        &(0..42)
            .map(|index| 100.0 + f64::from(index))
            .collect::<Vec<_>>(),
    );
    for (high, close) in data.high.iter_mut().zip(&data.close) {
        *high = close + 20.0;
    }
    for function in ["ema", "sma", "hma", "vwma"] {
        let source = format!(
            "//@version=6\nindicator(\"S\")\ntf = input.timeframe(\"1W\")\nsrc = input.source(close)\nn = input.int(2)\nplot(request.security(syminfo.tickerid, tf, ta.{function}(src, n)))\n"
        );
        let program = compile(&source);
        let expected_default = compile(&format!(
            "//@version=6\nindicator(\"S\")\nplot(request.security(syminfo.tickerid, \"1W\", ta.{function}(close, 2)))\n"
        ));
        let default_run = run(&program, &data, &RunOptions::default());
        assert!(
            default_run.errors.is_empty(),
            "{function}: {:?}",
            default_run.errors
        );
        assert_eq!(
            floats(&default_run.plots[0].values),
            floats(&run(&expected_default, &data, &RunOptions::default()).plots[0].values),
            "{function}: default source and length"
        );

        let mut selected = RunOptions::default();
        selected
            .inputs
            .insert(1, InputValue::Source(BuiltinSeries::High));
        selected.inputs.insert(2, InputValue::Int(3));
        let expected_selected = compile(&format!(
            "//@version=6\nindicator(\"S\")\nplot(request.security(syminfo.tickerid, \"1W\", ta.{function}(high, 3)))\n"
        ));
        let selected_run = run(&program, &data, &selected);
        assert!(
            selected_run.errors.is_empty(),
            "{function}: {:?}",
            selected_run.errors
        );
        assert_eq!(
            floats(&selected_run.plots[0].values),
            floats(&run(&expected_selected, &data, &RunOptions::default()).plots[0].values),
            "{function}: selected source and length"
        );
        assert_ne!(
            floats(&default_run.plots[0].values),
            floats(&selected_run.plots[0].values)
        );

        selected.inputs.insert(2, InputValue::Int(0));
        let invalid = run(&program, &data, &selected);
        assert!(invalid
            .errors
            .iter()
            .any(|error| error.kind == RuntimeErrorKind::InvalidTaLength));

        selected.inputs.insert(2, InputValue::Int(3));
        selected.inputs.insert(
            1,
            InputValue::ExternalSource(ExternalSourceRef {
                script_id: "fixture_script".into(),
                plot_slot: 0,
                plot_label: "Signal".into(),
            }),
        );
        let external = run(&program, &data, &selected);
        assert!(external
            .errors
            .iter()
            .any(|error| error.kind == RuntimeErrorKind::Unsupported));
    }
}

#[test]
fn security_compound_input_change_and_historical_ema_match_literal_contexts() {
    use pinewasm_hir::{BuiltinSeries, InputValue};

    let mut data = data_from_close(
        &(0..28)
            .map(|index| 100.0 + f64::from(index))
            .collect::<Vec<_>>(),
    );
    for (high, close) in data.high.iter_mut().zip(&data.close) {
        *high = close + 20.0;
    }
    for (function, default_length, selected_length, suffix) in
        [("change", 1, 2, ""), ("ema", 2, 3, "[1]")]
    {
        let input_program = compile(&format!(
            "//@version=6\nindicator(\"S\")\nsrc = input.source(close)\nn = input.int({default_length})\nplot(request.security(syminfo.tickerid, \"1W\", ta.{function}(src, n){suffix}, lookahead=barmerge.lookahead_on))\n"
        ));
        let literal_program = compile(&format!(
            "//@version=6\nindicator(\"S\")\nplot(request.security(syminfo.tickerid, \"1W\", ta.{function}(high, {selected_length}){suffix}, lookahead=barmerge.lookahead_on))\n"
        ));
        let mut selected = RunOptions::default();
        selected
            .inputs
            .insert(0, InputValue::Source(BuiltinSeries::High));
        selected.inputs.insert(1, InputValue::Int(selected_length));
        let actual = run(&input_program, &data, &selected);
        let expected = run(&literal_program, &data, &RunOptions::default());
        assert!(actual.errors.is_empty(), "{function}: {:?}", actual.errors);
        assert!(
            expected.errors.is_empty(),
            "{function}: {:?}",
            expected.errors
        );
        assert_eq!(
            floats(&actual.plots[0].values),
            floats(&expected.plots[0].values),
            "{function}: selected inputs with {suffix}"
        );
        assert!(floats(&actual.plots[0].values).iter().any(Option::is_some));
    }
}

#[test]
fn syminfo_ticker_reads_the_real_symbol_not_the_member_name() {
    // Regression: `syminfo.ticker`/`syminfo.tickerid` used to be const tokens
    // whose VALUE was the member name, so a script displaying one showed the
    // literal text "syminfo.tickerid". They read the host's SymInfo now.
    let program = compile(
        "//@version=6\nindicator(\"S\")\nlog.info(syminfo.ticker)\nlog.info(syminfo.tickerid)\nplot(close)\n",
    );
    let mut data = data_from_close(&[1.0]);
    data.syminfo.ticker = "ASSETUSD".to_string();
    data.syminfo.prefix = "EXCHANGE".to_string();
    let outcome = run(&program, &data, &RunOptions::default());
    assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
    assert_eq!(outcome.logs[0].message, "ASSETUSD");
    // tickerid is derived as `prefix:ticker` when not supplied outright.
    assert_eq!(outcome.logs[1].message, "EXCHANGE:ASSETUSD");

    // An explicit host tickerid wins over the derivation.
    let mut data = data_from_close(&[1.0]);
    data.syminfo.ticker = "ASSETUSD".to_string();
    data.syminfo.prefix = "EXCHANGE".to_string();
    data.syminfo.tickerid = "ALTERNATE:ASSETUSD".to_string();
    let outcome = run(&program, &data, &RunOptions::default());
    assert_eq!(outcome.logs[1].message, "ALTERNATE:ASSETUSD");

    // With no prefix it degrades to the bare ticker rather than ":ASSETUSD".
    let mut data = data_from_close(&[1.0]);
    data.syminfo.ticker = "ASSETUSD".to_string();
    let outcome = run(&program, &data, &RunOptions::default());
    assert_eq!(outcome.logs[1].message, "ASSETUSD");
}

#[test]
fn security_compound_history_offset_reads_prior_htf_bar() {
    // History offsets: `close[1]` inside `request.security` indexes the REQUESTED
    // timeframe, so it is the previous *weekly* close, not the previous daily
    // one. Weekly closes are 106, 113, 118 (buckets closing at bars 6/13/18):
    //   bucket 0: na (no prior bucket)
    //   bucket 1: 106
    //   bucket 2: 113
    let series = security_expr_plot(
        "//@version=6\nindicator(\"S\")\nplot(request.security(syminfo.tickerid, \"1W\", close[1]))\n",
    );
    assert_eq!(series[6], None, "bucket 0 has no prior weekly bar");
    assert_eq!(series[13], Some(106.0), "bucket 1 sees bucket 0's close");
    assert_eq!(series[18], Some(113.0), "bucket 2 sees bucket 1's close");
    // Decisively not a chart-bar offset: the previous DAILY close at bar 18 is
    // 117 and the current weekly close is 118 — neither is 113.
    assert_ne!(series[18], Some(117.0));
    assert_ne!(series[18], Some(118.0));
}

#[test]
fn security_compound_history_offset_applies_to_a_ta_result() {
    // The offset wraps an arbitrary sub-expression, not just a source read:
    // `ta.sma(close, 2)[1]` is the PREVIOUS bucket's weekly SMA. Bucket SMAs
    // are na / 109.5 / 115.5, so offset 1 yields na / na / 109.5.
    let series = security_expr_plot(
        "//@version=6\nindicator(\"S\")\nplot(request.security(syminfo.tickerid, \"1W\", ta.sma(close, 2)[1]))\n",
    );
    assert_eq!(series[6], None, "bucket 0: no prior bucket");
    assert_eq!(series[13], None, "bucket 1: prior bucket's SMA was na");
    assert_eq!(series[18], Some(109.5), "bucket 2 sees bucket 1's SMA");
}

#[test]
fn security_compound_history_offset_folds_a_simple_int_expression() {
    // An `input.int`-derived history offset has type `simple int` and is fixed for the run,
    // so `close[n + 1]` with n = 1 bakes to offset 2 — bucket 2 reads bucket 0's
    // close (106). This is the "12-1 momentum" shape: close[1] / close[n+1] - 1.
    let series = security_expr_plot(
        "//@version=6\nindicator(\"S\")\nn = input.int(1)\nplot(request.security(syminfo.tickerid, \"1W\", close[n + 1]))\n",
    );
    assert_eq!(series[13], None, "bucket 1 has no bucket -1");
    assert_eq!(series[18], Some(106.0), "bucket 2 reads two buckets back");

    // And the full ratio at bucket 2: 113 / 106 - 1.
    let ratio = security_expr_plot(
        "//@version=6\nindicator(\"S\")\nn = input.int(1)\nplot(request.security(syminfo.tickerid, \"1W\", close[1] / close[n + 1] - 1.0))\n",
    );
    let expected = 113.0 / 106.0 - 1.0;
    assert!(
        ratio[18].is_some_and(|v| (v - expected).abs() < 1e-12),
        "bucket 2 momentum: got {:?}, want {expected}",
        ratio[18]
    );
}

#[test]
fn security_history_offset_accepts_the_int_spelling_of_a_division() {
    // With input n = 3, the offsets below are checked against the weekly buckets.
    // A history offset consumes the truncated index. With n = 3,
    // int(3 / 2) = int(1.5) = 1: bucket 2 reads bucket 1's close (113).
    let one = security_expr_plot(
        "//@version=6\nindicator(\"S\")\nn = input.int(3)\nplot(request.security(syminfo.tickerid, \"1W\", close[int(n / 2)]))\n",
    );
    assert_eq!(one[18], Some(113.0), "int(3 / 2) = 1 bucket back");

    // A const operand and a compound numerator: int((4 + 1) / 2) = int(2.5) = 2.
    let two = security_expr_plot(
        "//@version=6\nindicator(\"S\")\nN = 4\nplot(request.security(syminfo.tickerid, \"1W\", close[int((N + 1) / 2)]))\n",
    );
    assert_eq!(two[13], None, "bucket 1 has no bucket -1");
    assert_eq!(two[18], Some(106.0), "int(5 / 2) = 2 buckets back");

    let implicit_offset = security_expr_plot(
        "//@version=6\nindicator(\"S\")\nn = input.int(3)\nplot(request.security(syminfo.tickerid, \"1W\", close[n / 2]))\n",
    );
    assert_eq!(implicit_offset[18], Some(113.0), "3 / 2 indexes bucket 1");
}

#[test]
fn security_compound_sma_independent_state_lookahead_on() {
    // Same compound expression under lookahead_on: the forming bucket's SMA
    // leaks onto its earlier chart bars (repaint). Bars 14..18 all belong to
    // bucket 2, whose HTF SMA is 115.5 — so every one of them reads 115.5,
    // again distinct from any adjacent-daily-close average (per-context state).
    let series = security_expr_plot(
        "//@version=6\nindicator(\"S\")\nplot(request.security(syminfo.tickerid, \"1W\", ta.sma(close, 2), lookahead=barmerge.lookahead_on))\n",
    );
    for (bar, value) in series.iter().enumerate().take(19).skip(14) {
        assert_eq!(*value, Some(115.5), "bar {bar} repaints bucket 2 SMA");
    }
    // Bars 7..13 belong to bucket 1 ⇒ its SMA 109.5 repainted across them.
    assert_eq!(series[7], Some(109.5));
    assert_eq!(series[13], Some(109.5));
}

#[test]
fn security_compound_history_uses_resampled_context() {
    // History belongs to the requested context, not the chart context.
    // Weekly closes are 106, 113, 118, so close[1] on those weekly bars is
    // na, 106, 113. lookahead_on paints each completed requested value across
    // the chart bars in its bucket.
    let close_history = security_expr_plot(
        "//@version=6\nindicator(\"S\")\nplot(request.security(syminfo.tickerid, \"1W\", close[1], lookahead=barmerge.lookahead_on))\n",
    );
    assert_eq!(close_history[6], None);
    assert_eq!(close_history[7], Some(106.0));
    assert_eq!(close_history[13], Some(106.0));
    assert_eq!(close_history[14], Some(113.0));
    assert_eq!(close_history[18], Some(113.0));

    // The history operator can wrap a stateful secondary expression too.
    // ta.sma(close, 2) is na, 109.5, 115.5; shifting it by one requested bar
    // yields na, na, 109.5.
    let sma_history = security_expr_plot(
        "//@version=6\nindicator(\"S\")\nplot(request.security(syminfo.tickerid, \"1W\", ta.sma(close, 2)[1], lookahead=barmerge.lookahead_on))\n",
    );
    assert_eq!(sma_history[13], None);
    assert_eq!(sma_history[14], Some(109.5));
    assert_eq!(sma_history[18], Some(109.5));
}

#[test]
fn security_compound_atr_uses_requested_ohlc_and_wilder_smoothing() {
    let values = security_expr_plot(
        "//@version=6\nindicator(\"S\")\nplot(request.security(syminfo.tickerid, \"1W\", ta.atr(2), lookahead=barmerge.lookahead_on))\n",
    );
    assert!(values[..7].iter().all(Option::is_none));
    assert!(values[7..14].iter().all(|value| *value == Some(6.5)));
    assert!(values[14..].iter().all(|value| *value == Some(5.75)));
}

