    // an unrelated table does not leak into `currency_rate`.
    let mut tables = std::collections::HashMap::new();
    tables.insert("currency_rate/EUR/USD".to_string(), vec![1.1, 1.2, 1.3]);
    tables.insert("financial/ACME/TOTAL_REVENUE/FQ".to_string(), vec![9.0; 3]);
