#[test]
fn request_splits_earnings_economic_default_na_and_read_host_value() {
    // VALUE-ASSERTING roundtrip for the remaining request.* interfaces. Each
    // shares the READ_REQUEST mechanism but keys a distinct selector; assert
    // BOTH the default (`na` with no host table) AND the host-supplied series
    // per selector. One table drives the whole cluster.
    let cases: &[(&str, &str)] = &[
        // (source call, selector the constant args fold into)
        (
            "plot(request.splits(\"ACME\", \"numerator\"))",
            "splits/ACME/numerator",
        ),
        (
            "plot(request.earnings(\"ACME\", \"actual\"))",
            "earnings/ACME/actual",
        ),
        ("plot(request.economic(\"US\", \"GDP\"))", "economic/US/GDP"),
    ];
    for (call, selector) in cases {
        let src = format!("//@version=6\nindicator(\"R\")\n{call}\n");
        // Default: no host table -> na on every bar.
        let na = request_plot(&src, std::collections::HashMap::new());
        assert_eq!(
            na,
            vec![None, None, None],
            "{selector} default should be all-na"
        );
        // Host-supplied: the matching selector is read per bar, verbatim.
        let mut tables = std::collections::HashMap::new();
        tables.insert((*selector).to_string(), vec![1.5, 2.5, 3.5]);
        let hosted = request_plot(&src, tables);
        assert_eq!(
            hosted,
            vec![Some(1.5), Some(2.5), Some(3.5)],
            "{selector} should read its host series"
        );
    }
}

#[test]
fn request_non_constant_identifier_is_e0242() {
    // The identifying arguments must be constant string literals so the VM can
    // fold them into a selector; a runtime expression is rejected.
    let codes = security_error_codes(
        "//@version=6\nindicator(\"E\")\ns = syminfo.ticker\nplot(request.economic(s, \"GDP\"))\n",
    );
    assert!(codes.iter().any(|c| c == "E0242"), "got {codes:?}");
}

