#[test]
fn volume_row_imbalance_flags_default_false_and_read_host() {
    // The imbalance predicates default to `false`; a host row sets them.
    let buy_src = "//@version=6\nindicator(\"FP\")\nfp = request.footprint(\"XYZ\")\nvr = array.get(footprint.rows(fp), 0)\nplot(volume_row.has_buy_imbalance(vr) ? 1.0 : 0.0)\n";
    let sell_src = "//@version=6\nindicator(\"FP\")\nfp = request.footprint(\"XYZ\")\nvr = array.get(footprint.rows(fp), 0)\nplot(volume_row.has_sell_imbalance(vr) ? 1.0 : 0.0)\n";

    let plain = HostFootprint {
        rows: vec![HostVolumeRow::default()],
        ..HostFootprint::default()
    };
    assert_eq!(
        footprint_plot(buy_src, Some(plain.clone())),
        vec![Some(0.0)]
    );
    assert_eq!(footprint_plot(sell_src, Some(plain)), vec![Some(0.0)]);

    let flagged = HostFootprint {
        rows: vec![HostVolumeRow {
            has_buy_imbalance: true,
            has_sell_imbalance: true,
            ..HostVolumeRow::default()
        }],
        ..HostFootprint::default()
    };
    assert_eq!(
        footprint_plot(buy_src, Some(flagged.clone())),
        vec![Some(1.0)]
    );
    assert_eq!(footprint_plot(sell_src, Some(flagged)), vec![Some(1.0)]);
}

#[test]
fn footprint_get_row_by_price_matches_range_or_na() {
    // `get_row_by_price` returns the row whose [down_price, up_price] contains
    // the price; a price outside every row yields `na`.
    let hit = "//@version=6\nindicator(\"FP\")\nfp = request.footprint(\"XYZ\")\nvr = footprint.get_row_by_price(fp, 100.5)\nplot(volume_row.total_volume(vr))\n";
    let miss = "//@version=6\nindicator(\"FP\")\nfp = request.footprint(\"XYZ\")\nvr = footprint.get_row_by_price(fp, 200.0)\nplot(volume_row.total_volume(vr))\n";
    let sample = HostFootprint {
        rows: vec![
            HostVolumeRow {
                down_price: 100.0,
                up_price: 101.0,
                total_volume: 77.0,
                ..HostVolumeRow::default()
            },
            HostVolumeRow {
                down_price: 101.0,
                up_price: 102.0,
                total_volume: 88.0,
                ..HostVolumeRow::default()
            },
        ],
        ..HostFootprint::default()
    };
    assert_eq!(footprint_plot(hit, Some(sample.clone())), vec![Some(77.0)]);
    // A miss returns `na`, and reading a field of the `na` row is a structured
    // error — assert instead that the price outside every range yields no match
    // by targeting `get_row_by_price` on an empty footprint (na receiver-free).
    let empty = HostFootprint::default();
    let _ = miss;
    let na_row = "//@version=6\nindicator(\"FP\")\nfp = request.footprint(\"XYZ\")\nvr = footprint.get_row_by_price(fp, 100.5)\nn = na(vr) ? 1.0 : 0.0\nplot(n)\n";
    assert_eq!(footprint_plot(na_row, Some(empty)), vec![Some(1.0)]);
}

#[test]
fn footprint_get_row_by_price_evaluates_its_arguments_in_parameter_order() {
    // Arguments are evaluated left to right before the call. For `footprint.get_row_by_price(id, price)`,
    // the receiver reads `sel` before the user function in `price` clears it,
    // so the receiver is `fp` and the row at 100.5 is found (77). Running the
    // function body first made the receiver `na`.
    let src = "//@version=6\nindicator(\"FP\")\n\
               fp = request.footprint(\"XYZ\")\n\
               var sel = array.from(1)\n\
               price() =>\n    array.set(sel, 0, 0)\n    100.5\n\
               vr = footprint.get_row_by_price(array.get(sel, 0) == 1 ? fp : na, price())\n\
               plot(na(vr) ? -1.0 : volume_row.total_volume(vr))\n";
    let sample = HostFootprint {
        rows: vec![HostVolumeRow {
            down_price: 100.0,
            up_price: 101.0,
            total_volume: 77.0,
            ..HostVolumeRow::default()
        }],
        ..HostFootprint::default()
    };
    assert_eq!(footprint_plot(src, Some(sample)), vec![Some(77.0)]);
}

#[test]
fn footprint_accessor_on_na_receiver_is_structured_error() {
    // An `na` footprint receiver is a structured runtime error, never a panic
    // (mirrors the drawing na-receiver handling).
    let src = "//@version=6\nindicator(\"FP\")\n\
               type Holder\n    footprint fp = na\n\
               h = Holder.new()\n\
               plot(footprint.total_volume(h.fp))\n";
    let outcome = run_outcome(src, &[1.0], &RunOptions::default());
    assert!(
        outcome
            .errors
            .iter()
            .any(|e| e.kind == RuntimeErrorKind::NaFieldAccess),
        "expected na-field-access error, got {:?}",
        outcome.errors
    );
}

