#[test]
fn bid_and_ask_default_na_and_read_host_series() {
    // With no host quote series, `bid`/`ask` are `na` on every bar (they
    // are only carried on the "1T" tick timeframe; this VM has no tick feed).
    let program = compile("indicator(\"Q\")\nplot(bid)\nplot(ask)\n");
    let data = data_from_close(&[10.0, 11.0]);
    let outcome = run(&program, &data, &RunOptions::default());
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    assert_eq!(floats(&outcome.plots[0].values), vec![None, None]);
    assert_eq!(floats(&outcome.plots[1].values), vec![None, None]);
    // A host-supplied per-bar series flows through (short series → na past end).
    let mut data = data_from_close(&[10.0, 11.0, 12.0]);
    data.bid = vec![9.9, 10.9];
    data.ask = vec![10.1, 11.1, 12.1];
    let outcome = run(&program, &data, &RunOptions::default());
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    assert_eq!(
        floats(&outcome.plots[0].values),
        vec![Some(9.9), Some(10.9), None]
    );
    assert_eq!(
        floats(&outcome.plots[1].values),
        vec![Some(10.1), Some(11.1), Some(12.1)]
    );
}

