#[test]
fn dividends_earnings_future_series_default_na_and_host_supplied() {
    // The seven `dividends.future_*` / `earnings.future_*` built-in series read
    // the optional host upcoming-events feed. With no feed they are `na` on
    // every bar (this headless VM has no corporate-actions feed).
    let program = compile(
        "indicator(\"U\")\n\
         plot(dividends.future_amount)\n\
         plot(dividends.future_ex_date)\n\
         plot(dividends.future_pay_date)\n\
         plot(earnings.future_eps)\n\
         plot(earnings.future_period_end_time)\n\
         plot(earnings.future_revenue)\n\
         plot(earnings.future_time)\n",
    );
    let outcome = run(
        &program,
        &data_from_close(&[1.0, 2.0]),
        &RunOptions::default(),
    );
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    for plot in &outcome.plots {
        assert_eq!(floats(&plot.values), vec![None, None]);
    }
    // A host-supplied feed flows through (a per-run constant on every bar; plot
    // widens the epoch-ms int fields to float).
    let mut data = data_from_close(&[1.0, 2.0]);
    data.upcoming_events = crate::UpcomingEvents {
        dividends_future_amount: Some(0.24),
        dividends_future_ex_date: Some(1_700_000_000_000),
        dividends_future_pay_date: Some(1_700_500_000_000),
        earnings_future_eps: Some(1.53),
        earnings_future_period_end_time: Some(1_701_000_000_000),
        earnings_future_revenue: Some(94_000_000_000.0),
        earnings_future_time: Some(1_701_200_000_000),
    };
    let outcome = run(&program, &data, &RunOptions::default());
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    assert_eq!(
        floats(&outcome.plots[0].values),
        vec![Some(0.24), Some(0.24)]
    );
    assert_eq!(
        floats(&outcome.plots[1].values),
        vec![Some(1_700_000_000_000.0), Some(1_700_000_000_000.0)]
    );
    assert_eq!(
        floats(&outcome.plots[2].values),
        vec![Some(1_700_500_000_000.0), Some(1_700_500_000_000.0)]
    );
    assert_eq!(
        floats(&outcome.plots[3].values),
        vec![Some(1.53), Some(1.53)]
    );
    assert_eq!(
        floats(&outcome.plots[4].values),
        vec![Some(1_701_000_000_000.0), Some(1_701_000_000_000.0)]
    );
    assert_eq!(
        floats(&outcome.plots[5].values),
        vec![Some(94_000_000_000.0), Some(94_000_000_000.0)]
    );
    assert_eq!(
        floats(&outcome.plots[6].values),
        vec![Some(1_701_200_000_000.0), Some(1_701_200_000_000.0)]
    );
}

