#[test]
fn security_lower_tf_default_empty_and_host_supplied() {
    // Default: an empty array (this VM only aggregates UP; intrabar
    // decomposition is a host concern). `array.size` is 0 on every bar.
    let src = "//@version=6\nindicator(\"L\")\na = request.security_lower_tf(syminfo.tickerid, \"1\", close)\nplot(array.size(a))\n";
    let program = compile(src);
    let outcome = run(
        &program,
        &data_from_close(&[10.0, 11.0]),
        &RunOptions::default(),
    );
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    assert_eq!(floats(&outcome.plots[0].values), vec![Some(0.0), Some(0.0)]);

    // A host-supplied per-bar intrabar array: assert both size and a value.
    let sized = "//@version=6\nindicator(\"L\")\na = request.security_lower_tf(syminfo.tickerid, \"1\", close)\nplot(array.size(a) > 0 ? array.get(a, 1) : na)\n";
    let program = compile(sized);
    let mut data = data_from_close(&[10.0, 11.0]);
    let mut table = std::collections::HashMap::new();
    table.insert(
        "security_lower_tf/syminfo.tickerid/1/Close".to_string(),
        vec![vec![1.0, 2.0, 3.0], vec![4.0, 5.0]],
    );
    data.security_lower_tf_data = table;
    let outcome = run(&program, &data, &RunOptions::default());
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    // Bar 0 intrabar[1] == 2.0; bar 1 intrabar[1] == 5.0.
    assert_eq!(floats(&outcome.plots[0].values), vec![Some(2.0), Some(5.0)]);
}

#[test]
fn security_lower_tf_distinct_expressions_read_distinct_selectors() {
    // Regression: two calls on the same symbol/timeframe but different
    // expressions (`close` vs `volume`) must not collide on one selector —
    // each reads its own host-table entry.
    let src = "//@version=6\nindicator(\"L\")\n\
c = request.security_lower_tf(syminfo.tickerid, \"1\", close)\n\
v = request.security_lower_tf(syminfo.tickerid, \"1\", volume)\n\
plot(array.get(c, 0))\n\
plot(array.get(v, 0))\n";
    let program = compile(src);
    let mut data = data_from_close(&[10.0]);
    let mut table = std::collections::HashMap::new();
    table.insert(
        "security_lower_tf/syminfo.tickerid/1/Close".to_string(),
        vec![vec![111.0]],
    );
    table.insert(
        "security_lower_tf/syminfo.tickerid/1/Volume".to_string(),
        vec![vec![222.0]],
    );
    data.security_lower_tf_data = table;
    let outcome = run(&program, &data, &RunOptions::default());
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    assert_eq!(floats(&outcome.plots[0].values), vec![Some(111.0)]);
    assert_eq!(floats(&outcome.plots[1].values), vec![Some(222.0)]);
}

