#[test]
fn color_rgb_channels_and_transparency_are_exact() {
    // color.rgb(255, 0, 0) is opaque red; the accessors read back the exact
    // channels and default transparency 0.
    assert_eq!(
        run_plot(
            "//@version=6\nindicator(\"C\")\nc = color.rgb(255, 0, 0)\nplot(color.r(c))\n",
            &[1.0],
        ),
        vec![Some(255.0)]
    );
    assert_eq!(
        run_plot(
            "//@version=6\nindicator(\"C\")\nc = color.rgb(255, 0, 0)\nplot(color.g(c))\n",
            &[1.0],
        ),
        vec![Some(0.0)]
    );
    assert_eq!(
        run_plot(
            "//@version=6\nindicator(\"C\")\nc = color.rgb(255, 0, 0)\nplot(color.b(c))\n",
            &[1.0],
        ),
        vec![Some(0.0)]
    );
    assert_eq!(
        run_plot(
            "//@version=6\nindicator(\"C\")\nc = color.rgb(255, 0, 0)\nplot(color.t(c))\n",
            &[1.0],
        ),
        vec![Some(0.0)]
    );
}

#[test]
