#[test]
fn color_new_value_plots_identically_to_a_named_color() {
    // A color.new(color.red, 0) value is bit-identical to the named color.red
    // constant, so `==` over colors holds (proves the transp<->storage model
    // matches the named-constant convention).
    assert_eq!(
        run_plot(
            "//@version=6\nindicator(\"C\")\nc = color.new(color.red, 0)\nplot(c == color.red ? 1.0 : 0.0)\n",
            &[1.0],
        ),
        vec![Some(1.0)]
    );
}

#[test]
fn color_from_gradient_endpoints_and_midpoint_are_exact() {
    // Gradient from black (0,0,0) at value 0 to white (255,255,255) at value
    // 100. Endpoints return the pinned colors; the midpoint (value 50) blends
    // 50/50 to 128 (127.5 rounded half-away-from-zero).
    let bottom = "color.rgb(0, 0, 0)";
    let top = "color.rgb(255, 255, 255)";
    let grad = |v: &str, accessor: &str| {
        format!(
            "//@version=6\nindicator(\"C\")\nc = color.from_gradient({v}, 0, 100, {bottom}, {top})\nplot(color.{accessor}(c))\n"
        )
    };
    // Bottom endpoint: value 0 -> bottom color (0).
    assert_eq!(run_plot(&grad("0", "r"), &[1.0]), vec![Some(0.0)]);
    // Top endpoint: value 100 -> top color (255).
    assert_eq!(run_plot(&grad("100", "r"), &[1.0]), vec![Some(255.0)]);
    // Midpoint: value 50 -> 50/50 blend -> 128.
    assert_eq!(run_plot(&grad("50", "g"), &[1.0]), vec![Some(128.0)]);
}

#[test]
fn color_from_gradient_interpolates_transparency() {
    // Transparency is one of the four interpolated channels: from t=0 to
    // t=100, the midpoint blends to 50.
    let src = "//@version=6\nindicator(\"C\")\n\
               a = color.new(color.rgb(0, 0, 0), 0)\n\
               b = color.new(color.rgb(0, 0, 0), 100)\n\
               c = color.from_gradient(5.0, 0.0, 10.0, a, b)\n\
               plot(color.t(c))\n";
    assert_eq!(run_plot(src, &[1.0]), vec![Some(50.0)]);
}

#[test]
fn color_from_gradient_clamps_out_of_range_value() {
    // A value below the bottom pins to the bottom color; above the top pins to
    // the top color (no extrapolation).
    let bottom = "color.rgb(0, 0, 0)";
    let top = "color.rgb(255, 255, 255)";
    let below = format!(
        "//@version=6\nindicator(\"C\")\nc = color.from_gradient(-100, 0, 100, {bottom}, {top})\nplot(color.r(c))\n"
    );
    let above = format!(
        "//@version=6\nindicator(\"C\")\nc = color.from_gradient(9999, 0, 100, {bottom}, {top})\nplot(color.r(c))\n"
    );
    assert_eq!(run_plot(&below, &[1.0]), vec![Some(0.0)]);
    assert_eq!(run_plot(&above, &[1.0]), vec![Some(255.0)]);
}

#[test]
fn color_rgb_clamps_out_of_range_channels_without_panicking() {
    // Channels above 255 saturate to 255, below 0 to 0; transparency above
    // 100 saturates to 100. No panic on user-supplied out-of-range input.
    assert_eq!(
        run_plot(
            "//@version=6\nindicator(\"C\")\nc = color.rgb(999, -50, 300, 250)\nplot(color.r(c))\n",
            &[1.0],
        ),
        vec![Some(255.0)]
    );
    assert_eq!(
        run_plot(
            "//@version=6\nindicator(\"C\")\nc = color.rgb(999, -50, 300, 250)\nplot(color.g(c))\n",
            &[1.0],
        ),
        vec![Some(0.0)]
    );
    assert_eq!(
        run_plot(
            "//@version=6\nindicator(\"C\")\nc = color.rgb(999, -50, 300, 250)\nplot(color.t(c))\n",
            &[1.0],
        ),
        vec![Some(100.0)]
    );
}

#[test]
fn color_accessor_of_na_color_is_na() {
    // An accessor of an `na` color yields `na` (no panic). The ternary
    // produces an `na`-typed color on every bar (the false branch).
    let src = "//@version=6\nindicator(\"C\")\nc = false ? color.red : na\nplot(color.r(c))\n";
    assert_eq!(run_plot(src, &[1.0]), vec![None]);
}

#[test]
fn color_rgb_and_new_accept_float_arguments() {
    // Regression: float arguments are accepted. RGB channels round and clamp;
    // fractional color storage and input-qualified accessors remain distinct
    // from whole-percent constant accessors. Float
    // literals exercise the numeric (int-or-float) parameter path.
    // color.rgb(255.0, 127.6, 0.4) rounds to (255, 128, 0).
    assert_eq!(
        run_plot(
            "//@version=6\nindicator(\"C\")\nc = color.rgb(255.0, 127.6, 0.4)\nplot(color.g(c))\n",
            &[1.0],
        ),
        vec![Some(128.0)]
    );
    // A constant color.new accessor exposes the whole-percent constant value.
    assert_eq!(
        run_plot(
            "//@version=6\nindicator(\"C\")\nc = color.new(color.red, 50.4)\nplot(color.t(c))\n",
            &[1.0],
        ),
        vec![Some(50.0)]
    );
    // The constructor's stored color still retains its fractional payload.
    let stored = run(
        &compile(
            "//@version=6\nindicator(\"C\")\nc = color.new(color.red, 50.4)\nplot(close, color=c)\n",
        ),
        &data_from_close(&[1.0]),
        &RunOptions::default(),
    );
    assert!(stored.errors.is_empty(), "{:?}", stored.errors);
    assert!(matches!(
        stored.plots[0].colors[0].values[0],
        Value::Color { t: 50.4, .. }
    ));
    // Input-qualified transparency keeps the existing fractional runtime path.
    assert_eq!(
        run_plot(
            "//@version=6\nindicator(\"C\")\nt = input.float(50.4)\nc = color.new(color.red, t)\nplot(color.t(c))\n",
            &[1.0],
        ),
        vec![Some(50.4)]
    );
    // An out-of-range float channel still clamps (no panic).
    assert_eq!(
        run_plot(
            "//@version=6\nindicator(\"C\")\nc = color.rgb(300.5, 0.0, 0.0)\nplot(color.r(c))\n",
            &[1.0],
        ),
        vec![Some(255.0)]
    );
    // A float-typed *expression* channel (not just a literal) compiles and
    // runs — e.g. hl2 is a float series. Clamps to 255 for the large value.
    assert_eq!(
        run_plot(
            "//@version=6\nindicator(\"C\")\nc = color.rgb(hl2, 0.0, 0.0)\nplot(color.r(c))\n",
            &[1000.0],
        ),
        vec![Some(255.0)]
    );
}

// ---------------------------------------------------------------------------
// timeframe.* / syminfo.* / session.* context accessors. Values are
// asserted end-to-end: strings via a `== "literal"` ternary check, bools via a
// `? 1.0 : 0.0` ternary, ints/floats plotted directly. Defaults come from
// `MarketData::default()` (timeframe "1D", `SymInfo::default()`).
// ---------------------------------------------------------------------------

/// Run a single-bar program with an explicit chart timeframe, returning the
/// first plot's values.
fn plot_one_bar_tf(source: &str, timeframe: &str) -> Vec<Option<f64>> {
    let program = compile(source);
    let mut data = data_from_close(&[1.0]);
    data.timeframe = timeframe.to_string();
    let outcome = run(&program, &data, &RunOptions::default());
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    floats(&outcome.plots[0].values)
}

#[test]
fn timeframe_period_and_isdaily_default_to_one_day() {
    // Default chart timeframe is "1D": period == "1D", isdaily true.
    assert_eq!(
        str_eq_check("timeframe.period", "1D"),
        Some(1.0),
        "timeframe.period should be the default \"1D\""
    );
    let out = plot_one_bar("indicator(\"T\")\nplot(timeframe.isdaily ? 1.0 : 0.0)\n");
    assert_eq!(out[0], Some(1.0), "timeframe.isdaily should be true for 1D");
    // main_period mirrors period here.
    assert_eq!(str_eq_check("timeframe.main_period", "1D"), Some(1.0));
    // isdwm true, isintraday false, multiplier 1 for "1D".
    assert_eq!(
        plot_one_bar("indicator(\"T\")\nplot(timeframe.isdwm ? 1.0 : 0.0)\n")[0],
        Some(1.0)
    );
    assert_eq!(
        plot_one_bar("indicator(\"T\")\nplot(timeframe.isintraday ? 1.0 : 0.0)\n")[0],
        Some(0.0)
    );
    assert_eq!(
        plot_one_bar("indicator(\"T\")\nplot(timeframe.multiplier)\n")[0],
        Some(1.0)
    );
}

#[test]
fn timeframe_predicates_track_the_chart_timeframe() {
    // A 30-second intraday timeframe: isseconds/isintraday true, multiplier 30.
    assert_eq!(
        plot_one_bar_tf(
            "indicator(\"T\")\nplot(timeframe.isseconds ? 1.0 : 0.0)\n",
            "30S"
        )[0],
        Some(1.0)
    );
    assert_eq!(
        plot_one_bar_tf(
            "indicator(\"T\")\nplot(timeframe.isintraday ? 1.0 : 0.0)\n",
            "30S"
        )[0],
        Some(1.0)
    );
    assert_eq!(
        plot_one_bar_tf("indicator(\"T\")\nplot(timeframe.multiplier)\n", "30S")[0],
        Some(30.0)
    );
    // A bare number is minutes.
    assert_eq!(
        plot_one_bar_tf(
            "indicator(\"T\")\nplot(timeframe.isminutes ? 1.0 : 0.0)\n",
            "5"
        )[0],
        Some(1.0)
    );
    // Weekly / monthly are dwm, not intraday.
    assert_eq!(
        plot_one_bar_tf(
            "indicator(\"T\")\nplot(timeframe.isweekly ? 1.0 : 0.0)\n",
            "1W"
        )[0],
        Some(1.0)
    );
    assert_eq!(
        plot_one_bar_tf(
            "indicator(\"T\")\nplot(timeframe.ismonthly ? 1.0 : 0.0)\n",
            "3M"
        )[0],
        Some(1.0)
    );
    // No tick timeframes: isticks is always false.
    assert_eq!(
        plot_one_bar("indicator(\"T\")\nplot(timeframe.isticks ? 1.0 : 0.0)\n")[0],
        Some(0.0)
    );
}

#[test]
fn timeframe_in_seconds_and_from_seconds_round_trip() {
    // timeframe.in_seconds("1W") == 604800.
    assert_eq!(
        plot_one_bar("indicator(\"T\")\nplot(timeframe.in_seconds(\"1W\"))\n")[0],
        Some(604_800.0)
    );
    assert_eq!(
        plot_one_bar("indicator(\"T\")\nplot(timeframe.in_seconds(\"1D\"))\n")[0],
        Some(86_400.0)
    );
    assert_eq!(
        plot_one_bar("indicator(\"T\")\nplot(timeframe.in_seconds(\"30S\"))\n")[0],
        Some(30.0)
    );
    // from_seconds: 604800 -> "7D", 300 -> "5" (bare minutes), 30 -> "30S".
    assert_eq!(
        str_eq_check("timeframe.from_seconds(604800)", "7D"),
        Some(1.0)
    );
    assert_eq!(str_eq_check("timeframe.from_seconds(300)", "5"), Some(1.0));
    assert_eq!(str_eq_check("timeframe.from_seconds(30)", "30S"), Some(1.0));
}

/// The bars on which `timeframe.change(<timeframe>)` is true, over `data`.
fn timeframe_change_bars(timeframe: &str, data: &MarketData) -> Vec<usize> {
    let source =
        format!("indicator(\"TC\")\nplot(timeframe.change(\"{timeframe}\") ? 1.0 : 0.0)\n");
    let outcome = run(&compile(&source), data, &RunOptions::default());
    assert!(
        outcome.errors.is_empty(),
        "{timeframe}: {:?}",
        outcome.errors
    );
    floats(&outcome.plots[0].values)
        .iter()
        .enumerate()
        .filter(|(_, value)| **value == Some(1.0))
        .map(|(bar, _)| bar)
        .collect()
}

/// A feed of `count` bars `step_ms` apart from `start` (epoch ms), on chart
/// timeframe `timeframe`.
fn spaced_feed(start: i64, step_ms: i64, count: usize, timeframe: &str) -> MarketData {
    let mut data = data_from_close(&vec![1.0; count]);
    data.time = (0..count).map(|bar| start + bar as i64 * step_ms).collect();
    data.timeframe = timeframe.to_string();
    data
}

const DAY_MS: i64 = 86_400_000;
/// 2024-01-25, a Thursday, 00:00 UTC.
const THU_2024_01_25: i64 = 1_706_140_800_000;

#[test]
fn timeframe_change_opens_calendar_months_quarters_and_years() {
    // Daily bars from Thursday 2024-01-25 through 2024-12-31 (342 bars).
    let data = spaced_feed(THU_2024_01_25, DAY_MS, 342, "1D");
    // The first bar, then the first day of each month: Feb 1 is day 7, and
    // 2024 is a leap year.
    let month_starts = [0, 7, 36, 67, 97, 128, 158, 189, 220, 250, 281, 311];
    assert_eq!(timeframe_change_bars("M", &data), month_starts);
    assert_eq!(timeframe_change_bars("1M", &data), month_starts);
    // Quarters open on Apr 1, Jul 1 and Oct 1.
    assert_eq!(timeframe_change_bars("3M", &data), [0, 67, 158, 250]);
    // A 12-month bucket is the calendar year: nothing reopens inside 2024.
    assert_eq!(timeframe_change_bars("12M", &data), [0]);
}

#[test]
fn timeframe_change_opens_monday_weeks() {
    // Thursday 2024-01-25 to Sunday 2024-03-10: Mondays are 4 days apart
    // from the first bar, then every 7.
    let data = spaced_feed(THU_2024_01_25, DAY_MS, 46, "1D");
    assert_eq!(
        timeframe_change_bars("W", &data),
        [0, 4, 11, 18, 25, 32, 39]
    );
    assert_eq!(
        timeframe_change_bars("1W", &data),
        [0, 4, 11, 18, 25, 32, 39]
    );
    // Two-week blocks restart at the first Monday of the year (2024-01-01),
    // so they open on Jan 29 (bar 4), Feb 12 and Feb 26.
    assert_eq!(timeframe_change_bars("2W", &data), [0, 4, 18, 32]);
    // Seven days is not a week: it walks from the first bar's day.
    assert_eq!(
        timeframe_change_bars("7D", &data),
        [0, 7, 14, 21, 28, 35, 42]
    );
}

#[test]
fn timeframe_change_walks_fixed_widths_on_the_exchange_clock() {
    // Hourly bars starting at 13:00 UTC: a 240-minute bucket opens at
    // 16:00, 20:00, 00:00, ..., whatever hour the feed starts at.
    let hourly = spaced_feed(THU_2024_01_25 + 13 * 3_600_000, 3_600_000, 30, "60");
    assert_eq!(
        timeframe_change_bars("240", &hourly),
        [0, 3, 7, 11, 15, 19, 23, 27]
    );
    // A width that does not divide a day restarts at midnight: 420 minutes
    // opens at 00:00, 07:00, 14:00 and 21:00 each day.
    assert_eq!(timeframe_change_bars("420", &hourly), [0, 1, 8, 11, 18, 25]);
    // A day opens at the exchange's midnight: three hours east of UTC, that
    // is 21:00 UTC.
    let mut east = hourly.clone();
    east.syminfo.timezone = "UTC+3".to_string();
    east.syminfo.session_hours = "24x7".to_string();
    assert_eq!(timeframe_change_bars("D", &east), [0, 8]);
    assert_eq!(timeframe_change_bars("D", &hourly), [0, 11]);
    // Two days walk from the first bar's day.
    let daily = spaced_feed(THU_2024_01_25, DAY_MS, 9, "1D");
    assert_eq!(timeframe_change_bars("2D", &daily), [0, 2, 4, 6, 8]);
}

#[test]
fn timeframe_change_follows_the_trading_day_lane() {
    // Daily bars that open at 22:00 UTC the evening before their trading
    // day, as a futures feed does: the month follows the trading day, not
    // the bar's opening date.
    let mut data = spaced_feed(THU_2024_01_25 - 2 * 3_600_000, DAY_MS, 10, "1D");
    data.trading_day = (0..10).map(|bar| THU_2024_01_25 + bar * DAY_MS).collect();
    // Trading days Jan 25 .. Feb 3: February opens on bar 7, whose bar
    // opened on Jan 31 at 22:00.
    assert_eq!(timeframe_change_bars("M", &data), [0, 7]);
}

#[test]
fn timeframe_change_is_time_opening_a_new_bucket() {
    // For every timeframe, the call is true exactly when `time(timeframe)`
    // differs from the previous bar's, on the first bar, and on every bar
    // where `time` has no bucket to report: a timeframe below the chart's
    // reads `na`, and each chart bar opens a new period of it.
    let hourly = spaced_feed(THU_2024_01_25 + 5 * 3_600_000, 3_600_000, 24 * 40, "60");
    let daily = spaced_feed(THU_2024_01_25, DAY_MS, 400, "1D");
    for (timeframe, data) in [
        ("1", &hourly),
        ("45", &hourly),
        ("120S", &hourly),
        ("60", &hourly),
        ("90", &hourly),
        ("240", &hourly),
        ("1D", &hourly),
        ("D", &daily),
        ("3D", &daily),
        ("W", &daily),
        ("3W", &daily),
        ("M", &daily),
        ("6M", &daily),
        ("12M", &daily),
        ("", &daily),
    ] {
        let source = format!(
            "indicator(\"T\")\nt = time(\"{timeframe}\")\nplot(timeframe.change(\"{timeframe}\") == (bar_index == 0 or na(t) or t != t[1]) ? 1.0 : 0.0)\n"
        );
        let outcome = run(&compile(&source), data, &RunOptions::default());
        assert!(
            outcome.errors.is_empty(),
            "{timeframe}: {:?}",
            outcome.errors
        );
        let agrees = floats(&outcome.plots[0].values);
        assert!(
            agrees.iter().all(|value| *value == Some(1.0)),
            "{timeframe:?}: disagrees on bars {:?}",
            agrees
                .iter()
                .enumerate()
                .filter(|(_, value)| **value != Some(1.0))
                .map(|(bar, _)| bar)
                .take(5)
                .collect::<Vec<_>>()
        );
    }
}

#[test]
fn timeframe_change_nested_in_its_own_timeframe_compiles() {
    // The inner call's hidden names are taken while the outer timeframe is
    // analysed; the outer call's own must not collide with them.
    let data = spaced_feed(THU_2024_01_25, DAY_MS, 60, "1D");
    // An inner literal, and an inner computed timeframe, which lowers to a
    // temporary of its own.
    for source in [
        "indicator(\"T\")\nplot(timeframe.change(timeframe.change(\"D\") ? \"M\" : \"W\") ? 1.0 : 0.0)\n",
        "indicator(\"T\")\ntf = bar_index >= 0 ? \"D\" : \"W\"\nplot(timeframe.change(timeframe.change(tf) ? \"M\" : \"W\") ? 1.0 : 0.0)\n",
    ] {
        let outcome = run(&compile(source), &data, &RunOptions::default());
        assert!(outcome.errors.is_empty(), "{source}: {:?}", outcome.errors);
        // On daily bars every bar opens a day, so the outer timeframe is
        // always "M": the first bar and the first day of each month.
        let bars: Vec<usize> = floats(&outcome.plots[0].values)
            .iter()
            .enumerate()
            .filter(|(_, value)| **value == Some(1.0))
            .map(|(bar, _)| bar)
            .collect();
        assert_eq!(bars, timeframe_change_bars("M", &data), "{source}");
    }
}

#[test]
fn timeframe_change_reads_a_const_or_input_timeframe_as_the_literal() {
    let data = spaced_feed(THU_2024_01_25, DAY_MS, 120, "1D");
    let literal = timeframe_change_bars("M", &data);
    for source in [
        "indicator(\"T\")\nconst string TF = \"M\"\nplot(timeframe.change(TF) ? 1.0 : 0.0)\n",
        "indicator(\"T\")\ntf = input.timeframe(\"M\")\nplot(timeframe.change(tf) ? 1.0 : 0.0)\n",
        "indicator(\"T\")\ntf = bar_index >= 0 ? \"M\" : \"W\"\nplot(timeframe.change(tf) ? 1.0 : 0.0)\n",
    ] {
        let outcome = run(&compile(source), &data, &RunOptions::default());
        assert!(outcome.errors.is_empty(), "{source}: {:?}", outcome.errors);
        let bars: Vec<usize> = floats(&outcome.plots[0].values)
            .iter()
            .enumerate()
            .filter(|(_, value)| **value == Some(1.0))
            .map(|(bar, _)| bar)
            .collect();
        assert_eq!(bars, literal, "{source}");
    }
}

#[test]
fn syminfo_string_reads_default_and_host_supplied() {
    // Default currency is the empty string.
    assert_eq!(str_eq_check("syminfo.currency", ""), Some(1.0));
    // Host-supplied currency flows through.
    let program =
        compile("indicator(\"S\")\nb = syminfo.currency == \"USD\"\nplot(b ? 1.0 : 0.0)\n");
    let mut data = data_from_close(&[1.0]);
    data.syminfo.currency = "USD".to_string();
    let outcome = run(&program, &data, &RunOptions::default());
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    assert_eq!(floats(&outcome.plots[0].values)[0], Some(1.0));
    // Default timezone is "UTC".
    assert_eq!(str_eq_check("syminfo.timezone", "UTC"), Some(1.0));
}

#[test]
fn syminfo_numeric_reads_defaults() {
    // mintick default 0.01; minmove 1; pricescale 100; pointvalue/mincontract 1.
    assert_eq!(
        plot_one_bar("indicator(\"S\")\nplot(syminfo.mintick)\n")[0],
        Some(0.01)
    );
    assert_eq!(
        plot_one_bar("indicator(\"S\")\nplot(syminfo.minmove)\n")[0],
        Some(1.0)
    );
    assert_eq!(
        plot_one_bar("indicator(\"S\")\nplot(syminfo.pricescale)\n")[0],
        Some(100.0)
    );
    assert_eq!(
        plot_one_bar("indicator(\"S\")\nplot(syminfo.pointvalue)\n")[0],
        Some(1.0)
    );
    // Host-supplied pointvalue flows through.
    let program = compile("indicator(\"S\")\nplot(syminfo.pointvalue)\n");
    let mut data = data_from_close(&[1.0]);
    data.syminfo.pointvalue = 50.0;
    let outcome = run(&program, &data, &RunOptions::default());
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    assert_eq!(floats(&outcome.plots[0].values)[0], Some(50.0));
}

#[test]
fn session_first_and_last_bar_predicates() {
    // session.isfirstbar true on bar 0, false after; session.islastbar true on
    // the final bar only. Three bars.
    let program = compile(
        "indicator(\"S\")\n\
         plot(session.isfirstbar ? 1.0 : 0.0)\n\
         plot(session.islastbar ? 1.0 : 0.0)\n\
         plot(session.ismarket ? 1.0 : 0.0)\n\
         plot(session.ispremarket ? 1.0 : 0.0)\n",
    );
    let outcome = run(
        &program,
        &data_from_close(&[10.0, 11.0, 12.0]),
        &RunOptions::default(),
    );
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    assert_eq!(
        floats(&outcome.plots[0].values),
        vec![Some(1.0), Some(0.0), Some(0.0)],
        "isfirstbar true only on bar 0"
    );
    assert_eq!(
        floats(&outcome.plots[1].values),
        vec![Some(0.0), Some(0.0), Some(1.0)],
        "islastbar true only on the final bar"
    );
    // ismarket always true; ispremarket always false (single regular session).
    assert_eq!(
        floats(&outcome.plots[2].values),
        vec![Some(1.0), Some(1.0), Some(1.0)]
    );
    assert_eq!(
        floats(&outcome.plots[3].values),
        vec![Some(0.0), Some(0.0), Some(0.0)]
    );
}

// ---- timestamp() ----------------------------------------------------------

#[test]
fn timestamp_utc_epoch_ms_is_hand_computed() {
    // 2021-01-01T00:00:00Z = 1_609_459_200_000 ms (hand-computed UTC epoch).
    assert_eq!(
        plot_one_bar("indicator(\"T\")\nplot(timestamp(2021, 1, 1))\n")[0],
        Some(1_609_459_200_000.0)
    );
    // The Unix epoch itself is 0.
    assert_eq!(
        plot_one_bar("indicator(\"T\")\nplot(timestamp(1970, 1, 1, 0, 0, 0))\n")[0],
        Some(0.0)
    );
    // Full date/time: 2021-06-15T13:45:30Z.
    let expected = 1_623_764_730_000.0; // hand-computed UTC epoch ms
    assert_eq!(
        plot_one_bar("indicator(\"T\")\nplot(timestamp(2021, 6, 15, 13, 45, 30))\n")[0],
        Some(expected)
    );
}

#[test]
fn timestamp_timezone_overload_shifts_wall_clock() {
    // Wall-clock 2021-01-01T00:00:00 in UTC-5 is 05:00:00Z, i.e. 5h after the
    // UTC-midnight epoch: 1_609_459_200_000 + 5*3600*1000.
    let expected = 1_609_459_200_000.0 + 5.0 * 3600.0 * 1000.0;
    assert_eq!(
        plot_one_bar("indicator(\"T\")\nplot(timestamp(\"UTC-5\", 2021, 1, 1, 0, 0))\n")[0],
        Some(expected)
    );
    // Bare "UTC" is offset 0, so it matches the UTC overload.
    assert_eq!(
        plot_one_bar("indicator(\"T\")\nplot(timestamp(\"UTC\", 2021, 1, 1, 0, 0))\n")[0],
        Some(1_609_459_200_000.0)
    );
}

#[test]
fn timestamp_na_field_is_na() {
    // An na numeric field propagates to na (typed `int y = na` supplies the
    // field type; a bare `na` in argument position is E0220, as elsewhere).
    assert_eq!(
        plot_one_bar("indicator(\"T\")\nint y = na\nplot(timestamp(y, 1, 1))\n")[0],
        None
    );
}

