// ---- Type casts, unary plus, ta.tr, weekofyear, and request.quandl ---------

#[test]
fn cast_int_truncates_toward_zero() {
    // int(3.7) == 3; int(-3.7) == -3 (truncation toward zero, not floor).
    assert_eq!(
        plot_one_bar("indicator(\"C\")\nplot(int(3.7))\n"),
        vec![Some(3.0)]
    );
    assert_eq!(
        plot_one_bar("indicator(\"C\")\nplot(int(-3.7))\n"),
        vec![Some(-3.0)]
    );
    // An int argument passes through.
    assert_eq!(
        plot_one_bar("indicator(\"C\")\nplot(int(5))\n"),
        vec![Some(5.0)]
    );
}

#[test]
fn cast_int_of_na_is_na() {
    let out = plot_one_bar("indicator(\"C\")\nn = int(na)\nplot(na(n) ? -1.0 : n)\n");
    assert_eq!(out, vec![Some(-1.0)]);
}

#[test]
fn cast_float_widens_int() {
    // float(5) == 5.0 and divides as a float (5/2 -> 2.5, not int 2).
    assert_eq!(
        plot_one_bar("indicator(\"C\")\nplot(float(5) / 2)\n"),
        vec![Some(2.5)]
    );
}

#[test]
fn cast_bool_semantics() {
    // bool(1) / bool(2.5) -> true; bool(0) / bool(na) -> false.
    assert_eq!(
        plot_one_bar("indicator(\"C\")\nplot(bool(1) ? 1.0 : 0.0)\n"),
        vec![Some(1.0)]
    );
    assert_eq!(
        plot_one_bar("indicator(\"C\")\nplot(bool(2.5) ? 1.0 : 0.0)\n"),
        vec![Some(1.0)]
    );
    assert_eq!(
        plot_one_bar("indicator(\"C\")\nplot(bool(0) ? 1.0 : 0.0)\n"),
        vec![Some(0.0)]
    );
    // bool(na) is false, not na, as the test asserts.
    assert_eq!(
        plot_one_bar("indicator(\"C\")\nplot(bool(na) ? 1.0 : 0.0)\n"),
        vec![Some(0.0)]
    );
}

#[test]
fn cast_string_equals_str_tostring() {
    // string(42) == "42"; matches str.tostring.
    assert_eq!(str_eq_check("string(42)", "42"), Some(1.0));
    assert_eq!(str_eq_check("string(true)", "true"), Some(1.0));
}

