#[test]
fn ternary_nested_in_binary_keeps_live_outer_operands() {
    // The outer `close * 100` and `x` operands are live on the CSIL stack
    // while the ternary branches; both arms and the nested ternary must see
    // the same stack at the join.
    let src = "//@version=6\nindicator(\"nested ternary\")\na = array.new_float(0)\nx = close + 1.0\ny = close * 2.0\nplot(close * 100.0 + (x + (close > 0 ? (y > 1.0 ? y : array.get(a, 0)) : array.get(a, 1))))\n";
    // close = 1: 100 + (2 + 2) = 104.
    assert_eq!(plot_one_bar(src), vec![Some(104.0)]);
    let program = compile(
        "//@version=6\nindicator(\"nested ternary bars\")\nx = close + 1.0\nplot(x + (close > 2.0 ? close * 10.0 : close - 1.0) + math.max(x, close > 1.0 ? x * 2.0 : x / 2.0))\n",
    );
    let outcome = run(
        &program,
        &data_from_close(&[1.0, 2.0, 3.0]),
        &RunOptions::default(),
    );
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    // close 1: 2 + 0 + max(2, 1) = 4; close 2: 3 + 1 + max(3, 6) = 10;
    // close 3: 4 + 30 + max(4, 8) = 42.
    assert_eq!(
        floats(&outcome.plots[0].values),
        vec![Some(4.0), Some(10.0), Some(42.0)]
    );
}

// ---- ta.pivot_point_levels -------------------------------------------------

/// A nine-bar feed where `bar_index == 7` closes the accumulated first period
/// (bars 0..6) and begins a new one. Its known prior OHLC is 100/120/90/90.
fn pivot_daily_feed() -> MarketData {
    ohlc_data(&[
        (100.0, 110.0, 100.0, 105.0), // day 0
        (105.0, 115.0, 102.0, 110.0), // day 1
        (110.0, 120.0, 105.0, 115.0), // day 2  -> bucket high = 120
        (115.0, 118.0, 100.0, 112.0), // day 3
        (112.0, 116.0, 90.0, 108.0),  // day 4  -> bucket low = 90
        (108.0, 114.0, 95.0, 100.0),  // day 5
        (100.0, 112.0, 98.0, 90.0),   // day 6  -> bucket close = 90
        (90.0, 95.0, 85.0, 92.0),     // day 7  (bucket 1, forming)
        (92.0, 99.0, 88.0, 95.0),     // day 8
    ])
}

/// Compile `source`, run it against [`pivot_daily_feed`], and return the first
/// plot's floats. Any run/analysis error fails the test.
fn pivot_plot(source: &str) -> Vec<Option<f64>> {
    let program = compile(source);
    let outcome = run(&program, &pivot_daily_feed(), &RunOptions::default());
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    floats(&outcome.plots[0].values)
}

/// Plot pivot-array index `idx` guarded by the array size, so early bars where
/// the array is empty read `na` instead of a structured out-of-bounds error.
/// Uses an `if` value-expression (lazy — only the taken branch runs, unlike the
/// eager ternary) so `array.get` never executes on an empty array.
fn pivot_get_src(system: &str, anchor: &str, idx: usize) -> String {
    format!(
        "//@version=6\nindicator(\"P\")\np = ta.pivot_point_levels(\"{system}\", {anchor})\n\
         v = if array.size(p) > {idx}\n    array.get(p, {idx})\nelse\n    na\nplot(v)\n"
    )
}

#[test]
fn pivot_traditional_levels_from_prior_weekly_hlc() {
    // Bucket 0 (days 0..6) HLC = 120/90/90 ⇒ P=(120+90+90)/3=100, range=30.
    // Traditional [P,R1,S1,R2,S2,R3,S3,R4,S4,R5,S5] is fully defined:
    //   P=100, R1=2P-L=110, S1=2P-H=80, R2=P+range=130, S2=P-range=70,
    //   R3=2P+(H-2L)=140, S3=2P-(2H-L)=50, R4=3P+(H-3L)=150, S4=3P-(3H-L)=30,
    //   R5=4P+(H-4L)=160, S5=4P-(4H-L)=10.
    // Pivots for the CURRENT period use the PRIOR period's HLC: bars 7..8 (in
    // the forming bucket 1) read bucket 0's HLC. Bars 0..6 (bucket 0) have no
    // prior period ⇒ empty array ⇒ na.
    let expected = [
        100.0, 110.0, 80.0, 130.0, 70.0, 140.0, 50.0, 150.0, 30.0, 160.0, 10.0,
    ];
    for (i, want) in expected.iter().enumerate() {
        let series = pivot_plot(&pivot_get_src("Traditional", "bar_index == 7", i));
        assert_eq!(series[7], Some(*want), "Traditional level {i} on bar 7");
        assert_eq!(series[6], None, "no prior period yet on bar 6 (level {i})");
    }
}

#[test]
fn pivot_traditional_array_size_is_eleven_once_a_prior_period_exists() {
    // The pivot array always carries the 11-slot shape once a PRIOR anchor
    // period exists; it is empty (size 0) while still in the first period.
    let series = pivot_plot(
        "//@version=6\nindicator(\"P\")\np = ta.pivot_point_levels(\"Traditional\", bar_index == 7)\nplot(array.size(p))\n",
    );
    // The return shape is always 11 slots, including before the first anchor.
    for (bar, v) in series.iter().enumerate().take(7) {
        assert_eq!(*v, Some(11.0), "bar {bar} retains the 11-slot shape");
    }
    // Bars 7..8 are the second period ⇒ the 11-slot prior-period array.
    assert_eq!(series[7], Some(11.0));
    assert_eq!(series[8], Some(11.0));
}

#[test]
fn pivot_fibonacci_levels_and_na_upper_extensions() {
    // Same prior-period HLC (120/90/90) ⇒ P=100, range=30. Fibonacci:
    //   R1=P+0.382r=111.46, S1=P-0.382r=88.54, R2=P+0.618r=118.54,
    //   S2=P-0.618r=81.46, R3=P+r=130, S3=P-r=70; R4/S4/R5/S5 are na.
    let p = 100.0;
    let r = 30.0;
    let expected = [
        Some(p),
        Some(p + 0.382 * r),
        Some(p - 0.382 * r),
        Some(p + 0.618 * r),
        Some(p - 0.618 * r),
        Some(p + r),
        Some(p - r),
    ];
    for (i, want) in expected.iter().enumerate() {
        let series = pivot_plot(&pivot_get_src("Fibonacci", "bar_index == 7", i));
        assert_eq!(series[7], *want, "Fibonacci level {i} on bar 7");
    }
    // The upper-extension slots (R4=7, S4=8, R5=9, S5=10) Fibonacci omits are na
    // — the array is still length 11, but those cells are na.
    for i in 7..=10 {
        let series = pivot_plot(&pivot_get_src("Fibonacci", "bar_index == 7", i));
        assert_eq!(series[7], None, "Fibonacci omits level {i} (na)");
    }
}

#[test]
fn pivot_woodie_classic_demark_and_camarilla_match_published_formulas() {
    // Prior anchor OHLC = 100/120/90/90; current anchor open = 90.
    // Values below follow the classic pivot-point formulas.
    // Verify representative levels and each system's undefined
    // slots, so both formula inputs and 11-slot layout are covered.
    let cases = [
        ("Woodie", 0, Some(97.5)),  // P=(120+90+2*90)/4
        ("Woodie", 7, Some(165.0)), // R4 = R3 + range
        ("Woodie", 9, None),
        ("Classic", 5, Some(160.0)), // R3 = P + 2*range
        ("Classic", 8, Some(10.0)),  // S4 = P - 3*range
        ("Classic", 9, None),
        ("DM", 0, Some(97.5)), // bearish previous candle: X=2L+H+C
        ("DM", 1, Some(105.0)),
        ("DM", 2, Some(75.0)),
        ("DM", 3, None),
        ("Camarilla", 1, Some(92.75)), // C + 1.1*range/12
        ("Camarilla", 9, Some(120.0)), // H/L*C
        ("Camarilla", 10, Some(60.0)),
    ];
    for (system, index, expected) in cases {
        let values = pivot_plot(&pivot_get_src(system, "bar_index == 7", index));
        assert_eq!(values[7], expected, "{system} level index {index}");
    }
}

