#[test]
fn pivot_developing_tracks_the_active_period() {
    let source = "//@version=6\nindicator(\"P\")\np = ta.pivot_point_levels(\"Traditional\", bar_index == 7, developing=true)\nplot(array.get(p, 1))\n";
    let values = pivot_plot(source);
    // On bar 6, the accumulated bars 0..6 have H=120, L=90, C=90, P=100.
    assert_eq!(values[6], Some(110.0));
    // At the anchor, developing pivots restart from the new period's first bar.
    let current_p = (95.0 + 85.0 + 92.0) / 3.0;
    assert_eq!(values[7], Some(2.0 * current_p - 85.0));
}

