#[test]
fn chart_point_named_arguments_bind_coordinates_and_copy_values() {
    let src = "indicator(\"Point names\")\n\
               p = chart.point.new(price=2.5, index=7, time=1000)\n\
               q = chart.point.copy(id=p)\n\
               i = chart.point.from_index(price=3.5, index=8)\n\
               t = chart.point.from_time(price=4.5, time=2000)\n\
               n = chart.point.now()\n\
               plot(p.time)\n\
               plot(p.index)\n\
               plot(p.price)\n\
               plot(q.time)\n\
               plot(q.index)\n\
               plot(q.price)\n\
               plot(i.index)\n\
               plot(i.price)\n\
               plot(na(i.time) ? 1.0 : 0.0)\n\
               plot(t.time)\n\
               plot(t.price)\n\
               plot(na(t.index) ? 1.0 : 0.0)\n\
               plot(n.time == time and n.index == bar_index and n.price == close ? 1.0 : 0.0)\n";
    let outcome = run_outcome(src, &[1.0], &RunOptions::default());
    assert!(outcome.errors.is_empty(), "errors: {:?}", outcome.errors);
    let values: Vec<_> = outcome
        .plots
        .iter()
        .map(|plot| floats(&plot.values)[0])
        .collect();
    assert_eq!(
        values,
        vec![
            Some(1000.0),
            Some(7.0),
            Some(2.5),
            Some(1000.0),
            Some(7.0),
            Some(2.5),
            Some(8.0),
            Some(3.5),
            Some(1.0),
            Some(2000.0),
            Some(4.5),
            Some(1.0),
            Some(1.0),
        ]
    );
}

