#[test]
fn security_helper_history_preserves_input_source_overrides_and_constant_offsets() {
    use pinewasm_hir::BuiltinSeries;
    let program = compile("//@version=6\nindicator(\"S\")\nsrc = input.source(close)\nf(s, n) => request.security(syminfo.tickerid, \"1W\", s[n])\ng(s, n) => f(s, n + 1)\nplot(f(src, 1))\nplot(request.security(syminfo.tickerid, \"1W\", src[1]))\nplot(g(src, 1))\nplot(request.security(syminfo.tickerid, \"1W\", src[2]))\nplot(f(src, 0))\nplot(request.security(syminfo.tickerid, \"1W\", src))\n");
    let mut data = nineteen_daily_closes();
    data.open = data.close.iter().map(|price| price - 10.0).collect();
    for (source, expected) in [(BuiltinSeries::Close, 113.0), (BuiltinSeries::Open, 97.0)] {
        let mut options = RunOptions::default();
        options
            .inputs
            .insert(0, pinewasm_hir::InputValue::Source(source));
        let outcome = run(&program, &data, &options);
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        for (helper, direct) in [(0, 1), (2, 3), (4, 5)] {
            assert_eq!(outcome.plots[helper].values, outcome.plots[direct].values);
        }
        assert_eq!(floats(&outcome.plots[0].values)[18], Some(expected));
        assert_eq!(floats(&outcome.plots[2].values)[18], Some(expected - 7.0));
    }
}

