#[test]
fn security_input_history_binds_selected_offset_in_direct_and_nested_helpers() {
    let program = compile("//@version=6\nindicator(\"S\")\nn = input.int(1)\nalias = n\nf(s, n) => request.security(syminfo.tickerid, \"1W\", s[n])\ng(s, n) => f(s, n)\nplot(request.security(syminfo.tickerid, \"1W\", close[n]))\nplot(g(close, alias))\nplot(request.security(syminfo.tickerid, \"1W\", ta.sma(close, 2)[n]))\nplot(g(ta.sma(close, 2), n))\n");
    let data = nineteen_daily_closes();
    for offset in [0, 1, 2] {
        let reference = compile(&format!("//@version=6\nindicator(\"R\")\nplot(request.security(syminfo.tickerid, \"1W\", close[{offset}]))\nplot(request.security(syminfo.tickerid, \"1W\", ta.sma(close, 2)[{offset}]))\n"));
        let expected = run(&reference, &data, &RunOptions::default());
        let mut options = RunOptions::default();
        options
            .inputs
            .insert(0, pinewasm_hir::InputValue::Int(offset));
        let actual = run(&program, &data, &options);
        assert!(actual.errors.is_empty(), "{:?}", actual.errors);
        for (plot, reference) in [(0, 0), (1, 0), (2, 1), (3, 1)] {
            assert_eq!(
                actual.plots[plot].values, expected.plots[reference].values,
                "offset {offset}, plot {plot}"
            );
        }
        assert_eq!(
            floats(&actual.plots[0].values)[18],
            Some([118.0, 113.0, 106.0][offset as usize])
        );
    }
    let mut options = RunOptions::default();
    options.inputs.insert(0, pinewasm_hir::InputValue::Int(-1));
    let negative = run(&program, &data, &options);
    assert!(negative.errors.is_empty(), "{:?}", negative.errors);
    assert!(negative
        .plots
        .iter()
        .all(|plot| floats(&plot.values).iter().all(Option::is_none)));
    options
        .inputs
        .insert(0, pinewasm_hir::InputValue::Int(i64::MAX));
    let huge = run(&program, &data, &options);
    assert!(
        huge.errors
            .iter()
            .any(|error| error.kind == RuntimeErrorKind::HistoryBufferLimitExceeded),
        "{:?}",
        huge.errors
    );
}

#[test]
fn security_input_history_arithmetic_preserves_fractional_indices_and_exact_ints() {
    let program = compile(
        r#"//@version=6
indicator("Arithmetic history")
n = input.int(1)
fraction = input.float(0.25)
huge = input.int(9223372036854775807)
f(src, offset) => request.security(syminfo.tickerid, "1W", src[offset])
plot(request.security(syminfo.tickerid, "1W", close[n / 2]))
plot(f(close, n / 2))
plot(request.security(syminfo.tickerid, "1W", close[(n / 2) * 2]))
plot(f(close, (n / 2) * 2))
plot(request.security(syminfo.tickerid, "1W", close[int(n / 2) * 2]))
plot(f(close, int(fraction * 2)))
plot(f(close, n % 2))
plot(f(close, n / 0))
plot(f(close, huge - huge + n))
plot(request.security(syminfo.tickerid, "1W", close[(1 / 2) * 2]))
"#,
    );
    let data = nineteen_daily_closes();
    for (n, fraction, offsets) in [
        (1, 0.25, [0, 0, 1, 1, 0, 0, 1, 0, 1, 1]),
        (2, 0.5, [1, 1, 2, 2, 2, 1, 0, 0, 2, 1]),
        (3, 1.25, [1, 1, 3, 3, 2, 2, 1, 0, 3, 1]),
    ] {
        let mut options = RunOptions::default();
        options.inputs.insert(0, pinewasm_hir::InputValue::Int(n));
        options
            .inputs
            .insert(1, pinewasm_hir::InputValue::Float(fraction));
        let actual = run(&program, &data, &options);
        assert!(actual.errors.is_empty(), "{:?}", actual.errors);
        for (plot, offset) in offsets.into_iter().enumerate() {
            if plot == 7 {
                assert!(floats(&actual.plots[plot].values)
                    .iter()
                    .all(Option::is_none));
                continue;
            }
            let reference = compile(&format!("//@version=6\nindicator(\"R\")\nplot(request.security(syminfo.tickerid, \"1W\", close[{offset}]))\n"));
            let expected = run(&reference, &data, &RunOptions::default());
            assert_eq!(
                actual.plots[plot].values, expected.plots[0].values,
                "n {n}, fraction {fraction}, plot {plot}"
            );
            assert_eq!(
                floats(&actual.plots[plot].values)[18],
                [Some(118.0), Some(113.0), Some(106.0), None][offset]
            );
        }
    }
}

#[test]
fn security_input_history_binding_work_obeys_instruction_budget() {
    use pinewasm_hir::{BinOp, HtfExpr, HtfHistoryOffset as O};
    fn tree(depth: u32) -> O {
        if depth == 0 {
            O::InputInt {
                input: 0,
                default: 0,
            }
        } else {
            O::Binary {
                op: BinOp::Add,
                lhs: Box::new(tree(depth - 1)),
                rhs: Box::new(tree(depth - 1)),
            }
        }
    }
    let original = compile("//@version=6\nindicator(\"S\")\nn = input.int(0)\nplot(request.security(syminfo.tickerid, \"1W\", close[n]))\n");
    let mut expanded = original.clone();
    let mut changed = false;
    for instr in &mut expanded.functions[0].code {
        if let pinewasm_csil::CsilInstr::ReadSecurityExpr {
            expr: HtfExpr::HistoryInput { offset, .. },
            ..
        } = instr
        {
            *offset = tree(9);
            changed = true;
        }
    }
    assert!(changed);
    let data = nineteen_daily_closes();
    let expected = run(&original, &data, &RunOptions::default());
    let actual = run(&expanded, &data, &RunOptions::default());
    assert!(actual.errors.is_empty(), "{:?}", actual.errors);
    assert_eq!(actual.plots[0].values, expected.plots[0].values);
    let options = RunOptions {
        max_instructions_per_bar: 100,
        ..RunOptions::default()
    };
    assert!(run(&original, &data, &options).errors.is_empty());
    let limited = run(&expanded, &data, &options);
    assert!(
        limited
            .errors
            .iter()
            .any(|error| error.kind == RuntimeErrorKind::InstructionLimitExceeded),
        "{:?}",
        limited.errors
    );
}

#[test]
fn security_calendar_week_preserves_unit_and_distinct_memo_keys() {
    let source = "//@version=6\nindicator(\"W versus D\")\nplot(request.security(syminfo.tickerid, \"1W\", close, lookahead=barmerge.lookahead_on))\nplot(request.security(syminfo.tickerid, \"7D\", close, lookahead=barmerge.lookahead_on))\nplot(request.security(syminfo.tickerid, \"1W\", close + 0, lookahead=barmerge.lookahead_on))\nplot(request.security(syminfo.tickerid, \"7D\", close + 0, lookahead=barmerge.lookahead_on))\n";
    let data = data_from_close(&(100..116).map(f64::from).collect::<Vec<_>>());
    let program = compile(source);
    let encoded = serde_json::to_string(&program).unwrap();
    let restored: pinewasm_csil::CsilProgram = serde_json::from_str(&encoded).unwrap();
    let actual = run(&restored, &data, &RunOptions::default());
    assert!(actual.errors.is_empty(), "{:?}", actual.errors);
    let weekly = floats(&actual.plots[0].values);
    let fixed = floats(&actual.plots[1].values);
    assert_eq!(
        weekly,
        [
            vec![Some(104.0); 5],
            vec![Some(111.0); 7],
            vec![Some(115.0); 4]
        ]
        .concat()
    );
    assert_eq!(
        fixed,
        [
            vec![Some(106.0); 7],
            vec![Some(113.0); 7],
            vec![Some(115.0); 2]
        ]
        .concat()
    );
    assert_eq!(weekly, floats(&actual.plots[2].values));
    assert_eq!(fixed, floats(&actual.plots[3].values));
    let selected = compile("//@version=6\nindicator(\"Selected calendar\")\ntf=input.timeframe(\"1W\")\nplot(request.security(syminfo.tickerid, tf, close, lookahead=barmerge.lookahead_on))\n");
    for tf in ["1W", "7D", "2W", "3W", "4W"] {
        let literal = compile(&format!("//@version=6\nindicator(\"Literal\")\nplot(request.security(syminfo.tickerid, \"{tf}\", close, lookahead=barmerge.lookahead_on))\n"));
        let mut options = RunOptions::default();
        options
            .inputs
            .insert(0, pinewasm_hir::InputValue::String(tf.into()));
        let actual = run(&selected, &data, &options);
        let expected = run(&literal, &data, &RunOptions::default());
        assert!(actual.errors.is_empty(), "{tf}: {:?}", actual.errors);
        assert_eq!(actual.plots[0].values, expected.plots[0].values, "{tf}");
    }
}

#[test]
fn conditional_tuple_na_components_preserve_integer_type_and_history() {
    let source = r#"//@version=6
indicator("S")
f(mode) =>
    switch mode
        0 => [close, 3]
        1 => [na, na]
        => [open, 5]
[a, b] = f(bar_index % 3)
plot(a)
plot(b)
plot(b[1])
plot(b == 3 ? 1 : 0)
[c, exact] = switch bar_index % 3
    0 => [close, 9007199254740993]
    1 => [na, na]
    => [open, 9007199254740992]
plot(exact == 9007199254740993 ? 1 : 0)
"#;
    let out = run(
        &compile(source),
        &data_from_close(&[10., 20., 30., 40., 50., 60.]),
        &RunOptions::default(),
    );
    assert!(out.errors.is_empty(), "{:?}", out.errors);
    assert_eq!(
        floats(&out.plots[0].values),
        vec![Some(10.), None, Some(30.), Some(40.), None, Some(60.)]
    );
    assert_eq!(
        floats(&out.plots[1].values),
        vec![Some(3.), None, Some(5.), Some(3.), None, Some(5.)]
    );
    assert_eq!(
        floats(&out.plots[2].values),
        vec![None, Some(3.), None, Some(5.), Some(3.), None]
    );
    assert_eq!(
        floats(&out.plots[3].values),
        [1., 0., 0., 1., 0., 0.].map(Some)
    );
    assert_eq!(
        floats(&out.plots[4].values),
        [1., 0., 0., 1., 0., 0.].map(Some)
    );
}
#[test]
fn vertical_gradient_fill_preserves_series_values_and_colors() {
    let named = "fill(a, b, top_value=close, bottom_value=-close, top_color=color.blue, bottom_color=color.new(color.blue, 100))";
    let positional = "fill(a, b, close, -close, color.blue, color.new(color.blue, 100))";
    for call in [named, positional] {
        let source =
            format!("//@version=6\nindicator(\"Gradient\")\na=plot(close)\nb=plot(0)\n{call}\n");
        let result = run_outcome(&source, &[10.0, 20.0], &RunOptions::default());
        assert!(result.errors.is_empty(), "{:?}", result.errors);
        let fill = &result.fills[0];
        assert_eq!(fill.colors.len(), 4);
        assert_eq!(floats(&fill.colors[0].values), vec![Some(10.0), Some(20.0)]);
        assert_eq!(
            floats(&fill.colors[1].values),
            vec![Some(-10.0), Some(-20.0)]
        );
        assert_eq!(fill.colors[2].role, pinewasm_hir::PlotColorRole::TopColor);
        assert_eq!(
            fill.colors[3].role,
            pinewasm_hir::PlotColorRole::BottomColor
        );
    }
}

