#[test]
fn prepared_float_overrides_install_resolved_params() {
    use crate::{PreparedProgram, Vm};
    use pinewasm_hir::{InputValue, TaInputTarget};
    use std::sync::Arc;
    let data = data_from_close(&[2.0, 7.0, 4.0, 11.0, 3.0, 9.0]);
    for (source, overrides) in [
        ("//@version=6\nindicator('ALMA offset')\nx = input.float(0.85)\nplot(ta.alma(close, 3, x, 6))\nplot(ta.alma(close, 4, x, 6))\n", vec![(InputValue::Float(0.1), false), (InputValue::Float(0.85), true), (InputValue::Bool(true), true), (InputValue::Int(0), true)]),
        ("//@version=6\nindicator('ALMA integer offset')\nx = input.int(1)\nplot(ta.alma(close, 3, x, 6))\n", vec![(InputValue::Int(0), false), (InputValue::Int(1), true), (InputValue::Float(0.1), true)]),
        ("//@version=6\nindicator('Percent')\nx = input.float(50.0)\nplot(ta.percentile_nearest_rank(close, 3, x))\n", vec![(InputValue::Float(25.0), false), (InputValue::Float(50.0), true), (InputValue::Float(0.0), false), (InputValue::Float(100.0), false), (InputValue::Bool(false), true)]),
        ("//@version=6\nindicator('Signed zero')\nx = input.float(0.0)\nplot(ta.alma(close, 3, x, 6))\n", vec![(InputValue::Float(-0.0), false), (InputValue::Float(0.0), true)]),
    ] {
        let program = compile(source);
        let prepared = PreparedProgram::new(program.clone()).unwrap();
        assert!(!program.ta_input_bindings.is_empty());
        for (value, reuse) in overrides {
            let mut options = RunOptions::default();
            options.inputs.insert(0, value);
            let vm = Vm::new_owned(&prepared.program, Some(&prepared.program), &data, &options).unwrap();
            assert_eq!(Arc::ptr_eq(&prepared.program, &vm.program), reuse, "{source}");
            for binding in &program.ta_input_bindings {
                let TaInputTarget::State { state, param } = binding.target else { panic!("expected State binding") };
                let selected = program.resolve_ta_input(binding, options.inputs.get(&binding.input)).unwrap();
                assert_eq!(vm.program.ta_states[state as usize].params[param as usize], selected);
            }
            assert_eq!(serde_json::to_value(prepared.run(&data, &options)).unwrap(), serde_json::to_value(crate::run(&program, &data, &options)).unwrap());
        }
    }
}

#[test]
fn prepared_float_rejections_and_duplicate_target_admission() {
    use crate::PreparedProgram;
    use pinewasm_hir::InputValue;
    let data = data_from_close(&[2.0, 7.0, 4.0, 11.0]);
    for (source, invalid) in [
        ("//@version=6\nindicator('Sigma')\nx = input.float(6.0)\nplot(ta.alma(close, 3, 0.85, x))\n", vec![0.0, -1.0, f64::INFINITY, f64::NAN]),
        ("//@version=6\nindicator('Percent')\nx = input.float(50.0)\nplot(ta.percentile_nearest_rank(close, 3, x))\n", vec![-1.0, 101.0, f64::INFINITY, f64::NAN]),
    ] {
        let program = compile(source);
        let prepared = PreparedProgram::new(program.clone()).unwrap();
        for value in invalid {
            let mut options = RunOptions::default(); options.inputs.insert(0, InputValue::Float(value));
            let actual = prepared.run(&data, &options); let expected = crate::run(&program, &data, &options);
            assert!(!actual.errors.is_empty());
            assert_eq!(serde_json::to_value(actual).unwrap(), serde_json::to_value(expected).unwrap());
        }
        let mut duplicate = program.clone(); duplicate.ta_input_bindings.push(duplicate.ta_input_bindings[0]);
        assert!(PreparedProgram::new(duplicate).is_err(), "duplicate target is outside admitted prepared domain");
    }
}

#[test]
fn color_input_origin_tracks_selected_equal_rgba_branch_and_history() {
    let source = r#"//@version=6
indicator("Palette identity")
a = input.color(#ff0000, "A")
b = input.color(#ff0000, "B")
selected = bar_index % 2 == 0 ? a : b
plot(close, color=selected)
plot(close, color=selected[1])
plot(a == b ? 1 : 0)
"#;
    let outcome = run_outcome(source, &[10.0, 11.0, 12.0, 13.0], &RunOptions::default());
    assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
    let origins = |values: &[Value]| {
        values
            .iter()
            .map(|v| match v {
                Value::Color { input_origin, .. } => *input_origin,
                Value::Na => None,
                other => panic!("unexpected paint {other:?}"),
            })
            .collect::<Vec<_>>()
    };
    assert_eq!(
        origins(&outcome.plots[0].colors[0].values),
        vec![Some(0), Some(1), Some(0), Some(1)]
    );
    assert_eq!(
        outcome.plots[0].colors[0].palette_indices,
        vec![Some(0), Some(1), Some(0), Some(1)]
    );
    let wire = serde_json::to_value(&outcome).unwrap();
    assert_eq!(
        wire["plots"][0]["colors"][0]["paletteIndices"],
        serde_json::json!([0, 1, 0, 1])
    );
    assert_eq!(
        wire["plots"][0]["colors"][0]["values"],
        serde_json::json!(["#FF0000", "#FF0000", "#FF0000", "#FF0000"])
    );
    assert_eq!(
        origins(&outcome.plots[1].colors[0].values),
        vec![None, Some(0), Some(1), Some(0)]
    );
    assert_eq!(floats(&outcome.plots[2].values), vec![Some(1.0); 4]);
}

#[test]
fn color_input_origin_survives_realtime_heap_rollback_and_varip() {
    let program = compile(
        r#"//@version=6
indicator("Palette rollback")
a = input.color(#ff0000, "A")
b = input.color(#ff0000, "B")
var held = a
varip live = a
var colors = array.new_color(1, a)
if close > 11
    held := b
    live := b
    array.set(colors, 0, b)
plot(close, color=held)
plot(close, color=live)
plot(close, color=color(array.get(colors, 0)))
plot(close, color=color.new(held, 0))
"#,
    );
    let data = data_from_close(&[10.0, 10.0]);
    let options = RunOptions {
        realtime: Some(RealtimeSim {
            ticks: vec![tick(2, 12.0, false), tick(2, 9.0, true)],
        }),
        ..RunOptions::default()
    };
    let outcome = crate::run(&program, &data, &options);
    assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
    let origins = |index: usize| {
        outcome.plots[index].colors[0]
            .values
            .iter()
            .map(|v| match v {
                Value::Color { input_origin, .. } => *input_origin,
                other => panic!("unexpected paint {other:?}"),
            })
            .collect::<Vec<_>>()
    };
    assert_eq!(origins(0), vec![Some(0), Some(0), Some(0)]);
    assert_eq!(origins(1), vec![Some(0), Some(0), Some(1)]);
    assert_eq!(origins(2), vec![Some(0), Some(0), Some(0)]);
    // Calculating a color creates paint, rather than retaining raw input identity.
    assert_eq!(origins(3), vec![None, None, None]);
}

#[test]
fn color_input_origin_wire_covers_all_output_families_and_gradient_domains() {
    let source = r#"//@version=6
indicator("Palette roles")
a = input.color(#ff0000, "A")
b = input.color(#ff0000, "B")
selected = bar_index % 2 == 0 ? a : b
p = plot(close, color=selected)
q = plot(close + 1, color=b)
plotcandle(open, high, low, close, color=selected, wickcolor=a, bordercolor=b)
bgcolor(selected)
barcolor(b)
fill(p, q, color=selected)
fill(p, q, top_value=close + 1, bottom_value=close, top_color=a, bottom_color=b)
"#;
    let outcome = run_outcome(source, &[10.0, 11.0, 12.0], &RunOptions::default());
    assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
    let channels: Vec<_> = outcome
        .plots
        .iter()
        .flat_map(|p| &p.colors)
        .chain(outcome.visuals.iter().flat_map(|v| &v.colors))
        .chain(outcome.fills.iter().flat_map(|f| &f.colors))
        .collect();
    assert!(
        channels.len() >= 10,
        "expected plot, candle, visual and fill roles"
    );
    let mut numeric_roles = 0;
    for channel in channels {
        assert_eq!(channel.palette_indices.len(), channel.values.len());
        assert_eq!(channel.palette_indices.len(), 3);
        for (value, origin) in channel.values.iter().zip(&channel.palette_indices) {
            match value {
                Value::Color { input_origin, .. } => {
                    assert!(origin.is_some());
                    assert!(matches!(input_origin, Some(0 | 1)));
                }
                Value::Float(_) => {
                    assert_eq!(channel.role.value_domain(), "float-or-na");
                    assert_eq!(*origin, None);
                }
                other => panic!("unexpected lane value {other:?}"),
            }
        }
        if channel.role.value_domain() == "float-or-na" {
            numeric_roles += 1;
        }
        let json = serde_json::to_value(channel).unwrap();
        assert_eq!(json["paletteIndices"].as_array().unwrap().len(), 3);
    }
    assert_eq!(numeric_roles, 2);
}

#[test]
fn constant_palette_origins_preserve_fractional_transparency_before_rgba_quantization() {
    let program = compile(
        r#"//@version=6
indicator("Constant palette identity")
a = color.new(#ff0000, 50.01)
b = color.new(#ff0000, 50.02)
plot(close, color=bar_index % 2 == 0 ? a : b)
"#,
    );
    let outcome = crate::run(
        &program,
        &data_from_close(&[10.0, 11.0, 12.0]),
        &RunOptions::default(),
    );
    assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
    assert!(outcome.plots[0].style.color_editable);
    let palette = &program.plots[0].style.color_palette;
    assert_eq!(palette.len(), 2);
    assert_ne!(palette[0].source, palette[1].source);
    let paints = &outcome.plots[0].colors[0].values;
    assert_ne!(paints[0], paints[1]);
    let wire = serde_json::to_value(paints).unwrap();
    assert_eq!(wire[0], wire[1]);
    assert_eq!(
        outcome.plots[0].colors[0].palette_indices,
        vec![Some(0), Some(1), Some(0)]
    );
    let wire = serde_json::to_value(&outcome.plots[0].colors[0]).unwrap();
    assert_eq!(wire["paletteIndices"], serde_json::json!([0, 1, 0]));
}
